INSERT INTO public.custom_certificates (
  id, name, code, description, difficulty, estimated_hours, color_class, icon_name, is_vip, is_disabled, badge
) VALUES (
  'dp-900', 'Microsoft Azure Data Fundamentals', 'DP-900', 'Chinh phục chứng chỉ Microsoft Azure Data Fundamentals (DP-900). Nắm vững các khái niệm dữ liệu cốt lõi, dữ liệu quan hệ và phi quan hệ trên Azure, cùng các giải pháp phân tích dữ liệu hiện đại.',
  'Cơ bản', '8-12 Giờ', 'bg-gradient-to-br from-emerald-600 via-teal-700 to-slate-900 text-white', 'Database',
  false, true, 'new'
) ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name, code = EXCLUDED.code, description = EXCLUDED.description,
  difficulty = EXCLUDED.difficulty, estimated_hours = EXCLUDED.estimated_hours,
  color_class = EXCLUDED.color_class, icon_name = EXCLUDED.icon_name, badge = EXCLUDED.badge;

INSERT INTO public.questions (
  id, cert_id, question_number, text, options,
  correct_answers, explanation, category, tags, image_url, status
) VALUES
  ('dp900-1', 'dp-900', 1, 'Which Azure storage solution natively supports POSIX-compliant access control lists (ACLs)?', '[{"key":"A","text":"Azure Table storage"},{"key":"B","text":"Azure Data Lake Storage"},{"key":"C","text":"Azure Queue storage"},{"key":"D","text":"Azure Files"}]'::jsonb, ARRAY['B']::text[], 'Azure Data Lake Storage hỗ trợ danh sách kiểm soát truy cập chi tiết cho các tệp và thư mục thông qua không gian tên phân cấp của nó, sử dụng mô hình POSIX ACL cùng với Azure RBAC. [Microsoft Learn: Access control model in Azure Data Lake Storage](https://learn.microsoft.com/en-us/azure/storage/blobs/data-lake-storage-access-control-model)', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-2', 'dp-900', 2, 'Select the answer that correctly finishes the sentence.', '[]'::jsonb, ARRAY[]::text[], 'JSON lưu trữ các trường được đặt tên và có thể chứa các đối tượng và mảng lồng nhau mà không yêu cầu lược đồ quan hệ cố định, vì vậy đây là dữ liệu bán cấu trúc.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-3', 'dp-900', 3, 'Match the Azure services with the appropriate locations in the architecture.  
  
Each service may be used once, multiple times, or not at all.', '{"statements":[{"id":"etl_service","text":"Extract Transform Load (ETL)","correctAnswer":"B"},{"id":"data_warehouse_service","text":"Data warehouse","correctAnswer":"E"}],"choices":[{"key":"A","text":"Azure Analysis Services"},{"key":"B","text":"Azure Data Factory"},{"key":"C","text":"Azure Table storage"},{"key":"D","text":"Azure Cosmos DB"},{"key":"E","text":"Azure Synapse Analytics"}]}'::jsonb, ARRAY['etl_service=B', 'data_warehouse_service=E']::text[], 'Azure Data Factory là dịch vụ tích hợp dữ liệu được quản lý dùng để tạo, lên lịch và điều phối các đường dẫn ETL/ELT. Azure Synapse Analytics cung cấp kho dữ liệu doanh nghiệp thông qua nhóm SQL chuyên dụng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-4', 'dp-900', 4, 'Which type of non-relational data store supports a flexible schema, stores data as JSON files, and keeps all data for an entity within the same document?', '[{"key":"A","text":"document"},{"key":"B","text":"columnar"},{"key":"C","text":"graph"},{"key":"D","text":"time series"}]'::jsonb, ARRAY['A']::text[], 'Kho lưu trữ dữ liệu tài liệu sử dụng các tài liệu linh hoạt giống JSON và có thể lưu giữ dữ liệu liên quan của một thực thể trong một tài liệu duy nhất.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-5', 'dp-900', 5, 'Question 5', '[]'::jsonb, ARRAY[]::text[], 'Azure SQL Managed Instance là công cụ cơ sở dữ liệu PaaS được quản lý hoàn toàn, sử dụng mô hình triển khai ở phạm vi phiên bản. Nó hỗ trợ nhiều cơ sở dữ liệu trong một phiên bản và các công việc của Tác nhân SQL Server, không giống như Azure SQL Database, trong đó Tác nhân SQL Server không khả dụng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-6', 'dp-900', 6, 'Match the security components to their appropriate scenarios.  
  
Each component may be used once, more than once, or not at all.', '{"statements":[{"id":"slot1","text":"Prevent access to an Azure SQL database from another network.","correctAnswer":"B"},{"id":"slot2","text":"Support Azure Active Directory (Azure AD) sign-ins to an Azure SQL database.","correctAnswer":"A"},{"id":"slot3","text":"Ensure that sensitive data never appears as plain text in an Azure SQL database.","correctAnswer":"C"}],"choices":[{"key":"A","text":"Authentication"},{"key":"B","text":"Firewall"},{"key":"C","text":"Encryption"}]}'::jsonb, ARRAY['slot1=B', 'slot2=A', 'slot3=C']::text[], 'Quy tắc tường lửa Azure SQL kiểm soát kết nối mạng bằng địa chỉ IP và quy tắc mạng ảo. Xác thực Azure AD (Microsoft Entra ID) cung cấp thông tin đăng nhập dựa trên danh tính vào Azure SQL. Mã hóa bảo vệ dữ liệu cơ sở dữ liệu nhạy cảm ở phần còn lại khỏi bị lưu trữ dưới dạng văn bản gốc có thể đọc được.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-7', 'dp-900', 7, 'For each of the following statements, select **Yes** if the statement is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"You must apply operating system updates to Azure SQL databases regularly.","correctAnswer":"No"},{"id":"2","text":"You need a Microsoft 365 subscription to create an Azure SQL database.","correctAnswer":"No"},{"id":"3","text":"You can use existing Microsoft SQL Server licenses to reduce the cost of Azure SQL databases.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:No', '3:Yes']::text[], 'Azure SQL Database được quản lý hoàn toàn: Microsoft vá và cập nhật mã hệ điều hành và SQL cơ bản. Đăng ký Microsoft 365 không phải là điều kiện tiên quyết đối với tài nguyên Azure. Azure Hybrid Benefit có thể áp dụng giấy phép SQL Server đủ điều kiện để giảm chi phí cấp phép Azure SQL Database.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-8', 'dp-900', 8, 'Which clause should be used in a `SELECT` statement to combine rows from one table with rows from another table?', '[{"key":"A","text":"SET"},{"key":"B","text":"VALUES"},{"key":"C","text":"KEY"},{"key":"D","text":"JOIN"}]'::jsonb, ARRAY['D']::text[], 'Mệnh đề `JOIN` kết hợp các hàng từ các bảng riêng biệt, thường bằng cách khớp các giá trị cột liên quan thông qua điều kiện nối.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-9', 'dp-900', 9, 'Match the analytics types that can be used to answer the business questions. Each analytics type may be used once, more than once, or not at all.', '{"statements":[{"id":"sales_increase","text":"Why did sales increase last month?","correctAnswer":"B"},{"id":"budget_allocation","text":"How do I allocate my budget to buy different inventory items?","correctAnswer":"E"},{"id":"people_mentions","text":"Which people are mentioned in a company''s business documents?","correctAnswer":"A"}],"choices":[{"key":"A","text":"Cognitive"},{"key":"B","text":"Diagnostic"},{"key":"C","text":"Descriptive"},{"key":"D","text":"Predictive"},{"key":"E","text":"Prescriptive"}]}'::jsonb, ARRAY['sales_increase=B', 'budget_allocation=E', 'people_mentions=A']::text[], 'Phân tích chẩn đoán xác định nguyên nhân của các kết quả trong quá khứ. Phân tích theo quy định đề xuất các quyết định như phân bổ ngân sách. Phân tích nhận thức có thể áp dụng xử lý ngôn ngữ tự nhiên để trích xuất những người được đặt tên từ các tài liệu kinh doanh phi cấu trúc.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-10', 'dp-900', 10, 'Question 10', '[]'::jsonb, ARRAY[]::text[], 'PolyBase truy cập dữ liệu ngoài trong Azure Blob Storage và Azure Data Lake Storage bằng cách sử dụng Transact-SQL, cho phép nhóm Synapse SQL tải hoặc truy vấn dữ liệu đó.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-11', 'dp-900', 11, 'For each statement below, select **Yes** when it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"A job that processes sales data once daily is an example of a batch workload.","correctAnswer":"Yes"},{"id":"2","text":"A job that calculates a rolling average temperature reading is an example of a streaming workload.","correctAnswer":"Yes"},{"id":"3","text":"A job that calculates average revenue per product for the last month is an example of a streaming workload.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:Yes', '3:No']::text[], 'Quá trình xử lý hàng ngày và tổng hợp doanh thu tháng trước hoạt động dựa trên dữ liệu được thu thập trong một khoảng thời gian xác định, do đó chúng là khối lượng công việc theo đợt. Giá trị trung bình luân phiên của các chỉ số nhiệt độ được cập nhật khi có các chỉ số mới, đây là khối lượng công việc phát trực tuyến.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-12', 'dp-900', 12, 'For each statement below, select **Yes** when it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"Relational database tables contain columns and rows","correctAnswer":"Yes"},{"id":"2","text":"Indexes in a relational database describe the data types in a table","correctAnswer":"No"},{"id":"3","text":"A database view is a virtual table whose content is defined by a query","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:Yes']::text[], 'Các bảng quan hệ bao gồm các hàng và cột. Các chỉ mục hỗ trợ truy cập dữ liệu hiệu quả hơn là xác định các kiểu dữ liệu cột thuộc về lược đồ bảng. Chế độ xem là một bảng ảo có kết quả được xác định bằng một truy vấn.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-13', 'dp-900', 13, 'Which statement is an example of Data Definition Language (DDL)?', '[{"key":"A","text":"SELECT"},{"key":"B","text":"INSERT"},{"key":"C","text":"CREATE"},{"key":"D","text":"MERGE"}]'::jsonb, ARRAY['C']::text[], 'Câu lệnh CREATE xác định một đối tượng cơ sở dữ liệu, chẳng hạn như bảng, dạng xem hoặc lược đồ, vì vậy đây là lệnh Ngôn ngữ định nghĩa dữ liệu.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-14', 'dp-900', 14, 'Question 14', '[]'::jsonb, ARRAY[]::text[], 'Quản trị viên cơ sở dữ liệu chịu trách nhiệm vận hành và duy trì cơ sở dữ liệu, bao gồm định cấu hình, thực hiện và xác thực các quy trình sao lưu và khôi phục.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-15', 'dp-900', 15, 'Select the answer that correctly finishes the sentence.', '[]'::jsonb, ARRAY[]::text[], 'Power BI Desktop là công cụ soạn thảo đầy đủ tính năng để kết nối với dữ liệu, chuyển đổi dữ liệu, xây dựng mô hình dữ liệu và tạo hoặc chỉnh sửa báo cáo. Dịch vụ Power BI tập trung vào xuất bản, chia sẻ và cộng tác trên nội dung đó và ứng dụng điện thoại dành cho thiết bị di động.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-16', 'dp-900', 16, 'HOTSPOT – Select the answer that correctly completes the sentence.', '[]'::jsonb, ARRAY[]::text[], 'SQL Server trên Azure Virtual Machines là một sản phẩm IaaS. Nó cung cấp quyền kiểm soát quản trị đối với phiên bản SQL Server và hệ điều hành cơ bản, với trách nhiệm liên quan là quản lý máy ảo.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-17', 'dp-900', 17, 'For each of the following statements, select **Yes** if the statement is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"A pipeline is a representation of a data structure within Azure Data Factory","correctAnswer":"No"},{"id":"2","text":"Azure Data Factory pipelines can execute other pipelines","correctAnswer":"Yes"},{"id":"3","text":"A processing step within an Azure Data Factory pipeline is an activity","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:Yes', '3:Yes']::text[], 'Trong Azure Data Factory, quy trình là một nhóm hoạt động hợp lý; một tập dữ liệu đại diện cho cấu trúc dữ liệu trong kho dữ liệu. Hoạt động Đường ống thực thi có thể gọi một đường ống khác và một hoạt động là một bước xử lý trong đường ống.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-18', 'dp-900', 18, 'You intend to deploy an app. The app needs a nonrelational data service that provides latency guarantees of less than 10 ms for reads and writes.  
  
What should you include in the solution?', '[{"key":"A","text":"Azure Blob storage"},{"key":"B","text":"Azure Files"},{"key":"C","text":"Azure Table storage"},{"key":"D","text":"Azure Cosmos DB"}]'::jsonb, ARRAY['D']::text[], 'Azure Cosmos DB là dịch vụ cơ sở dữ liệu phi quan hệ cung cấp độ trễ dưới 10 mili giây được hỗ trợ SLA cho hoạt động đọc và ghi ở phân vị thứ 99 trong các cấu hình hiện hành, đáp ứng đảm bảo độ trễ thấp bắt buộc.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-19', 'dp-900', 19, 'For each of the following statements, select Yes if the statement is true. Otherwise, select No.', '{"statements":[{"id":"1","text":"In a transactional database that guarantees atomicity, all statements in a transaction must complete successfully or the transaction must roll back.","correctAnswer":"Yes"},{"id":"2","text":"In a transactional database that guarantees consistency, all data changes will be logged and accounted for.","correctAnswer":"No"},{"id":"3","text":"In a transactional database that guarantees isolation, processes can see only data in a consistent state.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:Yes']::text[], 'Atomicity thực hiện một giao dịch được tất cả hoặc không có gì. Tính nhất quán duy trì tính toàn vẹn của dữ liệu và các ràng buộc về cơ sở dữ liệu, trong khi các thay đổi trong việc ghi nhật ký có liên quan đến độ bền. Sự cô lập ngăn các quá trình đồng thời nhìn thấy kết quả giao dịch không đầy đủ, do đó chúng thấy được dữ liệu nhất quán.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-20', 'dp-900', 20, 'For each of the following statements, select **Yes** if it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"Platform as a service (PaaS) database offerings in Azure provide built-in high availability.","correctAnswer":"Yes"},{"id":"2","text":"Platform as a service (PaaS) database offerings in Azure provide configurable scaling options.","correctAnswer":"Yes"},{"id":"3","text":"Platform as a service (PaaS) database offerings in Azure reduce the administrative overhead for managing hardware.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:Yes', '3:Yes']::text[], 'Các dịch vụ cơ sở dữ liệu Azure PaaS cung cấp tính sẵn sàng cao được quản lý, hỗ trợ mở rộng quy mô tài nguyên điện toán và lưu trữ cũng như chuyển dịch quản lý cơ sở hạ tầng cơ bản—bao gồm cả phần cứng—sang Microsoft. Do đó cả ba phát biểu đều đúng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-21', 'dp-900', 21, 'Your company has a reporting solution containing paginated reports. The reports query a dimensional model in a data warehouse.  
  
Which type of processing does the reporting solution use?', '[{"key":"A","text":"stream processing"},{"key":"B","text":"batch processing"},{"key":"C","text":"Online Analytical Processing (OLAP)"},{"key":"D","text":"Online Transaction Processing (OLTP)"}]'::jsonb, ARRAY['C']::text[], 'Xử lý phân tích trực tuyến (OLAP) hỗ trợ báo cáo phân tích và truy vấn trên các mô hình dữ liệu thứ nguyên trong dữ liệu warehouse.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-22', 'dp-900', 22, 'You are provided with the following data.  
  
![Question Image](https://cdn.examcademy.com/images/questions/1783775282127-9chcmk0r.png)  
  
What type of data is this?', '[{"key":"A","text":"unstructured"},{"key":"B","text":"semi-structured"},{"key":"C","text":"structured"}]'::jsonb, ARRAY['B']::text[], 'JSON sử dụng các cặp khóa-giá trị được gắn nhãn và các đối tượng hoặc mảng lồng nhau, cung cấp cấu trúc vốn có nhưng linh hoạt thay vì các hàng và cột cố định của dữ liệu quan hệ có cấu trúc. Do đó, nó là dữ liệu bán cấu trúc.', 'General', ARRAY['DP-900', 'General']::text[], 'https://cdn.examcademy.com/images/questions/1783775282127-9chcmk0r.png', 'published'),
  ('dp900-23', 'dp-900', 23, 'What can be used with built-in notebook support to query and visualize data through a web-based interface?', '[{"key":"A","text":"Azure Databricks"},{"key":"B","text":"pgAdmin"},{"key":"C","text":"Microsoft Power BI"}]'::jsonb, ARRAY['A']::text[], 'Azure Databricks bao gồm các sổ ghi chép gốc trong không gian làm việc dựa trên web, cho phép người dùng truy vấn, phân tích và trực quan hóa dữ liệu một cách tương tác.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-24', 'dp-900', 24, 'Question 24', '[]'::jsonb, ARRAY[]::text[], 'Nhà phân tích dữ liệu thường biến dữ liệu thành báo cáo, trang tổng quan, biểu đồ và các hình ảnh trực quan khác hỗ trợ việc ra quyết định kinh doanh.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-25', 'dp-900', 25, 'Question 25', '[]'::jsonb, ARRAY[]::text[], 'Microsoft Power BI hỗ trợ nhúng các báo cáo và bảng thông tin tương tác vào các trang web, bao gồm cả các kịch bản xuất bản lên web công khai cho người dùng bên ngoài. Dịch vụ Phân tích Azure cung cấp các mô hình ngữ nghĩa, Azure Automation điều phối các tác vụ và Azure Data Lake Analytics xử lý dữ liệu; không có dịch vụ nhúng trang web.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-26', 'dp-900', 26, 'Match each job role with its appropriate task.  
  
Each role may be used once, multiple times, or not at all.', '{"statements":[{"id":"slot1","text":"Database backup and recovery","correctAnswer":"C"},{"id":"slot2","text":"Enabling advanced analytic capabilities through reports","correctAnswer":"A"},{"id":"slot3","text":"Monitoring data pipelines","correctAnswer":"B"}],"choices":[{"key":"A","text":"Data analyst"},{"key":"B","text":"Data engineer"},{"key":"C","text":"Database administrator"}]}'::jsonb, ARRAY['slot1=C', 'slot2=A', 'slot3=B']::text[], 'Quản trị viên cơ sở dữ liệu chịu trách nhiệm sao lưu và phục hồi cơ sở dữ liệu. Các nhà phân tích dữ liệu tạo báo cáo để hỗ trợ phân tích và ra quyết định. Kỹ sư dữ liệu vận hành và giám sát các đường ống dữ liệu di chuyển và chuẩn bị dữ liệu.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-27', 'dp-900', 27, 'Question 27', '[]'::jsonb, ARRAY[]::text[], 'Quản trị viên cơ sở dữ liệu quản lý và duy trì cơ sở dữ liệu, bao gồm tính khả dụng, điều chỉnh hiệu suất và tối ưu hóa.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-28', 'dp-900', 28, 'Which T-SQL statement should be used to tell a database management system to use an index rather than carry out a full table scan?', '[{"key":"A","text":"SELECT"},{"key":"B","text":"WHERE"},{"key":"C","text":"JOIN"}]'::jsonb, ARRAY['B']::text[], 'Vị từ WHERE lọc các hàng theo một điều kiện. Khi một chỉ mục thích hợp tồn tại trên cột hoặc các cột được lọc, trình tối ưu hóa có thể sử dụng chỉ mục đó để định vị các hàng đủ điều kiện thay vì đọc toàn bộ bảng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-29', 'dp-900', 29, 'Question 29', '[]'::jsonb, ARRAY[]::text[], 'Mệnh đề WHERE xác định một điều kiện lọc các hàng bị ảnh hưởng hoặc được trả về bởi câu lệnh DML.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-30', 'dp-900', 30, 'You need to ingest and retain large volumes of streaming IoT data.  
  
Which database solution should you choose?', '[{"key":"A","text":"Azure Database for PostgreSQL"},{"key":"B","text":"Azure Database for MariaDB"},{"key":"C","text":"Azure Cache for Redis"},{"key":"D","text":"Azure Cosmos DB"}]'::jsonb, ARRAY['D']::text[], 'Azure Cosmos DB cung cấp bộ lưu trữ NoSQL bền bỉ, có thể mở rộng với khả năng đọc và ghi thông lượng cao, độ trễ thấp, khiến bộ lưu trữ này rất phù hợp với khối lượng công việc truyền dữ liệu trực tuyến và đo từ xa IoT có khối lượng lớn.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-31', 'dp-900', 31, 'Question 31', '[]'::jsonb, ARRAY[]::text[], 'Chỉ mục được nhóm lưu trữ các hàng của bảng theo thứ tự các giá trị khóa của nó, do đó, nó tổ chức dữ liệu bảng theo (các) cột được lập chỉ mục về mặt vật lý.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-32', 'dp-900', 32, 'You have data in a tabular format, as shown in the following table.  
  
![Question Image](https://cdn.examcademy.com/images/questions/1784211716713-7ommpdk7.png)  
  
What type of data is this an example of?', '[{"key":"A","text":"unstructured data"},{"key":"B","text":"semi-structured data"},{"key":"C","text":"document"},{"key":"D","text":"structured data"}]'::jsonb, ARRAY['D']::text[], 'Dữ liệu có cấu trúc được sắp xếp theo một lược đồ được xác định trước, chẳng hạn như các hàng bản ghi có các cột và trường dữ liệu được xác định nhất quán.', 'General', ARRAY['DP-900', 'General']::text[], 'https://cdn.examcademy.com/images/questions/1784211716713-7ommpdk7.png', 'published'),
  ('dp900-33', 'dp-900', 33, 'Question 33', '[]'::jsonb, ARRAY[]::text[], 'Cơ sở dữ liệu phi quan hệ (NoSQL) sử dụng các mô hình dữ liệu linh hoạt và không yêu cầu mọi bản ghi phải tuân theo một lược đồ cố định. Ngược lại, cơ sở dữ liệu quan hệ lưu trữ dữ liệu trong các bảng và thường thực thi một lược đồ đã xác định.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-34', 'dp-900', 34, 'Question 34', '[]'::jsonb, ARRAY[]::text[], 'Xử lý hàng loạt xử lý dữ liệu tích lũy theo nhóm, do đó không cần phải gửi kết quả ngay lập tức và có thể chấp nhận được một số độ trễ xử lý.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-35', 'dp-900', 35, 'Match the data processing languages with the appropriate real-time analytics services.  
  
Each language may be used once, more than once, or not at all.', '{"statements":[{"id":"azure_data_explorer","text":"Azure Data Explorer","correctAnswer":"B"},{"id":"azure_stream_analytics","text":"Azure Stream Analytics","correctAnswer":"D"},{"id":"azure_synapse_analytics","text":"Azure Synapse Analytics","correctAnswer":"C"}],"choices":[{"key":"A","text":"JavaScript"},{"key":"B","text":"KQL"},{"key":"C","text":"Python"},{"key":"D","text":"SQL"}]}'::jsonb, ARRAY['azure_data_explorer=B', 'azure_stream_analytics=D', 'azure_synapse_analytics=C']::text[], 'Azure Data Explorer sử dụng Ngôn ngữ truy vấn Kusto (KQL) làm ngôn ngữ truy vấn chính. Azure Stream Analytics sử dụng ngôn ngữ truy vấn dựa trên SQL để chuyển đổi và tính toán qua các luồng sự kiện. Azure Synapse Analytics hỗ trợ PySpark (Python) để xử lý dữ liệu Apache Spark.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-36', 'dp-900', 36, 'Match the Azure Data Factory components to the appropriate descriptions. Each component may be used once, more than once, or not at all.', '{"statements":[{"id":"slot1","text":"A representation of data structures within data stores","correctAnswer":"A"},{"id":"slot2","text":"The information used to connect to external resources","correctAnswer":"B"},{"id":"slot3","text":"A logical grouping of activities that performs a unit of work and can be scheduled","correctAnswer":"D"}],"choices":[{"key":"A","text":"Dataset"},{"key":"B","text":"Linked service"},{"key":"C","text":"Mapping data flow"},{"key":"D","text":"Pipeline"}]}'::jsonb, ARRAY['slot1=A', 'slot2=B', 'slot3=D']::text[], 'Tập dữ liệu thể hiện cấu trúc dữ liệu trong các kho dữ liệu được liên kết. Dịch vụ được liên kết cung cấp thông tin kết nối cho các tài nguyên bên ngoài. Quy trình nhóm các hoạt động thành một đơn vị công việc có thể được lên lịch. Ánh xạ các luồng dữ liệu xác định logic chuyển đổi dữ liệu.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-37', 'dp-900', 37, 'Which service can be used to create extract, transform, and load (ETL) pipelines?', '[{"key":"A","text":"Azure Data Factory"},{"key":"B","text":"Azure Pipelines"},{"key":"C","text":"Azure SQL Database"},{"key":"D","text":"Azure Cosmos DB"},{"key":"E","text":"Azure Databricks"}]'::jsonb, ARRAY['A']::text[], 'Azure Data Factory là dịch vụ ETL và tích hợp dữ liệu đám mây của Azure. Nó cung cấp các đường dẫn và hoạt động để nhập dữ liệu, chuyển đổi và tải dữ liệu vào kho lưu trữ dữ liệu mục tiêu.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-38', 'dp-900', 38, 'Question 38', '[]'::jsonb, ARRAY[]::text[], 'Dữ liệu có cấu trúc được tổ chức theo lược đồ được xác định trước; do đó, các thực thể hoặc bản ghi của nó có chung các thuộc tính được xác định. Lược đồ khi đọc và các thuộc tính khác nhau là các đặc điểm liên quan nhiều hơn đến dữ liệu bán cấu trúc hoặc không cấu trúc.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-39', 'dp-900', 39, 'Match each data term with its appropriate description.  
  
A term may be used once, more than once, or not at all.', '{"statements":[{"id":"slot1","text":"Data storage optimized for read operations.","correctAnswer":"A"},{"id":"slot2","text":"Data storage optimized for both read and write operations.","correctAnswer":"C"},{"id":"slot3","text":"Purpose-built systems for storing vast volumes of historical data.","correctAnswer":"A"}],"choices":[{"key":"A","text":"Analytical processing"},{"key":"B","text":"Data pipelines"},{"key":"C","text":"Transactional processing"},{"key":"D","text":"XML files"}]}'::jsonb, ARRAY['slot1=A', 'slot2=C', 'slot3=A']::text[], 'Xử lý phân tích (OLAP) được tối ưu hóa cho phân tích đọc nhiều và thường giữ lại dữ liệu lịch sử để báo cáo và phân tích chuỗi thời gian. Xử lý giao dịch (OLTP) hỗ trợ khối lượng công việc vận hành với khả năng đọc và ghi thường xuyên.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-40', 'dp-900', 40, 'Which Azure Cosmos DB API should be used for a graph database?', '[{"key":"A","text":"Azure Cosmos DB for Table"},{"key":"B","text":"Azure Cosmos DB for Apache Cassandra"},{"key":"C","text":"Azure Cosmos DB for NoSQL"},{"key":"D","text":"Azure Cosmos DB for Apache Gremlin"}]'::jsonb, ARRAY['D']::text[], 'Azure Cosmos DB dành cho Apache Gremlin là API cơ sở dữ liệu đồ thị. Nó lưu trữ và quản lý dữ liệu đồ thị thuộc tính, bao gồm các đỉnh và cạnh, đồng thời hỗ trợ các truy vấn và duyệt đồ thị Gremlin.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-41', 'dp-900', 41, 'Which benefit does hosting a database on Azure SQL Managed Instance provide compared with an Azure SQL Database?', '[{"key":"A","text":"built-in high availability"},{"key":"B","text":"native support for cross-database queries and transactions"},{"key":"C","text":"system-initiated automatic backups"},{"key":"D","text":"support for encryption at rest"}]'::jsonb, ARRAY['B']::text[], 'Azure SQL Managed Instance hỗ trợ các truy vấn cơ sở dữ liệu chéo gồm ba phần gốc và giao dịch cơ sở dữ liệu chéo trong cùng một phiên bản. Azure SQL Database không cung cấp các khả năng gốc đó; tính sẵn sàng cao, các bản sao lưu do hệ thống khởi tạo và mã hóa ở trạng thái lưu trữ cũng là các tính năng của dịch vụ được quản lý.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-42', 'dp-900', 42, 'For each of the following statements, select Yes if the statement is true. Otherwise, select No.', '{"statements":[{"id":"1","text":"Batch processing is optimized for handling large datasets.","correctAnswer":"Yes"},{"id":"2","text":"Stream processing is optimized for performing complex analysis of datasets.","correctAnswer":"No"},{"id":"3","text":"The latency of batch processing is typically measured in seconds or milliseconds.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:No']::text[], 'Xử lý hàng loạt xử lý dữ liệu được tích lũy với khối lượng lớn và phù hợp với các tập dữ liệu lớn. Xử lý luồng tập trung vào dữ liệu đến liên tục và độ trễ thấp, thay vì được xác định bằng phân tích tập dữ liệu phức tạp. Xử lý hàng loạt thường có độ trễ cao hơn—thường là vài phút hoặc lâu hơn—trong khi giây hoặc mili giây là mục tiêu độ trễ xử lý luồng điển hình.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-43', 'dp-900', 43, 'Question 43', '[]'::jsonb, ARRAY[]::text[], 'TDE mã hóa dữ liệu cơ sở dữ liệu và các tệp nhật ký giao dịch ở trạng thái lưu trữ. Nó không cung cấp mã hóa cho dữ liệu đang truyền hoặc nhắm mục tiêu vào các cột riêng lẻ.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-44', 'dp-900', 44, 'What is the main purpose of a data warehouse?', '[{"key":"A","text":"to provide answers to complex queries that rely on data from multiple sources"},{"key":"B","text":"to provide transformation services between source and target data stores"},{"key":"C","text":"to provide read-only storage of relational and non-relational historical data"},{"key":"D","text":"to provide storage for transactional line-of-business (LOB) applications"}]'::jsonb, ARRAY['A']::text[], 'Dữ liệu warehouse tích hợp dữ liệu từ nhiều nguồn vào cấu trúc được tối ưu hóa cho phân tích, báo cáo và truy vấn phức tạp trên dữ liệu kết hợp đó.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-45', 'dp-900', 45, 'You have an Azure SQL database containing tables for customers and orders.  
  
You need to create a query that returns the orders submitted by each customer.  
  
Which two Transact-SQL statements should be included in the query? Each correct answer represents part of the solution.  
  
NOTE: Each correct selection is worth one point.', '[{"key":"A","text":"INDEX"},{"key":"B","text":"EXISTS"},{"key":"C","text":"JOIN"},{"key":"D","text":"ORDERBY"},{"key":"E","text":"SELECT"}]'::jsonb, ARRAY['C', 'E']::text[], '`SELECT` truy xuất các hàng cho tập kết quả và `JOIN` kết hợp các bảng Khách hàng và Đơn hàng bằng khóa liên quan của chúng để mỗi đơn hàng được trả về đều được liên kết với khách hàng của nó. Microsoft ghi lại `SELECT` làm câu lệnh truy xuất các hàng và `JOIN` làm thao tác giữa các nguồn bảng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-46', 'dp-900', 46, 'In a fully normalized database, how are data read and written for one entity?', '[{"key":"A","text":"Data is read from multiple tables and written to multiple tables."},{"key":"B","text":"Data is read from a single table and written to a single table."},{"key":"C","text":"Data is read from a single table and written to multiple tables."},{"key":"D","text":"Data is read from multiple tables and written to a single table."}]'::jsonb, ARRAY['A']::text[], 'Chuẩn hóa hoàn toàn phân phối các dữ kiện liên quan trên các bảng để tránh trùng lặp và duy trì sự phụ thuộc thích hợp. Do đó, việc đại diện cho một thực thể duy nhất có thể yêu cầu các phép nối đọc dữ liệu đầy đủ của nó và phối hợp ghi vào các bảng liên quan để lưu trữ dữ kiện của nó.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-47', 'dp-900', 47, 'Question 47', '[]'::jsonb, ARRAY[]::text[], 'Một bảng quan hệ có một lược đồ được xác định. Mỗi hàng tuân theo lược đồ đó và do đó chứa các cột giống nhau, mặc dù các giá trị trong các cột đó có thể khác nhau giữa các hàng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-48', 'dp-900', 48, 'Which service can you use to create data-ingestion pipelines?', '[{"key":"A","text":"Azure HDInsight"},{"key":"B","text":"Azure SQL Database"},{"key":"C","text":"Azure Data Factory"},{"key":"D","text":"Azure Cosmos DB"}]'::jsonb, ARRAY['C']::text[], 'Azure Data Factory tạo và lên lịch các quy trình công việc (đường dẫn) dựa trên dữ liệu để nhập dữ liệu từ các kho lưu trữ dữ liệu khác nhau và có thể điều phối việc di chuyển và chuyển đổi dữ liệu.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-49', 'dp-900', 49, 'Match each job role with its appropriate task.  
  
Each role may be used once, more than once, or not at all.', '{"statements":[{"id":"slot1","text":"Create a pipeline to transfer data from a database to a data warehouse.","correctAnswer":"C"},{"id":"slot2","text":"Create a transactional database.","correctAnswer":"D"},{"id":"slot3","text":"Create a chart that shows sales transactions by week.","correctAnswer":"A"}],"choices":[{"key":"A","text":"Data analyst"},{"key":"B","text":"Data architect"},{"key":"C","text":"Data engineer"},{"key":"D","text":"Database administrator"}]}'::jsonb, ARRAY['slot1=C', 'slot2=D', 'slot3=A']::text[], 'Các kỹ sư dữ liệu triển khai các quy trình truyền và chuyển đổi dữ liệu giữa các hệ thống, bao gồm từ cơ sở dữ liệu vận hành sang warehouse phân tích. Quản trị viên cơ sở dữ liệu cung cấp và vận hành cơ sở dữ liệu giao dịch. Các nhà phân tích dữ liệu khám phá dữ liệu và tạo trực quan hóa và biểu đồ để truyền đạt xu hướng, chẳng hạn như giao dịch bán hàng hàng tuần.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-50', 'dp-900', 50, 'Question 50', '[]'::jsonb, ARRAY[]::text[], 'Phân tích mô tả kiểm tra và tóm tắt dữ liệu lịch sử để báo cáo những gì đã xảy ra trong quá khứ.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-51', 'dp-900', 51, 'Question 51', '[]'::jsonb, ARRAY[]::text[], 'Báo cáo phân trang Power BI hỗ trợ bố cục chính xác, được định dạng cao, sẵn sàng in và được tối ưu hóa để in hoặc xuất PDF.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-52', 'dp-900', 52, 'Question 52', '[]'::jsonb, ARRAY[]::text[], 'SQL Server là một hệ thống quản lý cơ sở dữ liệu quan hệ. Các bảng của nó lưu trữ dữ liệu có cấu trúc theo hàng và cột, đồng thời các khóa và ràng buộc có thể xác định mối quan hệ giữa các bảng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-53', 'dp-900', 53, 'Question 53', '[]'::jsonb, ARRAY[]::text[], 'Một nhóm linh hoạt được thiết kế cho nhiều cơ sở dữ liệu Azure SQL với các kiểu sử dụng khác nhau để chia sẻ một nhóm tài nguyên xác định, giúp tối ưu hóa chi phí và hiệu suất.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-54', 'dp-900', 54, 'You need to create a solution that delivers data to executives. The solution must provide an interactive graphical interface, show various key performance indicators, and enable data exploration through drill-down.  
  
What should you use in Microsoft Power BI?', '[{"key":"A","text":"a view"},{"key":"B","text":"a report"},{"key":"C","text":"a dataflow"},{"key":"D","text":"Microsoft Power Apps"}]'::jsonb, ARRAY['B']::text[], 'Báo cáo Power BI chứa hình ảnh tương tác có thể hiển thị các chỉ số hiệu suất chính và cho phép người dùng khám phá dữ liệu bằng cách lọc và truy sâu vào hệ thống phân cấp.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-55', 'dp-900', 55, 'What is used to define a query for stream-processing jobs in Azure Stream Analytics?', '[{"key":"A","text":"YAML"},{"key":"B","text":"KQL"},{"key":"C","text":"SQL"},{"key":"D","text":"XML"}]'::jsonb, ARRAY['C']::text[], 'Azure Stream Analytics sử dụng ngôn ngữ truy vấn SQL, dựa trên một tập hợp con của T-SQL và được mở rộng bằng các cấu trúc phát trực tuyến, để xác định các phép biến đổi và tính toán qua các luồng sự kiện.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-56', 'dp-900', 56, 'When you provision an Azure Cosmos DB account, which feature delivers redundancy inside an Azure region?', '[{"key":"A","text":"multi-master replication"},{"key":"B","text":"Availability Zones"},{"key":"C","text":"the strong consistency level"},{"key":"D","text":"automatic failover"}]'::jsonb, ARRAY['B']::text[], 'Availability Zones cung cấp khả năng dự phòng trong khu vực bằng cách phân phối bản sao dữ liệu Azure Cosmos DB trên nhiều availability zones riêng biệt về mặt vật lý, bảo vệ tài khoản khỏi lỗi một vùng. [Microsoft Learn: Reliability in Azure Cosmos DB](https://learn.microsoft.com/en-us/azure/reliability/reliability-cosmos-db)', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-57', 'dp-900', 57, 'You must design and model a database using a graphical tool that supports project-based, offline database development.  
  
What should you use?', '[{"key":"A","text":"Microsoft SQL Server Data Tools (SSDT)"},{"key":"B","text":"Microsoft SQL Server Management Studio (SSMS)"},{"key":"C","text":"Azure Databricks"},{"key":"D","text":"Azure Data Studio"}]'::jsonb, ARRAY['A']::text[], 'SQL Server Data Tools (SSDT) ​​cung cấp các dự án cơ sở dữ liệu Visual Studio SQL để phát triển cơ sở dữ liệu ngoại tuyến, theo định hướng dự án và bao gồm giao diện đồ họa và trình thiết kế bảng trực quan để thiết kế cơ sở dữ liệu.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-58', 'dp-900', 58, 'You are reviewing the data model in the following exhibit.  
  
![Question Image](https://cdn.examcademy.com/images/questions/1785750867594-09a4l850.png)', '[]'::jsonb, ARRAY[]::text[], 'Bán hàng là bảng dữ kiện trung tâm, được liên kết trực tiếp với các bảng thứ nguyên Khách hàng, Sản phẩm, Người bán hàng và Warehouse. Khách hàng cung cấp các thuộc tính mô tả để phân tích doanh số bán hàng và do đó là một bảng thứ nguyên.', 'General', ARRAY['DP-900', 'General']::text[], 'https://cdn.examcademy.com/images/questions/1785750867594-09a4l850.png', 'published'),
  ('dp900-59', 'dp-900', 59, 'Question 59', '[]'::jsonb, ARRAY[]::text[], 'Truyền phát có cấu trúc Spark được xây dựng trên API Spark SQL DataFrame/Dataset. DataFrame biểu thị dữ liệu dạng bảng với các cột được đặt tên, trong khi Delta Lake, hồ dữ liệu và dữ liệu warehouse là các khái niệm lưu trữ hoặc kiến ​​trúc thay vì trừu tượng hóa bảng được sử dụng bởi Truyền có cấu trúc.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-60', 'dp-900', 60, 'Your company is designing a database to store website session data. The data will include notifications, personalization attributes, and products added to a shopping cart.  
  
Which type of data store provides the lowest latency for retrieving the data?', '[{"key":"A","text":"key/value"},{"key":"B","text":"graph"},{"key":"C","text":"columnar"},{"key":"D","text":"document"}]'::jsonb, ARRAY['A']::text[], 'Kho lưu trữ dữ liệu khóa/giá trị cung cấp khả năng truy xuất trực tiếp có độ trễ rất thấp bằng khóa phiên, phù hợp với trạng thái phiên như thông báo, thuộc tính cá nhân hóa và các mặt hàng trong giỏ hàng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-61', 'dp-900', 61, 'Which responsibility belongs to a database administrator?', '[{"key":"A","text":"applying data cleaning routines"},{"key":"B","text":"creating data visualizations"},{"key":"C","text":"managing data integration processes"},{"key":"D","text":"storing backup copies of data"}]'::jsonb, ARRAY['D']::text[], 'Quản trị viên cơ sở dữ liệu duy trì tính sẵn sàng, tính toàn vẹn, bảo mật và khả năng phục hồi của cơ sở dữ liệu. Tạo và giữ lại các bản sao lưu dữ liệu hỗ trợ phục hồi sau khi mất dữ liệu, hỏng hoặc lỗi hệ thống.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-62', 'dp-900', 62, 'You have the following two customer-data tables.  
  
![Question Image](https://cdn.examcademy.com/images/questions/1783769023212-u4q9t9us.jpg)  
  
![Question Image](https://cdn.examcademy.com/images/questions/1783769026105-ezb2pkmm.jpg)  
  
What type of data do the tables contain?', '[{"key":"A","text":"structured"},{"key":"B","text":"non-relational"},{"key":"C","text":"semi-structured"},{"key":"D","text":"unstructured"}]'::jsonb, ARRAY['A']::text[], 'Dữ liệu có cấu trúc được tổ chức thành một lược đồ gồm các cột và hàng được xác định trước, với mỗi giá trị được lưu trữ trong một trường xác định. Hồ sơ khách hàng sử dụng các trường cố định như số nhận dạng, tên, địa chỉ và ngày tháng.', 'General', ARRAY['DP-900', 'General']::text[], 'https://cdn.examcademy.com/images/questions/1783769023212-u4q9t9us.jpg', 'published'),
  ('dp900-63', 'dp-900', 63, 'Which three characteristics describe an Online Transaction Processing (OLTP) workload? Each correct answer provides a complete solution.  
  
> **NOTE:** Each correct selection is worth one point.', '[{"key":"A","text":"denormalized data"},{"key":"B","text":"heavy writes and moderate reads"},{"key":"C","text":"light writes and heavy reads"},{"key":"D","text":"schema defined in a database"},{"key":"E","text":"schema defined when reading unstructured data from a database"},{"key":"F","text":"normalized data"}]'::jsonb, ARRAY['B', 'D', 'F']::text[], 'Hệ thống OLTP được thiết kế để xử lý giao dịch với lượng ghi lớn và số lần đọc vừa phải. Họ sử dụng thiết kế cơ sở dữ liệu lược đồ khi ghi được thực thi và dữ liệu được chuẩn hóa cao để giảm sự dư thừa và duy trì tính toàn vẹn của giao dịch. [Online Transaction Processing (OLTP) — Microsoft Learn](https://learn.microsoft.com/en-us/azure/architecture/data-guide/relational-data/online-transaction-processing)', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-64', 'dp-900', 64, 'At which two levels can throughput be configured for an Azure Cosmos DB account? Each correct answer provides a complete solution.  
  
> **NOTE:** Each correct selection is worth one point.', '[{"key":"A","text":"database"},{"key":"B","text":"item"},{"key":"C","text":"container"},{"key":"D","text":"partition"}]'::jsonb, ARRAY['A', 'C']::text[], 'Azure Cosmos DB cho phép bạn cung cấp thông lượng ở cấp vùng chứa hoặc ở cấp cơ sở dữ liệu. Thông lượng cấp cơ sở dữ liệu được chia sẻ bởi các bộ chứa trong cơ sở dữ liệu đó; các mục và phân vùng không phải là mức cấu hình thông lượng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-65', 'dp-900', 65, 'You need to change a view in a relational database by adding a new column.  
  
Which statement should be used?', '[{"key":"A","text":"MERGE"},{"key":"B","text":"ALTER"},{"key":"C","text":"INSERT"},{"key":"D","text":"UPDATE"}]'::jsonb, ARRAY['B']::text[], 'Câu lệnh `ALTER` thay đổi định nghĩa của đối tượng cơ sở dữ liệu hiện có, bao gồm cả dạng xem. Việc thêm một cột vào một dạng xem yêu cầu thay đổi định nghĩa của nó.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-66', 'dp-900', 66, 'You plan to deploy a PostgreSQL database to Azure.  
  
Which hosting model matches each available deployment option?', '[]'::jsonb, ARRAY[]::text[], 'PostgreSQL trên máy ảo Azure là IaaS vì bạn quản lý máy ảo, hệ điều hành và nhiều tác vụ quản trị cơ sở dữ liệu. Cơ sở dữ liệu Azure cho PostgreSQL là PaaS vì Azure quản lý nền tảng cơ bản và các tác vụ vận hành như vá lỗi, sao lưu và tính sẵn sàng cao.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-67', 'dp-900', 67, 'Which command-line utility can be used to query Azure SQL databases?', '[{"key":"A","text":"sqlcmd"},{"key":"B","text":"bcp"},{"key":"C","text":"azdata"},{"key":"D","text":"Azure CLI"}]'::jsonb, ARRAY['A']::text[], 'Tiện ích `sqlcmd` kết nối với cơ sở dữ liệu Azure SQL và thực thi các câu lệnh và tập lệnh Transact-SQL từ dòng lệnh.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-68', 'dp-900', 68, 'Match the activity types to the corresponding Azure Data Factory activities.  
  
An activity type may be used once, more than once, or not at all.', '{"statements":[{"id":"copy","text":"Copy","correctAnswer":"B"},{"id":"mapping_data_flow","text":"Mapping data flow","correctAnswer":"C"},{"id":"lookup","text":"Lookup","correctAnswer":"A"}],"choices":[{"key":"A","text":"Control"},{"key":"B","text":"Data movement"},{"key":"C","text":"Data transformation"}]}'::jsonb, ARRAY['copy=B', 'mapping_data_flow=C', 'lookup=A']::text[], 'Copy activity chuyển dữ liệu giữa các kho dữ liệu, biến nó thành một hoạt động di chuyển dữ liệu. Mapping Data Flow thực hiện logic chuyển đổi, biến nó thành một hoạt động chuyển đổi dữ liệu. Tra cứu truy xuất dữ liệu hoặc siêu dữ liệu cho logic quy trình tiếp theo, biến nó thành hoạt động kiểm soát.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-69', 'dp-900', 69, 'For each statement, select **Yes** if it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"You can copy a dashboard between Microsoft Power BI workspaces.","correctAnswer":"No"},{"id":"2","text":"A Microsoft Power BI dashboard can only display visualizations from a single dataset.","correctAnswer":"No"},{"id":"3","text":"A Microsoft Power BI dashboard can display visualizations from a Microsoft Excel workbook.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:No', '3:Yes']::text[], 'Power BI hỗ trợ lưu bản sao báo cáo sang không gian làm việc khác, không sao chép bảng thông tin giữa các không gian làm việc. Trang tổng quan có thể kết hợp các ô được hỗ trợ bởi nhiều báo cáo và mô hình ngữ nghĩa. Phạm vi, bảng, PivotTable, biểu đồ và trang tính trong sổ làm việc Excel có thể được ghim vào bảng thông tin Power BI dưới dạng ô xếp.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-70', 'dp-900', 70, 'Question 70', '[]'::jsonb, ARRAY[]::text[], 'Chế độ xem là một bảng ảo có nội dung được xác định bởi một truy vấn. Đống là một bảng không có thứ tự, một thủ tục lưu sẵn sẽ thực thi một tập hợp các câu lệnh và một chỉ mục sẽ cải thiện hiệu suất truy cập dữ liệu.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-71', 'dp-900', 71, 'Question 71', '[]'::jsonb, ARRAY[]::text[], 'Phân tích mô tả trình bày và tóm tắt dữ liệu hiện tại hoặc quá khứ, chẳng hạn như số lượng tuyển sinh theo khoa sắp xếp.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-72', 'dp-900', 72, 'Data is stored in the following format.  
  
![Question Image](https://cdn.examcademy.com/images/questions/1783769421576-cfz08n5j.png)  
  
Which format is being used?', '[{"key":"A","text":"XML"},{"key":"B","text":"HTML"},{"key":"C","text":"YAML"},{"key":"D","text":"JSON"}]'::jsonb, ARRAY['D']::text[], 'JSON biểu thị các đối tượng có `{}` và các mảng có `[]`, với tên thuộc tính được trích dẫn và các giá trị được phân tách bằng dấu hai chấm.', 'General', ARRAY['DP-900', 'General']::text[], 'https://cdn.examcademy.com/images/questions/1783769421576-cfz08n5j.png', 'published'),
  ('dp900-73', 'dp-900', 73, 'For each statement, select **Yes** when it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"Normalizing a database increases the throughput of writing transactions.","correctAnswer":"Yes"},{"id":"2","text":"Analytics systems are more normalized than transactional systems.","correctAnswer":"No"},{"id":"3","text":"Normalizing a database results in queries that require more joins.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:Yes']::text[], 'Quá trình chuẩn hóa sẽ phân tách dữ liệu dư thừa thành các bảng có liên quan, do đó, thao tác ghi giao dịch thường cập nhật ít giá trị trùng lặp hơn và tránh công việc duy trì tính nhất quán. Hệ thống OLTP sử dụng chuẩn hóa để xử lý hiệu quả số lượng lớn giao dịch độc lập. Khối lượng công việc phân tích thường sử dụng các mô hình thứ nguyên không chuẩn hóa để đơn giản hóa và tăng tốc các truy vấn tổng hợp. Vì dữ liệu đã chuẩn hóa được phân phối trên các bảng liên quan nên việc truy xuất bản ghi kinh doanh kết hợp thường yêu cầu các phép nối bổ sung.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-74', 'dp-900', 74, 'You need to build a visualization showing running quarterly sales totals, as illustrated in the following exhibit.  
  
![Question Image](https://cdn.examcademy.com/images/questions/1783769007790-5ow8m1mz.png)  
  
What should you create in Power BI Desktop?', '[{"key":"A","text":"a waterfall chart"},{"key":"B","text":"a ribbon chart"},{"key":"C","text":"a bar chart"},{"key":"D","text":"a decomposition tree"}]'::jsonb, ARRAY['A']::text[], 'Biểu đồ thác nước hiển thị cách tích lũy các thay đổi tích cực hoặc tiêu cực tuần tự từ giá trị bắt đầu đến tổng giá trị cuối cùng. Nó phù hợp với những thay đổi về doanh số bán hàng hàng quý tạo nên tổng doanh số bán hàng tổng thể.', 'General', ARRAY['DP-900', 'General']::text[], 'https://cdn.examcademy.com/images/questions/1783769007790-5ow8m1mz.png', 'published'),
  ('dp900-75', 'dp-900', 75, 'Question 75', '[]'::jsonb, ARRAY[]::text[], 'Dữ liệu biểu đồ có cấu trúc tổ chức - các nút, cạnh và thuộc tính của chúng - nhưng no đã cố định lược đồ quan hệ mà mọi bản ghi phải tuân theo, điều này khiến nó có cấu trúc bán cấu trúc. Microsoft phân loại các cửa hàng biểu đồ như dữ liệu người dùng và người theo dõi trên mạng xã hội theo cách này, cùng với các tài liệu JSON và các cặp khóa-giá trị.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-76', 'dp-900', 76, 'Match each process to its corresponding scenario. Each process may be used once, more than once, or not at all.', '{"statements":[{"id":"slot1","text":"Data is retrieved and processed before being saved to a target system","correctAnswer":"C"},{"id":"slot2","text":"Data is saved to a target system, and then processed","correctAnswer":"B"},{"id":"slot3","text":"Data is extracted from a source system, and then saved to a target system","correctAnswer":"A"}],"choices":[{"key":"A","text":"Data ingestion"},{"key":"B","text":"Extract, load, and transform (ELT) processing"},{"key":"C","text":"Extract, transform, and load (ETL) processing"}]}'::jsonb, ARRAY['slot1=C', 'slot2=B', 'slot3=A']::text[], 'ETL chuyển đổi dữ liệu trước khi tải nó vào hệ thống đích, trong khi ELT tải dữ liệu vào mục tiêu và chuyển đổi dữ liệu sau đó. Việc nhập dữ liệu sẽ di chuyển dữ liệu được trích xuất từ ​​hệ thống nguồn sang hệ thống đích.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-77', 'dp-900', 77, 'Question 77', '[]'::jsonb, ARRAY[]::text[], 'CSV lưu trữ dữ liệu dạng bảng dưới dạng văn bản được phân tách: các giá trị trường được phân tách bằng dấu phẩy và mỗi bản ghi kết thúc bằng dấu ngắt dòng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-78', 'dp-900', 78, 'Your company has recently reported sales from the third quarter.  
  
You have the chart shown in the following exhibit.  
  
![Question Image](https://cdn.examcademy.com/images/questions/1783768225959-2w50smu3.png)  
  
Which type of analysis is displayed in the fourth quarter?', '[{"key":"A","text":"predictive"},{"key":"B","text":"prescriptive"},{"key":"C","text":"descriptive"},{"key":"D","text":"diagnostic"}]'::jsonb, ARRAY['A']::text[], 'Dự báo ước tính giá trị tương lai từ các xu hướng lịch sử, thường có khoảng tin cậy thể hiện sự không chắc chắn xung quanh kết quả được dự đoán. Đây là phân tích dự đoán.', 'General', ARRAY['DP-900', 'General']::text[], 'https://cdn.examcademy.com/images/questions/1783768225959-2w50smu3.png', 'published'),
  ('dp900-79', 'dp-900', 79, 'Match the workload types to the appropriate scenarios. Each workload type may be used once, more than once, or not at all.', '{"statements":[{"id":"slot1","text":"Data for a product catalog will be loaded every 12 hours to a data warehouse.","correctAnswer":"A"},{"id":"slot2","text":"Thousands of data sets per second for online purchases will be loaded into a data warehouse in real time","correctAnswer":"B"},{"id":"slot3","text":"Updates to inventory data will be loaded to a data warehouse every 1 million transactions.","correctAnswer":"A"}],"choices":[{"key":"A","text":"Batch"},{"key":"B","text":"Streaming"}]}'::jsonb, ARRAY['slot1=A', 'slot2=B', 'slot3=A']::text[], 'Xử lý hàng loạt tải dữ liệu tích lũy theo khoảng thời gian đã lên lịch hoặc sau ngưỡng khối lượng giao dịch được xác định. Quá trình xử lý phát trực tuyến liên tục tải dữ liệu sự kiện khi nó đến, phù hợp với việc nhập mua hàng trực tuyến theo thời gian thực.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-80', 'dp-900', 80, 'For each statement below, select **Yes** when it is true; otherwise, select **No**.', '{"statements":[{"id":"1","text":"Database administrators apply data cleansing routines and turn data into useful information.","correctAnswer":"No"},{"id":"2","text":"Data engineers manage databases, store backup copies of data, and restore data in the event of a failure.","correctAnswer":"No"},{"id":"3","text":"Data analysts create data visuals and enable companies to make data-driven decisions.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:No', '3:Yes']::text[], 'Áp dụng quy trình làm sạch dữ liệu và biến dữ liệu thành thông tin hữu ích là công việc của các kỹ sư dữ liệu và nhà phân tích dữ liệu, không phải quản trị viên cơ sở dữ liệu, vì vậy statement 1 là No. Quản lý cơ sở dữ liệu cũng như thực hiện sao lưu và khôi phục sau khi xảy ra lỗi là trách nhiệm của quản trị viên cơ sở dữ liệu cổ điển chứ không phải vai trò của kỹ sư dữ liệu (kỹ sư dữ liệu xây dựng đường dẫn nhập/chuyển đổi và kho lưu trữ dữ liệu cung cấp), vì vậy statement 2 là No. Các nhà phân tích dữ liệu tạo ra hình ảnh trực quan và cho phép các công ty đưa ra quyết định dựa trên dữ liệu, vì vậy statement 3 là Yes.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-81', 'dp-900', 81, 'Question 81', '[]'::jsonb, ARRAY[]::text[], 'Sơ đồ cây mã hóa các giá trị dưới dạng hình chữ nhật có diện tích tỷ lệ với các giá trị và nó có thể hiển thị thứ bậc thông qua các hình chữ nhật lồng nhau.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-82', 'dp-900', 82, 'Select the option that correctly finishes the sentence.', '[]'::jsonb, ARRAY[]::text[], 'Azure Cosmos DB dành cho NoSQL hỗ trợ ngôn ngữ truy vấn giống SQL trong đó SELECT dự án và truy xuất tài liệu JSON. Các API khác sử dụng các mô hình truy cập dữ liệu Gremlin, MongoDB hoặc Table tương ứng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-83', 'dp-900', 83, 'Question 83', '[]'::jsonb, ARRAY[]::text[], 'Các hệ thống OLAP thường sử dụng các khối đa chiều hoặc mô hình ngữ nghĩa dạng bảng chứa dữ liệu được tổng hợp trước. Những tập hợp này tăng tốc các truy vấn phân tích phức tạp trên nhiều hàng và thứ nguyên; tối ưu hóa giao dịch là một đặc điểm của hệ thống OLTP.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-84', 'dp-900', 84, 'Question 84', '[]'::jsonb, ARRAY[]::text[], 'Thủ tục lưu trữ là một khối SQL hoặc mã thủ tục được đặt tên được lưu trữ và thực thi bởi hệ thống quản lý cơ sở dữ liệu. Bảng chứa dữ liệu, dạng xem thể hiện kết quả truy vấn đã lưu và chỉ mục cải thiện hiệu suất tra cứu truy vấn.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-85', 'dp-900', 85, 'For each of the following statements, select **Yes** if the statement is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"Extract, transform, and load (ETL) can reduce the transfer of sensitive data to destination systems.","correctAnswer":"Yes"},{"id":"2","text":"Extract, load, and transform (ELT) transforms data by using a compute resource independent of the source system and destination system.","correctAnswer":"No"},{"id":"3","text":"Extract, load, and transform (ELT) minimizes the time it takes to copy large volumes of data to destination systems.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:Yes']::text[], 'ETL biến đổi dữ liệu trước khi tải, cho phép lọc, che hoặc xóa dữ liệu nhạy cảm trước khi chuyển đến đích. ELT tải dữ liệu trước rồi chuyển đổi dữ liệu đó bằng cách sử dụng tài nguyên điện toán trong hệ thống đích. Tải trước khi chuyển đổi cũng tránh làm trì hoãn thao tác sao chép đối với các chuyển đổi tải trước, điều này làm cho ELT phù hợp để di chuyển nhanh khối lượng dữ liệu lớn.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-86', 'dp-900', 86, 'Match each ACID term with its corresponding description.  
  
A term may be used once, multiple times, or not at all.', '{"statements":[{"id":"slot1","text":"Concurrent transactions cannot interfere with one another and must result in a consistent database state.","correctAnswer":"C"},{"id":"slot2","text":"Each transaction is treated as a single unit that succeeds completely or fails completely.","correctAnswer":"A"},{"id":"slot3","text":"Transactions can only take the data in a database from one valid state to another.","correctAnswer":"B"},{"id":"slot4","text":"When a transaction is committed, it will remain committed.","correctAnswer":"D"}],"choices":[{"key":"A","text":"Atomicity"},{"key":"B","text":"Consistency"},{"key":"C","text":"Isolation"},{"key":"D","text":"Durability"}]}'::jsonb, ARRAY['slot1=C', 'slot2=A', 'slot3=B', 'slot4=D']::text[], 'Sự cô lập tách biệt các giao dịch đồng thời; tính nguyên tử yêu cầu tất cả các hoạt động giao dịch phải thành công hoặc tất cả đều thất bại; tính nhất quán duy trì trạng thái cơ sở dữ liệu hợp lệ; và độ bền làm cho những thay đổi đã cam kết trở thành vĩnh viễn.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-87', 'dp-900', 87, 'You have the following JSON document.  
  
![Question Image](https://cdn.examcademy.com/images/questions/1783766107140-daa6328l.png)  
  
Complete each statement by choosing the appropriate answer based on the JSON document.', '[]'::jsonb, ARRAY[]::text[], 'Trong JSON, dấu ngoặc nhọn xác định đối tượng và dấu ngoặc vuông xác định mảng. Giá trị khách hàng và địa chỉ sử dụng dấu ngoặc nhọn bên trong tài liệu bên ngoài, biến chúng thành các đối tượng lồng nhau. Giá trị phương tiện truyền thông xã hội sử dụng dấu ngoặc vuông, biến nó thành một mảng lồng nhau.', 'General', ARRAY['DP-900', 'General']::text[], 'https://cdn.examcademy.com/images/questions/1783766107140-daa6328l.png', 'published'),
  ('dp900-88', 'dp-900', 88, 'What are two traits of real-time data processing? Each correct answer provides a complete solution.  
  
**NOTE:** Each correct selection is worth one point.', '[{"key":"A","text":"Data is processed periodically"},{"key":"B","text":"Low latency is expected"},{"key":"C","text":"High latency is acceptable"},{"key":"D","text":"Data is processed as it is created"}]'::jsonb, ARRAY['B', 'D']::text[], 'Quá trình xử lý dữ liệu theo thời gian thực xử lý dữ liệu ngay khi dữ liệu được tạo và hướng tới độ trễ thấp để có được kết quả với độ trễ tối thiểu.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-89', 'dp-900', 89, 'Match the job roles with their appropriate tasks.  
  
Each role can be used once, multiple times, or not at all.', '{"statements":[{"id":"slot1","text":"Assign permissions to users.","correctAnswer":"C"},{"id":"slot2","text":"Derive meaning from data by creating visualizations and charts.","correctAnswer":"A"},{"id":"slot3","text":"Implement which pipelines to transfer and transform data between systems.","correctAnswer":"B"}],"choices":[{"key":"A","text":"Data analyst"},{"key":"B","text":"Data engineer"},{"key":"C","text":"Database administrator"}]}'::jsonb, ARRAY['slot1=C', 'slot2=A', 'slot3=B']::text[], 'Quản trị viên cơ sở dữ liệu kiểm soát quyền truy cập cơ sở dữ liệu và phân quyền cho người dùng. Các nhà phân tích dữ liệu giải thích dữ liệu và truyền đạt các phát hiện thông qua trực quan hóa và biểu đồ. Kỹ sư dữ liệu xây dựng và vận hành các đường ống di chuyển và chuyển đổi dữ liệu giữa các hệ thống.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-90', 'dp-900', 90, 'Question 90', '[]'::jsonb, ARRAY[]::text[], 'JSON biểu thị dữ liệu dưới dạng các trường và giá trị được đặt tên, nhưng tài liệu có thể có các nhóm trường khác nhau. Tổ chức tự mô tả, linh hoạt đó làm cho nó trở thành dữ liệu bán cấu trúc thay vì dữ liệu quan hệ, có cấu trúc đầy đủ hoặc không có cấu trúc.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-91', 'dp-900', 91, 'Question 91', '[]'::jsonb, ARRAY[]::text[], 'Azure Synapse Analytics bao gồm khả năng tích hợp dữ liệu và đường dẫn tương tự như Azure Data Factory, cho phép tạo và điều phối các đường dẫn dữ liệu.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-92', 'dp-900', 92, 'You have an on-premises Microsoft SQL Server database that you need to migrate to the cloud. The solution must meet these requirements:  
  
- Minimize maintenance effort.  
- Support the Database Mail and Service Broker features.  
  
What should you include in the solution?', '[{"key":"A","text":"Azure SQL Database single database"},{"key":"B","text":"an Azure SQL Database elastic pool"},{"key":"C","text":"Azure SQL Managed instance"},{"key":"D","text":"SQL Server on Azure virtual machines"}]'::jsonb, ARRAY['C']::text[], 'Azure SQL Managed Instance cung cấp các khả năng của phiên bản SQL Server được quản lý đồng thời giảm thiểu việc bảo trì cơ sở hạ tầng và nền tảng. Nó hỗ trợ Nhà môi giới dịch vụ và thư cơ sở dữ liệu; Thư cơ sở dữ liệu không có sẵn trong cơ sở dữ liệu đơn lẻ hoặc nhóm đàn hồi Azure SQL Database.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-93', 'dp-900', 93, 'Question 93', '[]'::jsonb, ARRAY[]::text[], 'Tài khoản Azure Cosmos DB được tạo cho một API cụ thể, chẳng hạn như NoSQL, MongoDB, Cassandra, Gremlin hoặc Table. Cơ sở dữ liệu, vùng chứa và mục là các tài nguyên được tạo và quản lý trong tài khoản đó.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-94', 'dp-900', 94, 'What should you use to create a Microsoft Power BI paginated report?', '[{"key":"A","text":"Charticulator"},{"key":"B","text":"Power BI Desktop"},{"key":"C","text":"the Power BI service"},{"key":"D","text":"Power BI Report Builder"}]'::jsonb, ARRAY['D']::text[], 'Trình tạo báo cáo Power BI là công cụ soạn thảo độc lập cho các báo cáo được phân trang Power BI. Nó được sử dụng để thiết kế định nghĩa báo cáo được phân trang trước khi có thể xuất bản lên dịch vụ Power BI.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-95', 'dp-900', 95, 'Question 95', '[]'::jsonb, ARRAY[]::text[], 'Kho lưu trữ dữ liệu khóa/giá trị sắp xếp dữ liệu xung quanh một khóa duy nhất và truy xuất trực tiếp giá trị được liên kết, thực hiện các hoạt động tra cứu dựa trên khóa đơn giản được tối ưu hóa chính. Việc nối bảng và các ràng buộc quan hệ là đặc điểm của cơ sở dữ liệu quan hệ, trong khi các giao dịch không phải là sự tối ưu hóa xác định của mô hình khóa/giá trị.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-96', 'dp-900', 96, 'Question 96', '[]'::jsonb, ARRAY[]::text[], 'Cơ sở dữ liệu quan hệ hỗ trợ các giao dịch ACID và tính nhất quán cao, làm cho chúng phù hợp khi cần có dữ liệu giao dịch nhất quán, đáng tin cậy.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-97', 'dp-900', 97, 'For each statement, select **Yes** when it is true; otherwise, select **No**.', '{"statements":[{"id":"1","text":"The Azure Cosmos DB API is configured separately for each database in an Azure Cosmos DB account.","correctAnswer":"No"},{"id":"2","text":"Partition keys are used in Azure Cosmos DB to optimize queries.","correctAnswer":"Yes"},{"id":"3","text":"Items contained in the same Azure Cosmos DB logical partition can have different partition keys.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:Yes', '3:No']::text[], 'Tài khoản Azure Cosmos DB được tạo bằng một API duy nhất, do đó API không được định cấu hình độc lập cho mỗi cơ sở dữ liệu. Khóa phân vùng hỗ trợ phân phối dữ liệu và cho phép truy vấn hiệu quả trong phạm vi phân vùng hợp lý. Tất cả các mục trong một phân vùng logic đều có chung giá trị khóa phân vùng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-98', 'dp-900', 98, 'You have an e-commerce application that reads from and writes data to an Azure SQL database.  
  
Which type of processing does the application use?', '[{"key":"A","text":"stream processing"},{"key":"B","text":"batch processing"},{"key":"C","text":"Online Analytical Processing (OLAP)"},{"key":"D","text":"Online Transaction Processing (OLTP)"}]'::jsonb, ARRAY['D']::text[], 'Xử lý giao dịch trực tuyến (OLTP) hỗ trợ các hoạt động đọc và ghi thường xuyên, đồng thời cho các giao dịch kinh doanh riêng lẻ, chẳng hạn như các đơn đặt hàng thương mại điện tử và cập nhật trong cơ sở dữ liệu quan hệ.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-99', 'dp-900', 99, 'Which type of Microsoft Power BI visual can you use to analyze trends over time for one or more series of values?', '[{"key":"A","text":"funnel chart"},{"key":"B","text":"pie chart"},{"key":"C","text":"table"},{"key":"D","text":"line chart"}]'::jsonb, ARRAY['D']::text[], 'Biểu đồ đường hiển thị dữ liệu liên tục dưới dạng các điểm được kết nối bằng đường và được thiết kế để hiển thị các xu hướng và mô hình theo thời gian. Họ có thể vẽ một hoặc nhiều chuỗi giá trị theo trục thời gian.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-100', 'dp-900', 100, 'Select the answer that correctly finishes the sentence.', '[]'::jsonb, ARRAY[]::text[], 'Cơ sở dữ liệu đồ thị biểu diễn các thực thể và mối quan hệ của chúng một cách trực tiếp dưới dạng các nút và cạnh, làm cho việc duyệt và phân tích mối quan hệ trở thành một khả năng nguyên gốc.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-101', 'dp-900', 101, 'You have an inventory management database that includes the following table.  
  
![Question Image](https://cdn.examcademy.com/images/questions/1783766115853-47snfklr.png)  
  
Which SQL statement should you use to change Product1''s inventory quantity to 270?', '[{"key":"A","text":"INSERT"},{"key":"B","text":"MERGE"},{"key":"C","text":"UPDATE"},{"key":"D","text":"CREATE"}]'::jsonb, ARRAY['C']::text[], 'Câu lệnh `UPDATE` sửa đổi các giá trị trong một hàng hiện có của bảng, chẳng hạn như đặt Số lượng cho Sản phẩm1 thành 270.', 'General', ARRAY['DP-900', 'General']::text[], 'https://cdn.examcademy.com/images/questions/1783766115853-47snfklr.png', 'published'),
  ('dp900-102', 'dp-900', 102, 'Match the Azure services to the relevant requirements. A service may be used once, more than once, or not at all.', '{"statements":[{"id":"output_parquet","text":"Output data to Parquet format","correctAnswer":"C"},{"id":"store_parquet","text":"Store data that is in Parquet format","correctAnswer":"A"},{"id":"persist_tabular_parquet","text":"Persist a tabular representation of data that is stored in Parquet format","correctAnswer":"C"}],"choices":[{"key":"A","text":"Azure Data Lake Storage"},{"key":"B","text":"Azure SQL Database"},{"key":"C","text":"Azure Synapse Analytics"}]}'::jsonb, ARRAY['output_parquet=C', 'store_parquet=A', 'persist_tabular_parquet=C']::text[], 'Azure Data Lake Storage lưu trữ các tệp Parquet. Azure Synapse Analytics có thể tạo các bảng bên ngoài trên dữ liệu Parquet và sử dụng CETAS để xuất kết quả truy vấn sang Azure Storage với định dạng tệp bên ngoài Parquet, cung cấp bản trình bày dạng bảng cho dữ liệu được lưu trữ dưới dạng Parquet.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-103', 'dp-900', 103, 'You are deploying a software-as-a-service (SaaS) application that needs a relational database for Online Transaction Processing (OLTP).  
  
Which Azure service should you use to support the application?', '[{"key":"A","text":"Azure Cosmos DB"},{"key":"B","text":"Azure HDInsight"},{"key":"C","text":"Azure SQL Database"},{"key":"D","text":"Azure Synapse Analytics"}]'::jsonb, ARRAY['C']::text[], 'Azure SQL Database là dịch vụ cơ sở dữ liệu quan hệ được quản lý được thiết kế cho các ứng dụng đám mây hiện đại và khối lượng công việc giao dịch. Các tầng dịch vụ của nó bao gồm khả năng dành cho các ứng dụng OLTP với tốc độ giao dịch cao và yêu cầu I/O có độ trễ thấp.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-104', 'dp-900', 104, 'What is the typical read-operation latency for media files stored in the Cool access tier of Azure Blob Storage?', '[{"key":"A","text":"a few milliseconds"},{"key":"B","text":"a few seconds"},{"key":"C","text":"a few minutes"},{"key":"D","text":"a few hours"}]'::jsonb, ARRAY['A']::text[], 'Azure Blob Storage của Cool tier là tầng truy cập trực tuyến với độ trễ thời gian tính từ mili giây đến byte đầu tiên. Độ trễ truy xuất dài hơn, tính theo giờ được liên kết với Archive tier ngoại tuyến.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-105', 'dp-900', 105, 'For each of the following statements, select **Yes** if the statement is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"Azure Databricks can consume data from Azure SQL Database","correctAnswer":"Yes"},{"id":"2","text":"Azure Databricks can consume data from Azure Event Hubs","correctAnswer":"Yes"},{"id":"3","text":"Azure Databricks can consume data from Azure Cosmos DB","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:Yes', '3:Yes']::text[], 'Azure Databricks có thể đọc Azure SQL Database thông qua JDBC. Nó có thể sử dụng dữ liệu Azure Event Hubs thông qua tích hợp Trung tâm sự kiện, bao gồm cả khối lượng công việc phát trực tuyến. Azure Cosmos DB cung cấp trình kết nối Spark mà Azure Databricks có thể sử dụng để đọc dữ liệu. Vì vậy, cả ba nguồn đều được hỗ trợ.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-106', 'dp-900', 106, 'Which statement is an example of Data Manipulation Language (DML)?', '[{"key":"A","text":"REVOKE"},{"key":"B","text":"DISABLE"},{"key":"C","text":"CREATE"},{"key":"D","text":"UPDATE"}]'::jsonb, ARRAY['D']::text[], '`UPDATE` là một câu lệnh DML vì nó sửa đổi dữ liệu hiện có trong bảng cơ sở dữ liệu.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-107', 'dp-900', 107, 'For each of the following statements, select **Yes** if the statement is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"The Cool access tier is the default tier of an Azure Storage account.","correctAnswer":"No"},{"id":"2","text":"Append blobs are optimized for random read and write operations.","correctAnswer":"No"},{"id":"3","text":"Retrieving data from the Archive access tier takes hours to complete.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:No', '3:Yes']::text[], 'Tài khoản lưu trữ v2 đa năng mới sử dụng Hot làm cấp truy cập mặc định. Các đốm màu nối thêm được tối ưu hóa cho các hoạt động nối thêm các đốm màu cuối cùng; các đốm màu trang được tối ưu hóa cho các hoạt động đọc/ghi ngẫu nhiên. Các đốm màu cấp lưu trữ đang ngoại tuyến và cần được bù nước trước khi đọc, quá trình này có thể mất hàng giờ.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-108', 'dp-900', 108, 'Match the data types to the appropriate Azure data services. Each data type may be used once, more than once, or not at all.', '{"statements":[{"id":"blob","text":"Azure Blob storage","correctAnswer":"A"},{"id":"gremlin","text":"Azure Cosmos DB Gremlin API","correctAnswer":"C"},{"id":"table","text":"Azure Table storage","correctAnswer":"B"}],"choices":[{"key":"A","text":"Image files"},{"key":"B","text":"Key/value pairs"},{"key":"C","text":"Relationships between employees"}]}'::jsonb, ARRAY['blob=A', 'gremlin=C', 'table=B']::text[], 'Azure Blob storage được tối ưu hóa cho dữ liệu phi cấu trúc, bao gồm cả hình ảnh. Azure Cosmos DB dành cho Apache Gremlin là một dịch vụ cơ sở dữ liệu đồ thị để lập mô hình và duyệt qua các mối quan hệ giữa các thực thể. Azure Table storage là kho lưu trữ khóa/giá trị.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-109', 'dp-900', 109, 'What are two applications of data visualization? Each correct answer provides a complete solution.  
  
**NOTE:** Each correct selection is worth one point.', '[{"key":"A","text":"Represent trends and patterns over time"},{"key":"B","text":"Implement machine learning to predict future values"},{"key":"C","text":"Communicate the significance of data"},{"key":"D","text":"Enforce business logic across reports"}]'::jsonb, ARRAY['A', 'C']::text[], 'Trực quan hóa dữ liệu trình bày dữ liệu dưới dạng giúp xác định xu hướng và mô hình theo thời gian dễ dàng hơn và giúp truyền đạt tầm quan trọng của dữ liệu tới khán giả.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-110', 'dp-900', 110, 'Select the option that correctly finishes the sentence.', '[]'::jsonb, ARRAY[]::text[], 'Báo cáo Power BI là một tập hợp nhiều trang trực quan. Trang tổng quan được giới hạn ở một khung vẽ duy nhất, trong khi tập dữ liệu cung cấp dữ liệu và ô là một hình ảnh trực quan được hiển thị trên trang tổng quan.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-111', 'dp-900', 111, 'Which three characteristics describe an Online Transaction Processing (OLTP) workload? Each correct answer represents a complete solution.  
  
**NOTE:** Each correct selection is worth one point.', '[{"key":"A","text":"denormalized data"},{"key":"B","text":"heavy writes and moderate reads"},{"key":"C","text":"light writes and heavy reads"},{"key":"D","text":"schema on write"},{"key":"E","text":"schema on read"},{"key":"F","text":"normalized data"}]'::jsonb, ARRAY['B', 'D', 'F']::text[], 'Khối lượng công việc OLTP xử lý nhiều giao dịch ngắn, đồng thời và thường liên quan đến hoạt động ghi nặng với số lần đọc vừa phải. Họ sử dụng lược đồ khi ghi để xác thực dữ liệu có cấu trúc trước khi lưu trữ và thường sử dụng các mô hình dữ liệu được chuẩn hóa để duy trì tính nhất quán trong giao dịch và giảm thiểu sự dư thừa.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-112', 'dp-900', 112, 'Which database type includes nodes and edges?', '[{"key":"A","text":"graph"},{"key":"B","text":"key/value"},{"key":"C","text":"columnar"},{"key":"D","text":"time series"}]'::jsonb, ARRAY['A']::text[], 'Cơ sở dữ liệu đồ thị mô hình hóa dữ liệu dưới dạng các nút (thực thể) và các cạnh (mối quan hệ), làm cho nó phù hợp để biểu diễn dữ liệu được kết nối.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-113', 'dp-900', 113, 'What is an advantage of the Azure Cosmos DB Table API compared with Azure Table storage?', '[{"key":"A","text":"provides resiliency if an Azure region fails"},{"key":"B","text":"supports partitioning"},{"key":"C","text":"provides a higher storage capacity"},{"key":"D","text":"supports a multi-master model"}]'::jsonb, ARRAY['D']::text[], 'Azure Cosmos DB cho Bảng có thể sử dụng phân phối toàn cầu Azure Cosmos DB với tính năng ghi nhiều vùng, cho phép nhiều vùng chấp nhận ghi trong cấu hình nhiều chủ. Azure Table storage sử dụng vùng ghi chính, ngay cả khi sao chép dự phòng địa lý được định cấu hình.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-114', 'dp-900', 114, 'For each statement below, select **Yes** if it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"Each Azure SQL managed instance supports multiple databases that can be accessed by using cross-database queries.","correctAnswer":"Yes"},{"id":"2","text":"Elastic pools are used to share resources across multiple instances of SQL Server on Azure Virtual Machines.","correctAnswer":"No"},{"id":"3","text":"Azure SQL Database is fully compatible with both on-premises physical instances and virtualized instances of Microsoft SQL Server.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:No']::text[], 'Azure SQL Managed Instance hỗ trợ các tính năng ở phạm vi phiên bản như truy vấn cơ sở dữ liệu chéo. Nhóm đàn hồi Azure SQL Database chia sẻ tài nguyên điện toán giữa các cơ sở dữ liệu trên cùng một máy chủ, chứ không phải các phiên bản SQL Server trên Azure virtual machines. Azure SQL Database không khớp hoàn toàn với SQL Server: một số tính năng cấp phiên bản và khả năng T-SQL không được hỗ trợ hoặc chỉ được hỗ trợ một phần.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-115', 'dp-900', 115, 'Question 115', '[]'::jsonb, ARRAY[]::text[], 'Các cạnh của cơ sở dữ liệu đồ thị mô hình hóa mối quan hệ giữa các đỉnh (nút), đại diện cho các thực thể trong biểu đồ.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-116', 'dp-900', 116, 'Question 116', '[]'::jsonb, ARRAY[]::text[], 'Khối lượng công việc hàng loạt tích lũy dữ liệu và chạy xử lý sau, thường là theo lịch trình hoặc khi xảy ra điều kiện kích hoạt. Việc xử lý dữ liệu đến trong thời gian gần như thực mô tả khối lượng công việc phát trực tuyến.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-117', 'dp-900', 117, 'Which Azure Data Factory component starts a pipeline execution?', '[{"key":"A","text":"a control flow"},{"key":"B","text":"a trigger"},{"key":"C","text":"a parameter"},{"key":"D","text":"an activity"}]'::jsonb, ARRAY['B']::text[], 'Trình kích hoạt Azure Data Factory bắt đầu chạy quy trình theo lịch trình, sự kiện hoặc cửa sổ được định cấu hình của nó.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-118', 'dp-900', 118, 'Which statement correctly characterizes data processing?', '[{"key":"A","text":"Batch processing requires that data be processed immediately upon arrival."},{"key":"B","text":"Stream processing is typically used for time-critical operations that require an instant response."},{"key":"C","text":"Stream processing is typically used for analyzing larger datasets in less time."},{"key":"D","text":"Batch processing is typically used for scenarios that require continuous, real-time insights from rapidly arriving data."}]'::jsonb, ARRAY['B']::text[], 'Xử lý luồng liên tục xử lý dữ liệu đến với độ trễ thấp và thường được sử dụng cho các hoạt động quan trọng về thời gian yêu cầu phản hồi ngay lập tức.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-119', 'dp-900', 119, 'Which Azure Cosmos DB API should be used for a graph database?', '[{"key":"A","text":"Table"},{"key":"B","text":"Cassandra"},{"key":"C","text":"Core (SQL)"},{"key":"D","text":"Gremlin"}]'::jsonb, ARRAY['D']::text[], 'API Gremlin của Azure Cosmos DB được thiết kế cho cơ sở dữ liệu đồ thị và hỗ trợ truy vấn truyền tải đồ thị bằng ngôn ngữ Apache TinkerPop Gremlin.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-120', 'dp-900', 120, 'For each of the following statements, select Yes if the statement is true. Otherwise, select No.', '{"statements":[{"id":"1","text":"Batch processing can output data to a file store","correctAnswer":"Yes"},{"id":"2","text":"Batch processing can output data to a relational database","correctAnswer":"Yes"},{"id":"3","text":"Batch processing can output data to a NoSQL database","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:Yes', '3:Yes']::text[], 'Khối lượng công việc hàng loạt có thể ghi kết quả của chúng vào kho dữ liệu phù hợp với khối lượng công việc. Kho lưu trữ tệp/đối tượng là các mục tiêu đầu ra liên tục hợp lệ, cơ sở dữ liệu quan hệ hỗ trợ các ứng dụng xử lý hàng loạt và kho lưu trữ dữ liệu NoSQL cũng là đích đến hợp lệ cho dữ liệu đã xử lý.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-121', 'dp-900', 121, 'Which file format defines names and data types for every column and uses compressed columnar storage?', '[{"key":"A","text":"HTML"},{"key":"B","text":"CSV"},{"key":"C","text":"Apache Parquet"},{"key":"D","text":"JSON"}]'::jsonb, ARRAY['C']::text[], 'Apache Parquet là một định dạng tệp hướng theo cột, nhận biết lược đồ: nó lưu trữ các cột được đặt tên, được nhập và hỗ trợ nén ở cấp độ cột để lưu trữ và truy vấn phân tích hiệu quả.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-122', 'dp-900', 122, 'You have the following T-SQL statement:  
  
```sql  
SELECT o.OrderNo, o.OrderDate, c.Address, c.City  
FROM Order AS o  
JOIN Customer AS c  
    ON o.Customer = c.ID;  
```  
  
What is the purpose of the `ON` clause?', '[{"key":"A","text":"to update data in the Customer table"},{"key":"B","text":"to match data in the Customer table to data in the Order table"},{"key":"C","text":"to define an alias for the Customer table"},{"key":"D","text":"to update data in the Order table"}]'::jsonb, ARRAY['B']::text[], 'Mệnh đề `ON` xác định điều kiện được sử dụng để nối các bảng: nó khớp giá trị `Customer` của mỗi hàng `Order` với giá trị `ID` của hàng `Customer` tương ứng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-123', 'dp-900', 123, 'You have the following SQL query.  
  
![Question Image](https://cdn.examcademy.com/images/questions/1783766254915-8yyh9kfk.png)  
  
What are dbo.Products and ProductName?', '[]'::jsonb, ARRAY[]::text[], 'Trong Transact-SQL, `INSERT INTO` đặt tên cho bảng mục tiêu. Các mã định danh trong ngoặc đơn sau tên bảng đó tạo thành danh sách cột của nó, vì vậy `ProductName` là một cột.', 'General', ARRAY['DP-900', 'General']::text[], 'https://cdn.examcademy.com/images/questions/1783766254915-8yyh9kfk.png', 'published'),
  ('dp900-124', 'dp-900', 124, 'Question 124', '[]'::jsonb, ARRAY[]::text[], 'Khóa chính xác định duy nhất mỗi hàng trong bảng cơ sở dữ liệu quan hệ và không thể chứa các giá trị trùng lặp.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-125', 'dp-900', 125, 'For each statement, select **Yes** when it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"In Azure Blob Storage, each block in a block blob is a fixed size.","correctAnswer":"No"},{"id":"2","text":"In an Azure Blob Storage account, blobs are stored in a container.","correctAnswer":"Yes"},{"id":"3","text":"In an Azure Blob Storage account that does NOT have a hierarchical namespace enabled, you can assign access at the folder level.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:Yes', '3:No']::text[], 'Các khối khối bao gồm các khối có kích thước thay đổi chứ không phải các khối có một kích thước cố định. Vùng chứa Blob sắp xếp các đốm màu trong tài khoản Azure Storage. ACL cấp thư mục phụ thuộc vào tính năng không gian tên phân cấp; không có nó, các thư mục chỉ có tiền tố tên và không hỗ trợ gán quyền truy cập cấp thư mục.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-126', 'dp-900', 126, 'Which statement is an example of Data Definition Language (DDL)?', '[{"key":"A","text":"SELECT"},{"key":"B","text":"JOIN"},{"key":"C","text":"UPDATE"},{"key":"D","text":"CREATE"}]'::jsonb, ARRAY['D']::text[], '`CREATE` là câu lệnh Ngôn ngữ định nghĩa dữ liệu vì nó tạo ra các đối tượng cơ sở dữ liệu như bảng, lược đồ, chỉ mục hoặc dạng xem. `SELECT` và `JOIN` truy xuất/kết hợp dữ liệu, trong khi `UPDATE` sửa đổi dữ liệu hiện có.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-127', 'dp-900', 127, 'You have a banking application that transfers money into and out of accounts.  
  
What type of solution is this an example of?', '[{"key":"A","text":"online transaction processing (OLTP)"},{"key":"B","text":"online analytical processing (OLAP)"},{"key":"C","text":"extract, transform and load (ETL)"},{"key":"D","text":"a data warehouse"}]'::jsonb, ARRAY['A']::text[], 'Hệ thống xử lý giao dịch trực tuyến (OLTP) xử lý các giao dịch hoạt động thường xuyên, theo thời gian thực như gửi tài khoản, rút ​​tiền và chuyển khoản trong khi vẫn duy trì tính nhất quán trong giao dịch.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-128', 'dp-900', 128, 'Question 128', '[]'::jsonb, ARRAY[]::text[], 'API Gremlin của Azure Cosmos DB là một dịch vụ cơ sở dữ liệu đồ thị mô hình hóa dữ liệu dưới dạng các đỉnh và cạnh và được truy vấn bằng ngôn ngữ truyền tải Gremlin. Ngôn ngữ truy vấn Cassandra áp dụng cho API Cassandra, trong khi LINQ thường được sử dụng với API NoSQL.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-129', 'dp-900', 129, 'Which scenario illustrates a streaming workload?', '[{"key":"A","text":"sending transactions that are older than a month to an archive"},{"key":"B","text":"sending transactions daily from point of sale (POS) devices"},{"key":"C","text":"sending telemetry data from edge devices"},{"key":"D","text":"sending cloud infrastructure metadata every 30 minutes"}]'::jsonb, ARRAY['C']::text[], 'Dữ liệu đo từ xa do các thiết bị biên phát ra được tạo liên tục và thường được nhập và xử lý dưới dạng luồng sự kiện thời gian thực. Azure Event Hubs xác định cụ thể việc nhập dữ liệu đo từ xa IoT như một trường hợp sử dụng phát trực tuyến.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-130', 'dp-900', 130, 'Question 130', '[]'::jsonb, ARRAY[]::text[], 'Power BI Các mô hình dữ liệu và báo cáo của tác giả Máy tính để bàn được xuất bản lên dịch vụ Power BI để lưu trữ và chia sẻ. Power Query chuẩn bị dữ liệu và ứng dụng điện thoại Power BI dùng để xem nội dung.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-131', 'dp-900', 131, 'Which Azure Storage service uses the key/value model?', '[{"key":"A","text":"Azure Queue"},{"key":"B","text":"Azure Files"},{"key":"C","text":"Azure Table"},{"key":"D","text":"Azure Blob"}]'::jsonb, ARRAY['C']::text[], 'Azure Table storage cung cấp kho lưu trữ khóa/thuộc tính không có sơ đồ. Mỗi thực thể được xác định bởi `PartitionKey` và `RowKey` kết hợp, tạo thành khóa chính của nó.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-132', 'dp-900', 132, 'Question 132', '[]'::jsonb, ARRAY[]::text[], 'Azure Databricks là nền tảng phân tích dựa trên Apache Spark dành cho kỹ thuật, phân tích và học máy quy mô lớn. Azure SQL Database là cơ sở dữ liệu quan hệ được quản lý, trong khi Azure Blob Storage cung cấp khả năng lưu trữ đối tượng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-133', 'dp-900', 133, 'You have an Azure SQL database that you access directly from the Internet.  
  
You recently changed your computer’s public IP address. After the IP-address change, you can no longer access the database, although you can connect to other Azure resources.  
  
What could be causing this issue?', '[{"key":"A","text":"role-based access control (RBAC)"},{"key":"B","text":"Dynamic Host Configuration Protocol (DHCP)"},{"key":"C","text":"Domain Name Service (DNS)"},{"key":"D","text":"a database-level firewall"}]'::jsonb, ARRAY['D']::text[], 'Azure SQL Database đánh giá địa chỉ IP công cộng ban đầu dựa trên các quy tắc tường lửa IP của nó. Quy tắc tường lửa cấp cơ sở dữ liệu không bao gồm địa chỉ IP công cộng mới của máy tính sẽ chặn kết nối, mặc dù vẫn có khả năng kết nối với các tài nguyên Azure khác.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-134', 'dp-900', 134, 'Question 134', '[]'::jsonb, ARRAY[]::text[], 'SQL Server trên Azure Virtual Machines là một triển khai IaaS hỗ trợ di chuyển nâng và dịch chuyển khối lượng công việc SQL Server hiện có với những thay đổi mã tối thiểu hoặc mã no. Cơ sở dữ liệu đơn lẻ và nhóm đàn hồi Azure SQL Database là các dịch vụ PaaS thường yêu cầu thích ứng thay vì di chuyển nguyên trạng môi trường máy chủ.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-135', 'dp-900', 135, 'A development team has computers running Windows 10 and Ubuntu Desktop.  
  
The developers must connect to and query an Azure SQL database from every computer. They require code-assistance features such as IntelliSense.  
  
What should the developers use?', '[{"key":"A","text":"sqlcmd"},{"key":"B","text":"Microsoft SQL Server Management Studio (SSMS)"},{"key":"C","text":"Azure Data Studio"},{"key":"D","text":"Azure Data Explorer"}]'::jsonb, ARRAY['C']::text[], 'Azure Data Studio hỗ trợ Windows và Linux, kết nối với Azure SQL và cung cấp trình soạn thảo SQL hiện đại với IntelliSense. Do đó, nó đáp ứng cả yêu cầu truy cập đa nền tảng và yêu cầu hỗ trợ mã.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-137', 'dp-900', 137, 'Which statement is an example of Data Definition Language (DDL)?', '[{"key":"A","text":"SELECT"},{"key":"B","text":"INSERT"},{"key":"C","text":"DELETE"},{"key":"D","text":"DROP"}]'::jsonb, ARRAY['D']::text[], '`DROP` là câu lệnh Ngôn ngữ định nghĩa dữ liệu vì nó loại bỏ một đối tượng cơ sở dữ liệu, chẳng hạn như bảng, dạng xem hoặc cơ sở dữ liệu, khỏi lược đồ.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-138', 'dp-900', 138, 'Which Azure Cosmos DB API should be used for a graph database?', '[{"key":"A","text":"Table"},{"key":"B","text":"Cassandra"},{"key":"C","text":"NoSQL"},{"key":"D","text":"Gremlin"}]'::jsonb, ARRAY['D']::text[], 'Azure Cosmos DB dành cho Apache Gremlin là dịch vụ cơ sở dữ liệu đồ thị được quản lý. Nó lưu trữ, truy vấn và duyệt dữ liệu đồ thị bằng cách sử dụng ngôn ngữ truyền tải đồ thị Gremlin.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-139', 'dp-900', 139, 'Question 139', '[]'::jsonb, ARRAY[]::text[], 'Azure Data Explorer sử dụng Ngôn ngữ truy vấn Kusto (KQL) làm ngôn ngữ truy vấn chính để khám phá, lọc và tổng hợp dữ liệu.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-140', 'dp-900', 140, 'Question 140', '[]'::jsonb, ARRAY[]::text[], 'Cơ sở dữ liệu quan hệ sử dụng khóa chính để xác định các hàng và khóa ngoại nhằm thiết lập và thực thi mối quan hệ giữa các bảng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-141', 'dp-900', 141, 'You have a Windows-based application that needs access to a mapped drive.  
  
Which Azure service should you use?', '[{"key":"A","text":"Azure Files"},{"key":"B","text":"Azure Blob storage"},{"key":"C","text":"Azure Cosmos DB"},{"key":"D","text":"Azure Table storage"}]'::jsonb, ARRAY['A']::text[], 'Azure Files cung cấp tính năng chia sẻ tệp SMB được quản lý mà Windows có thể gắn kết và gán ký tự ổ đĩa, đáp ứng yêu cầu ứng dụng cho ổ đĩa được ánh xạ.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-142', 'dp-900', 142, 'Question 142', '[]'::jsonb, ARRAY[]::text[], 'JSON biểu thị dữ liệu với các trường được đặt tên và cấu trúc lồng nhau, đồng thời cho phép các bản ghi hoặc thực thể có các trường khác nhau. Lược đồ linh hoạt đó làm cho nó trở thành dữ liệu bán cấu trúc.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-143', 'dp-900', 143, 'Your company is developing an application that will write a large volume of JSON data and use an application-defined schema.  
  
Which type of data store should you use?', '[{"key":"A","text":"columnar"},{"key":"B","text":"key/value"},{"key":"C","text":"document"},{"key":"D","text":"graph"}]'::jsonb, ARRAY['C']::text[], 'Kho lưu trữ dữ liệu tài liệu được thiết kế cho khối lượng lớn dữ liệu JSON bán cấu trúc và hỗ trợ các lược đồ tài liệu linh hoạt, do ứng dụng xác định.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-144', 'dp-900', 144, 'You need to recommend a non-relational data store optimized to store and retrieve text files, videos, audio streams, and virtual disk images. The data store must retain the data, some metadata, and a unique ID for every file.  
  
Which type of data store should you recommend?', '[{"key":"A","text":"key/value"},{"key":"B","text":"columnar"},{"key":"C","text":"object"},{"key":"D","text":"document"}]'::jsonb, ARRAY['C']::text[], 'Lưu trữ đối tượng lưu trữ dữ liệu phi cấu trúc dưới dạng các đối tượng riêng biệt, mỗi đối tượng bao gồm chính dữ liệu đó, siêu dữ liệu liên quan và một mã định danh đối tượng duy nhất. Nó được thiết kế cho các tệp lớn như phương tiện và hình ảnh đĩa ảo.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-145', 'dp-900', 145, 'In a fully denormalized database, how are data read and written for one entity?', '[{"key":"A","text":"Data is read from a single table and written to a single table."},{"key":"B","text":"Data is read from multiple tables and written to a single table."},{"key":"C","text":"Data is read from a single table and written to multiple tables."},{"key":"D","text":"Data is read from multiple tables and written to multiple tables."}]'::jsonb, ARRAY['A']::text[], 'Một thiết kế không chuẩn hóa hoàn toàn sẽ lưu trữ tất cả các thuộc tính của một thực thể cùng nhau trong một bảng, tránh việc kết hợp giữa các bảng có liên quan. Do đó, đọc và ghi cho thực thể đó nhắm mục tiêu vào một bảng duy nhất.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-146', 'dp-900', 146, 'Which task is a data engineer responsible for?', '[{"key":"A","text":"Explore data to identify trends."},{"key":"B","text":"Implement policies, tools, and processes for backup and recovery plans."},{"key":"C","text":"Design and build analytical models."},{"key":"D","text":"Design and implement data stores for analytical workloads."}]'::jsonb, ARRAY['D']::text[], 'Kỹ sư dữ liệu triển khai các tạo phẩm liên quan đến dữ liệu, bao gồm các kho dữ liệu hỗ trợ khối lượng công việc phân tích. Vai trò của họ là cung cấp cơ sở hạ tầng dữ liệu đáng tin cậy, hiệu quả cho hoạt động phân tích tiếp theo.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-147', 'dp-900', 147, 'What is one function of a modern data warehouse?', '[{"key":"A","text":"supports batch processing only"},{"key":"B","text":"supports real-time and batch processing"},{"key":"C","text":"provides built-in or native online analytical processing"},{"key":"D","text":"stores raw data only"}]'::jsonb, ARRAY['B']::text[], 'Dữ liệu hiện đại warehouse hỗ trợ cả xử lý hàng loạt và theo thời gian thực để các tổ chức có thể phân tích dữ liệu mới đến cùng với dữ liệu được tải trong lịch sử.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-148', 'dp-900', 148, 'Which schema-design process reduces data duplication and ensures data integrity?', '[{"key":"A","text":"normalization"},{"key":"B","text":"batch processing"},{"key":"C","text":"extraction"},{"key":"D","text":"virtualization"}]'::jsonb, ARRAY['A']::text[], 'Chuẩn hóa cấu trúc các bảng quan hệ để giảm dữ liệu dư thừa và thực thi các phụ thuộc hợp lệ, giúp duy trì tính toàn vẹn của dữ liệu.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-149', 'dp-900', 149, 'For each of the following statements, select **Yes** if it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"Processing salary payments once a month is an example of a batch workload.","correctAnswer":"Yes"},{"id":"2","text":"A wind turbine that sends 50 sensor readings per second is an example of a streaming workload.","correctAnswer":"Yes"},{"id":"3","text":"A home electricity meter that sends readings once a day to an energy provider is an example of a streaming workload.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:Yes', '3:No']::text[], 'Các khoản thanh toán lương hàng tháng được tích lũy và xử lý theo lịch trình, tức là xử lý theo đợt. Số đọc cảm biến đến 50 lần mỗi giây tạo thành một luồng sự kiện liên tục đang phát trực tuyến. Việc đọc đồng hồ đo hàng ngày là việc thu thập định kỳ, theo lịch trình chứ không phải là một đợt liên tục.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-150', 'dp-900', 150, 'Which two activities can be completed entirely by using the Microsoft Power BI service, without relying on Power BI Desktop? Each correct answer provides a complete solution.  
  
**NOTE:** Each correct selection is worth one point.', '[{"key":"A","text":"report and dashboard creation"},{"key":"B","text":"report sharing and distribution"},{"key":"C","text":"data modeling"},{"key":"D","text":"data acquisition and preparation"}]'::jsonb, ARRAY['A', 'B']::text[], 'Dịch vụ Power BI hỗ trợ tạo báo cáo trên trình duyệt và tạo bảng chỉ số từ báo cáo. Nó cũng cung cấp các tính năng cộng tác và phân phối để chia sẻ báo cáo và bảng chỉ số với những người dùng khác. Máy tính để bàn Power BI là môi trường chính để chuyển đổi và lập mô hình dữ liệu. [Microsoft Learn: What is Power BI?](https://learn.microsoft.com/en-us/power-bi/fundamentals/power-bi-overview)', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-151', 'dp-900', 151, 'You have a data store with the structure illustrated in the following exhibit.  
  
![Question Image](https://cdn.examcademy.com/images/questions/1783769025515-29ixf62d.png)  
  
What type of data store is this?', '[{"key":"A","text":"key/value"},{"key":"B","text":"object data"},{"key":"C","text":"graph"},{"key":"D","text":"time series"}]'::jsonb, ARRAY['C']::text[], 'Kho dữ liệu đồ thị mô hình hóa các thực thể dưới dạng nút và các kết nối của chúng dưới dạng mối quan hệ. Nhân viên và các phòng ban được kết nối thông qua các mối quan hệ như đường dây báo cáo và thành viên phòng ban.', 'General', ARRAY['DP-900', 'General']::text[], 'https://cdn.examcademy.com/images/questions/1783769025515-29ixf62d.png', 'published'),
  ('dp900-152', 'dp-900', 152, 'Which Azure Cosmos DB API stores data in BSON format and uses MQL to query that data?', '[{"key":"A","text":"MongoDB"},{"key":"B","text":"Apache Gremlin"},{"key":"C","text":"Table"},{"key":"D","text":"PostgreSQL"}]'::jsonb, ARRAY['A']::text[], 'Azure Cosmos DB dành cho MongoDB hỗ trợ các tài liệu được mã hóa ở định dạng BSON và truy vấn Ngôn ngữ truy vấn MongoDB (MQL).', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-153', 'dp-900', 153, 'What are two advantages of platform as a service (PaaS) relational database offerings in Azure, such as Azure SQL Database? Each correct answer provides a complete solution.  
  
**NOTE:** Each correct selection is worth one point.', '[{"key":"A","text":"access to the latest features"},{"key":"B","text":"complete control over backup and restore processes"},{"key":"C","text":"in-database machine learning services"},{"key":"D","text":"reduced administrative effort for managing the server infrastructure"}]'::jsonb, ARRAY['A', 'D']::text[], 'Azure SQL Database là một sản phẩm PaaS được quản lý hoàn toàn, được lưu giữ trên công cụ cơ sở dữ liệu SQL Server ổn định mới nhất và hệ điều hành được vá lỗi. Microsoft quản lý công cụ cơ sở dữ liệu, hệ điều hành và phần cứng cơ bản, giảm bớt công việc quản trị cần thiết để quản lý cơ sở hạ tầng máy chủ.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-154', 'dp-900', 154, 'Your company must design a database that shows how network-traffic changes in one area of a network affect traffic in other network areas.  
  
Which type of data store should you use?', '[{"key":"A","text":"graph"},{"key":"B","text":"key/value"},{"key":"C","text":"document"},{"key":"D","text":"columnar"}]'::jsonb, ARRAY['A']::text[], 'Kho lưu trữ dữ liệu biểu đồ biểu thị các khu vực mạng dưới dạng nút và các kết nối hoặc phụ thuộc lưu lượng truy cập của chúng dưới dạng các cạnh, cho phép truyền tải và phân tích hiệu quả về cách thay đổi lan truyền qua các khu vực được kết nối. Cơ sở dữ liệu đồ thị được tối ưu hóa để lưu trữ và truy vấn mối quan hệ giữa các mục dữ liệu có tính kết nối cao.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-155', 'dp-900', 155, 'Within Azure Table storage, which two components uniquely identify each row in a table? Each correct answer represents part of the solution.  
  
**NOTE:** Each correct selection is worth one point.', '[{"key":"A","text":"a partition key"},{"key":"B","text":"a range"},{"key":"C","text":"a row key"},{"key":"D","text":"a timestamp"}]'::jsonb, ARRAY['A', 'C']::text[], 'Một thực thể Azure Table Storage được xác định duy nhất bằng sự kết hợp giữa Khóa phân vùng và Khóa hàng của nó. DiskKey xác định phân vùng và RowKey xác định một thực thể trong phân vùng đó; Dấu thời gian được duy trì để hoạt động đồng thời lạc quan hơn là đóng vai trò như một phần của khóa thực thể.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-156', 'dp-900', 156, 'Which Azure Data Factory component supplies the compute environment for activities?', '[{"key":"A","text":"SSIS packages"},{"key":"B","text":"an integration runtime"},{"key":"C","text":"a control flow"},{"key":"D","text":"a pipeline"}]'::jsonb, ARRAY['B']::text[], 'integration runtime cung cấp cơ sở hạ tầng điện toán và môi trường thực thi hoặc điều phối cho các hoạt động Azure Data Factory. Quy trình và luồng điều khiển xác định và điều phối công việc, trong khi các gói SSIS là khối lượng công việc thực thi có thể chạy trên Azure-SSIS integration runtime.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-157', 'dp-900', 157, 'You have a quality-assurance application that reads data from a data warehouse.  
  
What type of processing does the application use?', '[{"key":"A","text":"Online Transaction Processing (OLTP)"},{"key":"B","text":"batch processing"},{"key":"C","text":"Online Analytical Processing (OLAP)"},{"key":"D","text":"stream processing"}]'::jsonb, ARRAY['C']::text[], 'Xử lý phân tích trực tuyến (OLAP) được sử dụng để truy vấn và phân tích dữ liệu được lưu trữ trong dữ liệu warehouse để báo cáo, đảm bảo chất lượng và ra quyết định.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-158', 'dp-900', 158, 'Question 158', '[]'::jsonb, ARRAY[]::text[], 'Azure Cosmos DB cho Apache Gremlin là API cơ sở dữ liệu đồ thị. Nó biểu diễn các đồ thị thuộc tính với các đỉnh (nút) và các cạnh, đồng thời các truy vấn và phép duyệt sử dụng ngôn ngữ Gremlin.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-159', 'dp-900', 159, 'For each of the following statements, select **Yes** when the statement is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"The pgAdmin tool can be used to manage Azure Database for PostgreSQL.","correctAnswer":"Yes"},{"id":"2","text":"Azure Database for MariaDB offers point-in-time restore for up to 365 days.","correctAnswer":"No"},{"id":"3","text":"Azure Database for MySQL always requires SSL connections.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:No']::text[], 'pgAdmin là ứng dụng khách được hỗ trợ để kết nối với Cơ sở dữ liệu Azure cho PostgreSQL và quản trị các đối tượng cơ sở dữ liệu. Cơ sở dữ liệu Azure để lưu giữ bản sao lưu MariaDB để khôi phục tại thời điểm được tính bằng ngày và không kéo dài đến 365 ngày. Cơ sở dữ liệu Azure cho MySQL cho phép vô hiệu hóa việc thực thi TLS, do đó có thể cho phép các kết nối không được mã hóa.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-160', 'dp-900', 160, 'Match the Azure Cosmos DB APIs with the corresponding data structures.  
  
An API may be used once, more than once, or not at all.', '{"statements":[{"id":"graph-data","text":"Graph data","correctAnswer":"B"},{"id":"json-documents","text":"JSON documents","correctAnswer":"C"},{"id":"key-value-data","text":"Key/value data","correctAnswer":"D"}],"choices":[{"key":"A","text":"Azure Cosmos DB for Apache Cassandra API"},{"key":"B","text":"Azure Cosmos DB for Apache Gremlin API"},{"key":"C","text":"Azure Cosmos DB for NoSQL API"},{"key":"D","text":"Azure Cosmos DB for Table API"}]}'::jsonb, ARRAY['graph-data=B', 'json-documents=C', 'key-value-data=D']::text[], 'Azure Cosmos DB dành cho Apache Gremlin được thiết kế cho dữ liệu biểu đồ thuộc tính, bao gồm các đỉnh và cạnh. Azure Cosmos DB dành cho NoSQL sử dụng các mục tài liệu JSON linh hoạt. Azure Cosmos DB dành cho Bảng được tối ưu hóa cho dữ liệu dạng bảng và khóa-giá trị, với các thực thể được xác định bằng các khóa phân vùng và hàng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-161', 'dp-900', 161, 'Question 161', '[]'::jsonb, ARRAY[]::text[], 'Phân tích mô tả tóm tắt hoặc trực quan hóa dữ liệu hiện tại và lịch sử. So sánh số lượng tuyển sinh hiện tại với số lượng tối đa sẽ mô tả mức độ sử dụng hiện tại của trường đại học; nó không dự đoán việc tuyển sinh trong tương lai cũng như không đưa ra quyết định.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-162', 'dp-900', 162, 'You need to implement an Azure platform-as-a-service (PaaS) offering to host a relational database. The solution must provide built-in autoscaling.  
  
Which service should you implement?', '[{"key":"A","text":"Azure SQL Database"},{"key":"B","text":"SQL Server on Azure Virtual Machines"},{"key":"C","text":"Azure SQL Managed Instance"},{"key":"D","text":"Azure SQL Edge"}]'::jsonb, ARRAY['A']::text[], 'Azure SQL Database là dịch vụ cơ sở dữ liệu quan hệ PaaS. Tầng điện toán không có máy chủ của nó tự động điều chỉnh quy mô tài nguyên điện toán trong phạm vi được định cấu hình theo nhu cầu khối lượng công việc, cung cấp tính năng tự động điều chỉnh quy mô tích hợp.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-163', 'dp-900', 163, 'For each of the following statements, select **Yes** when the statement is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"If you have a platform as a service (PaaS) database in Azure, you are responsible for applying operating system updates.","correctAnswer":"No"},{"id":"2","text":"If you have a platform as a service (PaaS) database in Azure, backups are performed automatically.","correctAnswer":"Yes"},{"id":"3","text":"If you have a platform as a service (PaaS) database in Azure, you are responsible for installation of the database engine.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:Yes', '3:No']::text[], 'Các dịch vụ cơ sở dữ liệu Azure PaaS được quản lý bởi Microsoft: Azure áp dụng các bản vá và nâng cấp hệ điều hành và công cụ cơ sở dữ liệu, đồng thời dịch vụ này tự động thực hiện sao lưu. Khách hàng quản lý dữ liệu, cấu hình, quyền truy cập và quản trị cơ sở dữ liệu cấp ứng dụng của họ thay vì cài đặt hoặc bảo trì công cụ và hệ điều hành cơ bản.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-164', 'dp-900', 164, 'Question 164', '[]'::jsonb, ARRAY[]::text[], 'JSON biểu thị dữ liệu bằng cách sử dụng các đối tượng lồng nhau và các cặp tên/giá trị, cho phép các thực thể phân cấp có nhiều thuộc tính. CSV và TSV là các định dạng được phân cách bằng bảng và ORC là định dạng lưu trữ theo cột.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-165', 'dp-900', 165, 'You have a SQL query that joins customer data with order data and includes calculated columns.  
  
You need to create a database object that enables other users to run the same SQL query again. What should you create?', '[{"key":"A","text":"an index"},{"key":"B","text":"a view"},{"key":"C","text":"a scalar function"},{"key":"D","text":"a table"}]'::jsonb, ARRAY['B']::text[], 'Chế độ xem là một đối tượng cơ sở dữ liệu được xác định bởi truy vấn SQL đã lưu. Nó có thể kết hợp dữ liệu khách hàng và đơn đặt hàng, đồng thời bao gồm các cột được tính toán, cho phép người dùng chạy lại truy vấn bằng cách chọn từ chế độ xem.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-166', 'dp-900', 166, 'Which service is optimized for IoT scenarios involving streaming time-series data?', '[{"key":"A","text":"SQL Server on Azure Virtual Machines"},{"key":"B","text":"Azure SQL Managed Instance"},{"key":"C","text":"Azure SQL Database"},{"key":"D","text":"Azure SQL Edge"}]'::jsonb, ARRAY['D']::text[], 'Azure SQL Edge được tối ưu hóa cho việc triển khai IoT ở biên và cung cấp khả năng truyền phát tích hợp để phân tích thời gian thực và xử lý sự kiện phức tạp đối với dữ liệu chuỗi thời gian do thiết bị tạo.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-167', 'dp-900', 167, 'Match each storage solution with its appropriate description.  
  
Each solution can be used once, more than once, or not at all.', '{"statements":[{"id":"slot1","text":"Stores a large amount of unstructured data.","correctAnswer":"A"},{"id":"slot2","text":"A cloud-based network share.","correctAnswer":"B"},{"id":"slot3","text":"A NoSQL storage solution that stores key/value data items.","correctAnswer":"D"}],"choices":[{"key":"A","text":"Azure Blob storage"},{"key":"B","text":"Azure Files"},{"key":"C","text":"Azure SQL Database"},{"key":"D","text":"Azure Table storage"}]}'::jsonb, ARRAY['slot1=A', 'slot2=B', 'slot3=D']::text[], 'Azure Blob storage là một kho lưu trữ đối tượng được tối ưu hóa cho lượng lớn dữ liệu phi cấu trúc. Azure Files cung cấp khả năng chia sẻ tệp đám mây được quản lý hoàn toàn có thể truy cập được thông qua các giao thức chia sẻ tệp tiêu chuẩn. Azure Table storage là kho lưu trữ khóa/thuộc tính NoSQL không có sơ đồ. Azure SQL Database mang tính chất quan hệ và không phù hợp với những mô tả này.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-168', 'dp-900', 168, 'A bar chart that displays year-to-date sales by region is an example of which type of analytics?', '[{"key":"A","text":"predictive"},{"key":"B","text":"prescriptive"},{"key":"C","text":"descriptive"},{"key":"D","text":"diagnostic"}]'::jsonb, ARRAY['C']::text[], 'Phân tích mô tả tóm tắt dữ liệu lịch sử hoặc hiện tại để hiển thị những gì đã xảy ra, chẳng hạn như doanh số bán hàng từ đầu năm đến nay ở các khu vực.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-169', 'dp-900', 169, 'For each of the following statements, select Yes if the statement is true. Otherwise, select No.', '{"statements":[{"id":"1","text":"Azure Data Lake storage can be used as a staging area for ingested data before the data is converted into a format suitable for performing analytics.","correctAnswer":"Yes"},{"id":"2","text":"Azure Data Factory is an analytics engine that uses a massively parallel processing (MPP) architecture.","correctAnswer":"No"},{"id":"3","text":"Azure HDInsight enables you to build tabular models from multiple data sources to support online analytical processing (OLAP) queries.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:No']::text[], 'Azure Data Lake Storage có thể xử lý dữ liệu nguồn thô trước khi tải và chuyển đổi để phân tích. Azure Data Factory điều phối các quy trình chuyển đổi và di chuyển dữ liệu; Azure Synapse Analytics là công cụ phân tích MPP. Dịch vụ phân tích Azure, thay vì HDInsight, cung cấp các mô hình ngữ nghĩa dạng bảng để phân tích kiểu OLAP.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-170', 'dp-900', 170, 'Which two capabilities differentiate Delta Lake from Azure Data Lake Storage? Each correct answer provides a complete solution.  
  
**NOTE:** Each correct selection is worth one point.', '[{"key":"A","text":"support for batch data"},{"key":"B","text":"schema enforcement"},{"key":"C","text":"support for an Apache Spark runtime"},{"key":"D","text":"transactional consistency"},{"key":"E","text":"support for streaming data"}]'::jsonb, ARRAY['B', 'D']::text[], 'Delta Lake bổ sung tính năng thực thi lược đồ để xác thực dữ liệu được ghi vào bảng và tính nhất quán của giao dịch ACID thông qua nhật ký giao dịch của nó. Azure Data Lake Storage là dịch vụ lưu trữ cơ bản; Delta Lake cung cấp các khả năng quản trị và độ tin cậy ở cấp độ bảng này.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-171', 'dp-900', 171, 'You have a database that stores data in the format shown in the following table.  
  
![Question Image](https://cdn.examcademy.com/images/questions/1783776382042-ez1qlfrm.png)  
  
What type of database does this represent?', '[{"key":"A","text":"column family"},{"key":"B","text":"relational"},{"key":"C","text":"key-value"},{"key":"D","text":"document"}]'::jsonb, ARRAY['A']::text[], 'Dữ liệu được sắp xếp dưới dạng khóa hàng (Khóa) cộng với hai nhóm cột liên quan - Khách hàng (Tên, Địa chỉ) và Sản phẩm (Tên, Giá). Việc nhóm các cột thành các họ có liên quan về mặt logic được xác định bằng khóa hàng là đặc điểm xác định của kho lưu trữ họ cột (cột rộng), chẳng hạn như Apache Cassandra hoặc Azure Cosmos DB cho Cassandra. Cơ sở dữ liệu tài liệu sẽ lưu trữ từng mục dưới dạng tài liệu JSON/BSON tự mô tả, kho lưu trữ khóa-giá trị sẽ ánh xạ khóa tới một giá trị mờ duy nhất và cơ sở dữ liệu quan hệ sử dụng các bảng phẳng với các mối quan hệ khóa ngoài thay vì các nhóm cột lồng nhau. Vì vậy, điều này đại diện cho một cơ sở dữ liệu họ cột.', 'General', ARRAY['DP-900', 'General']::text[], 'https://cdn.examcademy.com/images/questions/1783776382042-ez1qlfrm.png', 'published'),
  ('dp900-172', 'dp-900', 172, 'What is one primary characteristic of a relational database?', '[{"key":"A","text":"a flexible data structure"},{"key":"B","text":"data is queried and manipulated by using a variant of the SQL language"},{"key":"C","text":"a lack of dependencies between tables"},{"key":"D","text":"a large amount of duplicate data"}]'::jsonb, ARRAY['B']::text[], 'Cơ sở dữ liệu quan hệ lưu trữ dữ liệu trong các bảng liên quan và sử dụng SQL hoặc một phương ngữ của SQL để truy vấn và thao tác dữ liệu đó.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-173', 'dp-900', 173, 'Question 173', '[]'::jsonb, ARRAY[]::text[], 'Cơ sở dữ liệu quan hệ lưu trữ thông tin trong các bảng (quan hệ), với các bản ghi được biểu thị dưới dạng hàng và các thuộc tính được biểu thị dưới dạng cột.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-174', 'dp-900', 174, 'Question 174', '[]'::jsonb, ARRAY[]::text[], 'Nhóm SQL chuyên dụng Azure Synapse Analytics sử dụng kiến ​​trúc MPP: nút điều khiển phối hợp và phân phối các truy vấn đến các nút tính toán, các nút này thực thi xử lý song song.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-175', 'dp-900', 175, 'Which Azure Blob Storage feature lets you synchronize a Blob Storage account with an external cache?', '[{"key":"A","text":"the Hot access tier"},{"key":"B","text":"change feed"},{"key":"C","text":"snapshots"},{"key":"D","text":"versioning"}]'::jsonb, ARRAY['B']::text[], 'Nguồn cấp dữ liệu thay đổi cung cấp nhật ký lâu dài, có trật tự về các thay đổi đối với siêu dữ liệu blob và blob mà các ứng dụng khách có thể sử dụng để đồng bộ hóa bộ đệm. Microsoft Learn liệt kê việc đồng bộ hóa với bộ nhớ đệm dưới dạng kịch bản thay đổi nguồn cấp dữ liệu.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-176', 'dp-900', 176, 'In what form is raw data stored in a data lakehouse?', '[{"key":"A","text":"as tables"},{"key":"B","text":"as queues"},{"key":"C","text":"as files"},{"key":"D","text":"as disks"}]'::jsonb, ARRAY['C']::text[], 'Dữ liệu lakehouse giữ lại dữ liệu thô dưới dạng tệp trong đối tượng có thể mở rộng hoặc bộ lưu trữ phân tán. Các định nghĩa bảng cung cấp cấu trúc logic và lớp siêu dữ liệu trên các tệp cơ bản đó.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-177', 'dp-900', 177, 'Question 177', '[]'::jsonb, ARRAY[]::text[], 'MAX và MIN là các hàm tổng hợp: chúng trả về giá trị tối đa và tối thiểu tương ứng trên một tập hợp các hàng hoặc giá trị.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-178', 'dp-900', 178, 'You need to create an Azure Storage account. Data in the account must be replicated automatically outside the Azure region.  
  
Which two replication types can you use for the storage account? Each correct answer provides a complete solution.  
  
**NOTE:** Each correct selection is worth one point.', '[{"key":"A","text":"zone-redundant storage (ZRS)"},{"key":"B","text":"read-access geo-redundant storage (RA-GRS)"},{"key":"C","text":"locally-redundant storage (LRS)"},{"key":"D","text":"geo-redundant storage (GRS)"}]'::jsonb, ARRAY['B', 'D']::text[], 'Geo-redundant storage (GRS) sao chép không đồng bộ dữ liệu tài khoản lưu trữ sang vùng Azure phụ. Truy cập đọc geo-redundant storage (RA-GRS) cũng sao chép dữ liệu sang vùng thứ cấp và bổ sung cho phép quyền truy cập đọc vào điểm cuối phụ đó. LRS được giới hạn ở một trung tâm dữ liệu và ZRS đến availability zones trong khu vực chính.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-179', 'dp-900', 179, 'In Azure Blob Storage, blob rehydration happens when a blob moves between which access tiers?', '[{"key":"A","text":"Hot to Cool"},{"key":"B","text":"Hot to Archive"},{"key":"C","text":"Cool to Archive"},{"key":"D","text":"Archive to Cool"}]'::jsonb, ARRAY['D']::text[], 'Archive tier đang ngoại tuyến. Việc di chuyển một blob đã lưu trữ sang Cool tier trực tuyến yêu cầu phải bù nước để blob có sẵn để truy cập.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-180', 'dp-900', 180, 'Question 180', '[]'::jsonb, ARRAY[]::text[], 'CSV lưu trữ các giá trị dạng bảng ở định dạng văn bản được phân tách bằng dấu phân cách, thường sử dụng dấu phẩy.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-181', 'dp-900', 181, 'Question 181', '[]'::jsonb, ARRAY[]::text[], 'Các tệp chứa đối tượng Avro lưu trữ lược đồ JSON trong tiêu đề của chúng và tuần tự hóa các bản ghi dữ liệu ở dạng nhị phân. Sàn gỗ và ORC là các định dạng lưu trữ theo cột; XML dựa trên văn bản.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-182', 'dp-900', 182, 'You need to run hybrid transactional and analytical processing (HTAP) queries against Azure Cosmos DB data sources by using Azure Synapse Analytics.  
  
What should you use?', '[{"key":"A","text":"Synapse pipelines"},{"key":"B","text":"a Synapse SQL pool"},{"key":"C","text":"Synapse Link"},{"key":"D","text":"Synapse Studio"}]'::jsonb, ARRAY['C']::text[], 'Azure Synapse Link cho Azure Cosmos DB cung cấp tích hợp HTAP trên nền tảng đám mây cho phép truy vấn phân tích gần như theo thời gian thực đối với dữ liệu Azure Cosmos DB đang hoạt động thông qua Azure Synapse Analytics.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-183', 'dp-900', 183, 'You need to analyze data by using Azure Databricks.  
  
Which two methods can achieve this goal? Each correct answer provides a complete solution.  
  
**NOTE:** Each correct selection is worth one point.', '[{"key":"A","text":"Create a Microsoft Power BI report."},{"key":"B","text":"Create an Azure Data Factory pipeline."},{"key":"C","text":"Use an Apache Spark job to process data stored in an Azure Cosmos DB database."},{"key":"D","text":"Create a data flow in Azure Data Factory."},{"key":"E","text":"Create an Apache Spark job that will run in a Spark cluster."}]'::jsonb, ARRAY['C', 'E']::text[], 'Azure Databricks chạy khối lượng công việc Apache Spark trên cụm điện toán Spark. Trình kết nối Azure Cosmos DB Spark cho phép Spark đọc và xử lý dữ liệu Azure Cosmos DB, do đó, công việc Spark có thể phân tích dữ liệu đó trong Azure Databricks.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-184', 'dp-900', 184, 'Match each workload type to its appropriate scenario.  
  
Each workload type may be used once, more than once, or not at all.', '{"statements":[{"id":"slot1","text":"Analyzing historical data containing web traffic collected during the previous year.","correctAnswer":"A"},{"id":"slot2","text":"Classifying images that were uploaded last month.","correctAnswer":"A"},{"id":"slot3","text":"Tracking in real time how many people are currently using a website.","correctAnswer":"B"}],"choices":[{"key":"A","text":"Batch"},{"key":"B","text":"Streaming"}]}'::jsonb, ARRAY['slot1=A', 'slot2=A', 'slot3=B']::text[], 'Khối lượng công việc hàng loạt xử lý dữ liệu tích lũy theo khoảng thời gian đã lên lịch hoặc muộn hơn, phù hợp với lưu lượng truy cập web của năm trước và hình ảnh được tải lên vào tháng trước. Khối lượng công việc phát trực tuyến xử lý các sự kiện liên tục đến với độ trễ thấp, phù hợp với việc theo dõi thời gian thực của người dùng trang web đang hoạt động.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-185', 'dp-900', 185, 'Which Azure resource type supports configuring an Azure SQL database as serverless?', '[{"key":"A","text":"SQL Server on Azure Virtual Machines"},{"key":"B","text":"an Azure SQL Database elastic pool"},{"key":"C","text":"a single database in Azure SQL Database"},{"key":"D","text":"Azure SQL Managed Instance"}]'::jsonb, ARRAY['C']::text[], 'Tầng điện toán không có máy chủ có sẵn cho các cơ sở dữ liệu đơn lẻ trong Azure SQL Database. Nó tự động điều chỉnh quy mô điện toán theo nhu cầu khối lượng công việc và có thể tạm dừng khi không hoạt động; thay vào đó, các nhóm đàn hồi sử dụng tài nguyên điện toán được cung cấp chung.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-186', 'dp-900', 186, 'You need to store data by using Azure Table storage.  
  
What should you create initially?', '[{"key":"A","text":"an Azure Cosmos DB instance"},{"key":"B","text":"a storage account"},{"key":"C","text":"a blob container"},{"key":"D","text":"a table"}]'::jsonb, ARRAY['B']::text[], 'Tài khoản Azure Storage cung cấp không gian tên cho các dịch vụ Azure Storage, bao gồm Azure Table Storage. Một bảng được tạo trong tài khoản đó nên tài khoản lưu trữ phải được tạo trước.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-187', 'dp-900', 187, 'Question 187', '[]'::jsonb, ARRAY[]::text[], 'CẬP NHẬT là một câu lệnh DML vì nó thay đổi dữ liệu trong các hàng hiện có của bảng. CREATE, DROP và RENAME sửa đổi các đối tượng cơ sở dữ liệu và là các câu lệnh DDL.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-188', 'dp-900', 188, 'Your company intends to load data from a customer relationship management (CRM) system into a data warehouse through an extract, load, and transform (ELT) process.  
  
Identify where data processing takes place at each ELT stage. Each location may be used once, multiple times, or not at all.', '{"statements":[{"id":"extract","text":"Extract:","correctAnswer":"B"},{"id":"load","text":"Load:","correctAnswer":"C"},{"id":"transform","text":"Transform:","correctAnswer":"C"}],"choices":[{"key":"A","text":"An in-memory data integration tool"},{"key":"B","text":"The CRM system"},{"key":"C","text":"The data warehouse"}]}'::jsonb, ARRAY['extract=B', 'load=C', 'transform=C']::text[], 'ELT trích xuất dữ liệu từ nguồn CRM và tải dữ liệu đó vào dữ liệu đích warehouse. Sau đó, các phép biến đổi sẽ chạy trong dữ liệu warehouse, sử dụng công cụ xử lý của nó thay vì công cụ tích hợp trong bộ nhớ bên ngoài.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-189', 'dp-900', 189, 'Question 189', '[]'::jsonb, ARRAY[]::text[], 'Dữ liệu warehouse là kho lưu trữ tập trung tích hợp dữ liệu từ nhiều nguồn cho khối lượng công việc báo cáo và phân tích.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-190', 'dp-900', 190, 'Match each term with its appropriate description.  
  
Each term may be used once, more than once, or not at all.', '{"statements":[{"id":"slot1","text":"A solution that copies data from files and online transaction processing (OLTP) databases to an analytical processing system.","correctAnswer":"C"},{"id":"slot2","text":"Contains numeric values that can be analyzed.","correctAnswer":"D"},{"id":"slot3","text":"A solution that stores data in a relational schema that is optimized for read operations.","correctAnswer":"A"}],"choices":[{"key":"A","text":"Data warehouses"},{"key":"B","text":"Dimension tables"},{"key":"C","text":"Extract, transform, and load (ETL)"},{"key":"D","text":"Fact tables"},{"key":"E","text":"Online analytical processing (OLAP)"}]}'::jsonb, ARRAY['slot1=C', 'slot2=D', 'slot3=A']::text[], 'ETL trích xuất dữ liệu từ các nguồn hoạt động và dựa trên tệp, chuyển đổi dữ liệu và tải dữ liệu đó vào đích phân tích. Bảng sự kiện lưu trữ các thước đo định lượng để phân tích. Kho dữ liệu sử dụng các cấu trúc quan hệ được tối ưu hóa cho các truy vấn phân tích và khối lượng công việc đọc nhiều.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-191', 'dp-900', 191, 'Question 191', '[]'::jsonb, ARRAY[]::text[], 'Các đốm màu trang Azure hỗ trợ các hoạt động đọc và ghi ngẫu nhiên và được tối ưu hóa cho các cập nhật thường xuyên ở các mức chênh lệch tùy ý, chẳng hạn như đĩa cứng ảo.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-192', 'dp-900', 192, 'Which activity is most typical of transactional workloads?', '[{"key":"A","text":"recording small units of work events in real time"},{"key":"B","text":"aggregating massive amounts of data"},{"key":"C","text":"producing complex reports"},{"key":"D","text":"performing self-service data exploration"}]'::jsonb, ARRAY['A']::text[], 'Khối lượng công việc giao dịch ghi lại và xử lý các sự kiện công việc nhỏ, riêng lẻ trong thời gian thực. Họ ưu tiên xử lý nhanh chóng, đáng tin cậy các hoạt động riêng biệt thay vì tổng hợp lớn, báo cáo phức tạp hoặc phân tích thăm dò.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-193', 'dp-900', 193, 'You must store data in Azure Blob storage for seven years to satisfy your company''s compliance requirements. Data retrieval time is not important, and the solution must minimize storage costs.  
  
Which storage tier should you use?', '[{"key":"A","text":"Archive"},{"key":"B","text":"Hot"},{"key":"C","text":"Cool"}]'::jsonb, ARRAY['A']::text[], 'Archive tier được thiết kế cho dữ liệu dài hạn, hiếm khi được truy cập với độ trễ truy xuất linh hoạt. Nó có chi phí lưu trữ thấp nhất trong các tầng truy cập Azure Blob; độ trễ truy xuất cao hơn có thể chấp nhận được khi thời gian truy xuất không quan trọng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-194', 'dp-900', 194, 'Question 194', '[]'::jsonb, ARRAY[]::text[], 'Quá trình xử lý luồng đánh giá dữ liệu đến liên tục trong thời gian gần thực, giúp dữ liệu này phù hợp với các phân tích phức tạp yêu cầu độ trễ ngắn.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-195', 'dp-900', 195, 'You need to create an Azure resource that stores data in Azure Table storage.  
  
Which command should you run?', '[{"key":"A","text":"az storage share create"},{"key":"B","text":"az storage account create"},{"key":"C","text":"az cosmosdb create"},{"key":"D","text":"az storage container create"}]'::jsonb, ARRAY['B']::text[], 'Tài khoản Azure Storage cung cấp không gian tên và điểm cuối dịch vụ cho các đối tượng dữ liệu Azure Storage, bao gồm cả bảng. Lệnh Azure CLI `az storage account create` tạo tài khoản đó. [Create an Azure storage account](https://learn.microsoft.com/en-us/azure/storage/common/storage-account-create)', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-196', 'dp-900', 196, 'Question 196', '[]'::jsonb, ARRAY[]::text[], 'Hệ thống phân cấp thuộc tính sắp xếp các thuộc tính thứ nguyên thành các cấp theo thứ tự, cho phép người dùng đi sâu vào các giá trị chi tiết hơn hoặc đi sâu vào các giá trị tổng hợp trong Power BI.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-197', 'dp-900', 197, 'Question 197', '[]'::jsonb, ARRAY[]::text[], 'Azure SQL Edge là một công cụ dữ liệu SQL được tối ưu hóa cho việc triển khai biên IoT và xử lý cục bộ gần các thiết bị.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-198', 'dp-900', 198, 'Question 198', '[]'::jsonb, ARRAY[]::text[], 'Azure Databricks là dịch vụ Azure dựa trên nền tảng phân tích Apache Spark. Nó là một phần của nền tảng Databricks, được cung cấp trên nhiều nhà cung cấp đám mây.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-199', 'dp-900', 199, 'What distinguishes structured data from semi-structured data?', '[{"key":"A","text":"Structured data has a fixed schema and semi-structured data has a flexible schema."},{"key":"B","text":"Only Structured data supports entities."},{"key":"C","text":"Structured data has a flexible schema and semi-structured data has a fixed schema."},{"key":"D","text":"Only Structured data supports attributes."}]'::jsonb, ARRAY['A']::text[], 'Dữ liệu có cấu trúc tuân theo một lược đồ cố định, được xác định trước. Dữ liệu bán cấu trúc giữ lại một số tổ chức nhưng cho phép một lược đồ linh hoạt.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-200', 'dp-900', 200, 'For each of the following statements, select **Yes** if the statement is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"Azure Table storage within a single Azure Storage account supports multiple concurrent reads in different Azure regions.","correctAnswer":"Yes"},{"id":"2","text":"Azure Table storage within a single Azure Storage account supports multiple concurrent writes in different Azure regions.","correctAnswer":"No"},{"id":"3","text":"An Azure Cosmos DB account that uses the Table API supports multiple concurrent reads in different Azure regions.","correctAnswer":"Yes"},{"id":"4","text":"An Azure Cosmos DB account that uses the Table API supports multiple concurrent writes in different Azure regions.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:Yes', '4:Yes']::text[], 'Với quyền truy cập đọc geo-redundant storage (RA-GRS), một tài khoản Azure Storage duy nhất sẽ sao chép dữ liệu lưu trữ Bảng sang một khu vực phụ nơi có thể đọc được, do đó hỗ trợ nhiều lần đọc đồng thời trên các khu vực (statement 1 Yes). Tuy nhiên, Azure Table storage chỉ chấp nhận ghi ở vùng chính; có no ghi nhiều vùng, vì vậy statement 2 là No. Azure Cosmos DB cho Bảng cung cấp khả năng phân phối toàn cầu theo hình thức chìa khóa trao tay với nhiều vùng có thể đọc được và ghi nhiều vùng chính (đa vùng), vì vậy cả hai câu lệnh 3 và 4 đều là Yes.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-201', 'dp-900', 201, 'Question 201', '[]'::jsonb, ARRAY[]::text[], 'Trong mô hình phân tích đa chiều, các kích thước tạo thành các trục được sử dụng để nhóm dữ liệu. Giao điểm của chúng là một ô chứa thước đo ở hạt chiều đó, thường là thước đo tổng hợp chẳng hạn như tổng doanh số hoặc số lượng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-202', 'dp-900', 202, 'You have data stored in the following format.  
  
![Question Image](https://cdn.examcademy.com/images/questions/1783769018972-axhs2uv9.png)  
  
Which format is being used?', '[{"key":"A","text":"YAML"},{"key":"B","text":"CSV"},{"key":"C","text":"JSON"},{"key":"D","text":"HTML"}]'::jsonb, ARRAY['B']::text[], 'CSV lưu trữ dữ liệu dạng bảng dưới dạng bản ghi trên các dòng riêng biệt, với các giá trị trong mỗi bản ghi được phân tách bằng dấu phẩy.', 'General', ARRAY['DP-900', 'General']::text[], 'https://cdn.examcademy.com/images/questions/1783769018972-axhs2uv9.png', 'published'),
  ('dp900-203', 'dp-900', 203, 'Match the database-normalization terms with the correct descriptions.  
  
Each term may be used once, multiple times, or not at all.', '{"statements":[{"id":"slot1","text":"Get separated into individual columns","correctAnswer":"A"},{"id":"slot2","text":"Get separated into individual tables","correctAnswer":"B"},{"id":"slot3","text":"Link two related entities","correctAnswer":"C"}],"choices":[{"key":"A","text":"Attributes"},{"key":"B","text":"Entities"},{"key":"C","text":"Foreign keys"},{"key":"D","text":"Primary keys"},{"key":"E","text":"Schemas"}]}'::jsonb, ARRAY['slot1=A', 'slot2=B', 'slot3=C']::text[], 'Thuộc tính là các trường của thực thể và được biểu diễn dưới dạng cột trong bảng. Các thực thể được mô hình hóa thành các bảng riêng biệt. Khóa ngoại tham chiếu khóa của bảng khác, thiết lập mối quan hệ giữa hai thực thể.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-204', 'dp-900', 204, 'Question 204', '[]'::jsonb, ARRAY[]::text[], 'Azure Cosmos DB là dịch vụ cơ sở dữ liệu phân tán toàn cầu hỗ trợ ghi nhiều vùng, lập chỉ mục tự động và phân vùng theo chiều ngang, cho phép hiệu suất đọc và ghi có độ trễ thấp trên quy mô lớn.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-205', 'dp-900', 205, 'A bank operates a system that manages financial transactions.  
  
When money is transferred between accounts, the system must never retrieve a value for the source account that shows the balance before the transfer and a value for the destination account that shows the balance after the transfer.  
  
Which ACID semantic does this illustrate?', '[{"key":"A","text":"atomicity"},{"key":"B","text":"durability"},{"key":"C","text":"consistency"},{"key":"D","text":"isolation"}]'::jsonb, ARRAY['D']::text[], 'Sự cô lập ngăn cản các hoạt động quan sát tác động một phần của giao dịch. Khoản ghi nợ và tín dụng của giao dịch chuyển khoản không được hiển thị ở trạng thái hỗn hợp trong đó một tài khoản phản ánh số dư trước khi chuyển khoản trong khi tài khoản kia phản ánh số dư sau giao dịch đó.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-206', 'dp-900', 206, 'You have a dedicated SQL pool in Azure Synapse Analytics that is actively used only for eight hours each night.  
  
You need to minimize the dedicated SQL pool''s cost as much as possible during idle periods. The solution must ensure the data remains intact.  
  
What should you do with the dedicated SQL pool?', '[{"key":"A","text":"Scale down the data warehouse units (DWUs)."},{"key":"B","text":"Pause the pool."},{"key":"C","text":"Create a user-defined restore point."},{"key":"D","text":"Delete the pool"}]'::jsonb, ARRAY['B']::text[], 'Việc tạm dừng nhóm SQL chuyên dụng sẽ dừng và giải phóng tài nguyên điện toán, do đó chi phí tính toán DWU bằng 0 khi nhóm này bị tạm dừng. Dung lượng lưu trữ vẫn được tính phí riêng nhưng dữ liệu được lưu trữ không bị ảnh hưởng và vẫn nguyên vẹn cho đến khi nhóm được tiếp tục hoạt động.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-207', 'dp-900', 207, 'Question 207', '[]'::jsonb, ARRAY[]::text[], 'Nhà phân tích dữ liệu kiểm tra dữ liệu để tìm các mẫu và truyền đạt các phát hiện thông qua các báo cáo và hình ảnh trực quan. Kỹ sư dữ liệu tập trung vào cơ sở hạ tầng dữ liệu và quản trị viên cơ sở dữ liệu duy trì hoạt động của cơ sở dữ liệu.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-208', 'dp-900', 208, 'Question 208', '[]'::jsonb, ARRAY[]::text[], 'Azure Cosmos DB dành cho Apache Gremlin sử dụng vùng chứa để lưu trữ dữ liệu biểu đồ và vùng chứa được biểu diễn dưới dạng biểu đồ trong API Gremlin.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-209', 'dp-900', 209, 'Which three services provide support for Apache Spark? Each correct answer represents a complete solution.  
  
> **NOTE:** Each correct selection is worth one point.', '[{"key":"A","text":"Azure Data Explorer"},{"key":"B","text":"Azure Synapse Analytics"},{"key":"C","text":"Azure Databricks"},{"key":"D","text":"Azure Stream Analytics"},{"key":"E","text":"Azure HDInsight"}]'::jsonb, ARRAY['B', 'C', 'E']::text[], 'Azure Synapse Analytics hỗ trợ Apache Spark thông qua các nhóm Spark không có máy chủ. Azure Databricks chạy và tối ưu hóa khối lượng công việc Apache Spark và Azure HDInsight cung cấp các cụm Apache Spark được quản lý. Azure Data Explorer cung cấp một trình kết nối để trao đổi dữ liệu với các cụm Spark, thay vì lưu trữ chính Apache Spark.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-210', 'dp-900', 210, 'Match the visualization types with their corresponding descriptions.  
  
Each visualization type may be used once, multiple times, or not at all.', '{"statements":[{"id":"slot1","text":"A chart of colored, nested rectangles that displays individual data points represented by the size and color of a relative rectangle.","correctAnswer":"C"},{"id":"slot2","text":"A chart that displays the major contributors of a selected result or value.","correctAnswer":"A"},{"id":"slot3","text":"A chart that shows the relationship between two numerical values.","correctAnswer":"B"}],"choices":[{"key":"A","text":"Key influencer"},{"key":"B","text":"Scatter"},{"key":"C","text":"Treemap"}]}'::jsonb, ARRAY['slot1=C', 'slot2=A', 'slot3=B']::text[], 'Sơ đồ cây hiển thị các giá trị phân cấp hoặc tương đối dưới dạng hình chữ nhật lồng nhau, với kích thước hình chữ nhật và giá trị mã hóa màu. Hình ảnh trực quan của Người có ảnh hưởng chính xác định các yếu tố thúc đẩy chỉ số hoặc kết quả đã chọn. Biểu đồ phân tán vẽ hai thước đo bằng số để thể hiện mối quan hệ của chúng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-211', 'dp-900', 211, 'For each of the following statements, select Yes if the statement is true. Otherwise, select No.', '{"statements":[{"id":"1","text":"Stream processing can process all the data in a dataset at once.","correctAnswer":"No"},{"id":"2","text":"Batch processing occurs immediately, with latency in the order of seconds or milliseconds.","correctAnswer":"No"},{"id":"3","text":"Stream processing is used for simple response functions, aggregates, or calculations, such as rolling averages.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:No', '3:Yes']::text[], 'Xử lý hàng loạt hoạt động trên tập dữ liệu tích lũy hoàn chỉnh, trong khi xử lý luồng xử lý các bản ghi liên tục khi chúng đến. Xử lý luồng được thiết kế để mang lại kết quả có độ trễ thấp và hỗ trợ tính toán tổng hợp và cuộn theo cửa sổ; xử lý hàng loạt không diễn ra ngay lập tức ở độ trễ vài giây hoặc mili giây.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-212', 'dp-900', 212, 'Match the analytics types that can answer the business questions. Each analytics type may be used once, more than once, or not at all.', '{"statements":[{"id":"slot1","text":"Why did sales increase last month?","correctAnswer":"B"},{"id":"slot2","text":"Provide specific guidance on how to allocate current budget to buy different inventory items.","correctAnswer":"E"},{"id":"slot3","text":"Detect images of the company’s logo included in PDF documents","correctAnswer":"A"}],"choices":[{"key":"A","text":"Cognitive"},{"key":"B","text":"Diagnostic"},{"key":"C","text":"Descriptive"},{"key":"D","text":"Predictive"},{"key":"E","text":"Prescriptive"}]}'::jsonb, ARRAY['slot1=B', 'slot2=E', 'slot3=A']::text[], 'Phân tích chẩn đoán giải thích lý do xảy ra kết quả trong quá khứ. Phân tích theo quy định đề xuất một hành động, chẳng hạn như phân bổ ngân sách. Phân tích nhận thức có thể nhận dạng và giải thích nội dung hình ảnh phi cấu trúc, bao gồm hình ảnh logo được nhúng trong tài liệu PDF.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-213', 'dp-900', 213, 'Select the option that correctly finishes the sentence.', '[]'::jsonb, ARRAY[]::text[], 'Power BI Desktop là ứng dụng soạn thảo chính để kết nối với dữ liệu, chuyển đổi và lập mô hình dữ liệu cũng như tạo báo cáo. Sau đó, những nội dung báo cáo đó có thể được xuất bản lên dịch vụ Power BI và được xem qua ứng dụng di động.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-214', 'dp-900', 214, 'Match the datastore services with their corresponding descriptions.  
  
Each service can be used once, more than once, or not at all.', '{"statements":[{"id":"slot1","text":"Enables the use of SQL queries against data stored in JSON documents","correctAnswer":"B"},{"id":"slot2","text":"Enables users to access data by using the Server Message Block (SMB) version 3 protocol","correctAnswer":"C"}],"choices":[{"key":"A","text":"Azure Blob storage"},{"key":"B","text":"Azure Cosmos DB"},{"key":"C","text":"Azure Files"},{"key":"D","text":"Azure Table storage"}]}'::jsonb, ARRAY['slot1=B', 'slot2=C']::text[], 'Azure Cosmos DB lưu trữ các mục dưới dạng JSON và cung cấp ngôn ngữ truy vấn SQL để truy vấn dữ liệu đó. Azure Files cung cấp tính năng chia sẻ tệp qua SMB và hỗ trợ các phiên bản giao thức SMB 3.x.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-215', 'dp-900', 215, 'A company needs to deploy a relational database in Azure while minimizing ongoing maintenance.  
  
Which Azure service should it use?', '[{"key":"A","text":"Azure SQL Database"},{"key":"B","text":"Azure Cosmos DB"},{"key":"C","text":"Azure Databricks"},{"key":"D","text":"SQL Server on Azure Virtual Machines"}]'::jsonb, ARRAY['A']::text[], 'Azure SQL Database là nền tảng cơ sở dữ liệu quan hệ được quản lý hoàn toàn (PaaS). Microsoft quản lý các hoạt động thường lệ bao gồm vá lỗi, nâng cấp, sao lưu và giám sát, giúp giảm thiểu việc bảo trì liên tục.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-216', 'dp-900', 216, 'Question 216', '[]'::jsonb, ARRAY[]::text[], 'Khóa chính và khóa ngoài xác định mối quan hệ giữa các bảng quan hệ và thực thi tính toàn vẹn tham chiếu.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-217', 'dp-900', 217, 'For each statement, select **Yes** when it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"In a relational database, the schema is defined before data is written to the table.","correctAnswer":"Yes"},{"id":"2","text":"Key/value data stores are highly optimized for complex queries that contain multiple joins.","correctAnswer":"No"},{"id":"3","text":"A relational database is commonly used to store and query structured data.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:Yes']::text[], 'Cơ sở dữ liệu quan hệ sử dụng lược đồ khi ghi, sắp xếp dữ liệu có cấu trúc trong bảng và hỗ trợ các truy vấn SQL phong phú bao gồm cả các phép nối. Các cửa hàng khóa/giá trị được tối ưu hóa để tra cứu điểm theo khóa thay vì các phép nối nhiều bảng phức tạp.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-218', 'dp-900', 218, 'Which transactional-workload property ensures that every transaction is handled as one unit, either completing entirely or failing entirely?', '[{"key":"A","text":"atomicity"},{"key":"B","text":"isolation"},{"key":"C","text":"durability"},{"key":"D","text":"consistency"}]'::jsonb, ARRAY['A']::text[], 'Tính nguyên tử đảm bảo một giao dịch là tất cả hoặc không có gì: các thay đổi của nó được thực hiện hoàn toàn hoặc tất cả chúng đều được khôi phục khi giao dịch thất bại.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-219', 'dp-900', 219, 'Question 219', '[]'::jsonb, ARRAY[]::text[], 'ETL biến đổi và xử lý dữ liệu được trích xuất trước khi tải nó đến đích. Nguồn và đích không cần chia sẻ lược đồ, đích không thực hiện chuyển đổi và đích có thể không quan hệ.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-220', 'dp-900', 220, 'What is one characteristic of batch processing?', '[{"key":"A","text":"The data ingested during batch processing must be processed as soon as the data is received."},{"key":"B","text":"Large datasets must be split into batches of less than 1 GB before the data can be processed."},{"key":"C","text":"There is a noticeable time delay between ingesting data and obtaining the data processing results."},{"key":"D","text":"Batch processing can only process data that is structured."}]'::jsonb, ARRAY['C']::text[], 'Quá trình xử lý hàng loạt sẽ tích lũy dữ liệu và xử lý dữ liệu đó theo các khoảng thời gian đã lên lịch hoặc theo nhóm, gây ra độ trễ đáng kể giữa quá trình nhập dữ liệu và kết quả đầu ra được xử lý.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-221', 'dp-900', 221, 'For each statement below, select **Yes** when it is true; otherwise, select **No**.', '{"statements":[{"id":"1","text":"Azure Data Studio can be used to query an Azure SQL database from a device that runs macOS.","correctAnswer":"Yes"},{"id":"2","text":"Microsoft SQL Server Management Studio (SSMS) enables users to create and use SQL notebooks.","correctAnswer":"No"},{"id":"3","text":"Azure Data Studio can be used to restore a database.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:Yes']::text[], 'Azure Data Studio hỗ trợ macOS và có thể truy vấn Azure SQL Database. Sổ ghi chép SQL được tạo và chạy trong Azure Data Studio thay vì SQL Server Management Studio. Azure Data Studio bao gồm hỗ trợ sao lưu và khôi phục cho cơ sở dữ liệu SQL Server.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-222', 'dp-900', 222, 'Question 222', '[]'::jsonb, ARRAY[]::text[], 'XML biểu diễn dữ liệu bằng cách sử dụng các thẻ lồng nhau, tự mô tả. Điều này mang lại sự tổ chức linh hoạt mà không áp đặt lược đồ bảng quan hệ cố định, vì vậy XML là dữ liệu bán cấu trúc.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-223', 'dp-900', 223, 'Match the Azure SQL services with the corresponding use cases. Each service can be used once, more than once, or not at all.', '{"statements":[{"id":"slot1","text":"A serverless configuration","correctAnswer":"B"},{"id":"slot2","text":"A database that has the highest compatibility with on-premises Microsoft SQL Server","correctAnswer":"C"},{"id":"slot3","text":"A low-cost, low-maintenance database","correctAnswer":"A"}],"choices":[{"key":"A","text":"Azure SQL Database elastic pool"},{"key":"B","text":"Azure SQL Database single database"},{"key":"C","text":"Azure SQL Managed instance"}]}'::jsonb, ARRAY['slot1=B', 'slot2=C', 'slot3=A']::text[], 'Cơ sở dữ liệu đơn Azure SQL Database hỗ trợ tầng điện toán serverless. Azure SQL Managed Instance cung cấp khả năng tương thích gần như hoàn toàn với công cụ cơ sở dữ liệu SQL Server, khiến nó phù hợp nhất cho khả năng tương thích SQL Server tại chỗ. Nhóm đàn hồi chia sẻ tài nguyên điện toán giữa các cơ sở dữ liệu Azure SQL, giảm chi phí và quản trị cho cơ sở dữ liệu có nhu cầu khác nhau.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-224', 'dp-900', 224, 'A company must deploy a relational database in Azure. The solution needs to minimize ongoing maintenance.  
  
Which Azure service should be used?', '[{"key":"A","text":"Azure HDInsight"},{"key":"B","text":"Azure SQL Database"},{"key":"C","text":"Azure Cosmos DB"},{"key":"D","text":"SQL Server on Azure Virtual Machines"}]'::jsonb, ARRAY['B']::text[], 'Azure SQL Database là dịch vụ cơ sở dữ liệu PaaS quan hệ được quản lý hoàn toàn. Nó giảm tải công việc quản lý cơ sở dữ liệu thông thường, bao gồm nâng cấp, vá lỗi, sao lưu và giám sát, giúp giảm thiểu việc bảo trì liên tục.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-225', 'dp-900', 225, 'Question 225', '[]'::jsonb, ARRAY[]::text[], 'ELT tải dữ liệu thô vào kho lưu trữ dữ liệu đích trước khi chuyển đổi, do đó cửa hàng đó phải có khả năng thực hiện các chuyển đổi được yêu cầu.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-226', 'dp-900', 226, 'When an Azure SQL database is created, which account can always connect to that database?', '[{"key":"A","text":"the Azure Active Directory (Azure AD) account that created the database"},{"key":"B","text":"the server admin login account of the logical server"},{"key":"C","text":"the Azure Active Directory (Azure AD) administrator account"},{"key":"D","text":"the sa account"}]'::jsonb, ARRAY['B']::text[], 'Thông tin đăng nhập quản trị viên máy chủ của máy chủ logic được cung cấp đầy đủ quyền quản trị cho tất cả các cơ sở dữ liệu trên máy chủ đó, bao gồm cả cơ sở dữ liệu mới được tạo. Danh tính Azure AD của người tạo cơ sở dữ liệu không được tự động cấp quyền truy cập cơ sở dữ liệu; quản trị viên Azure AD là tùy chọn; và Azure SQL Database có tài khoản no `sa`.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-227', 'dp-900', 227, 'Question 227', '[]'::jsonb, ARRAY[]::text[], 'Các thủ tục được lưu trữ chứa các câu lệnh cơ sở dữ liệu có thể thực thi được và đóng gói logic kinh doanh hoặc lập trình có thể tái sử dụng. Bảng lưu trữ dữ liệu, dạng xem xác định tập hợp kết quả và lập chỉ mục tối ưu hóa việc truy cập dữ liệu.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-228', 'dp-900', 228, 'Which database transaction property ensures that each individual transaction runs only once and either completes entirely or is rolled back?', '[{"key":"A","text":"atomicity"},{"key":"B","text":"durability"},{"key":"C","text":"isolation"},{"key":"D","text":"consistency"}]'::jsonb, ARRAY['A']::text[], 'Atomicity xử lý một giao dịch như một đơn vị công việc được làm tất cả hoặc không có gì: mọi thao tác đều thành công và cam kết, hoặc một thất bại khiến toàn bộ giao dịch bị quay trở lại.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-229', 'dp-900', 229, 'You need to store semi-structured event-log data as the logs are generated.  
  
What should you use?', '[{"key":"A","text":"Azure Table storage"},{"key":"B","text":"Azure Queue storage"},{"key":"C","text":"Azure Files"}]'::jsonb, ARRAY['A']::text[], 'Azure Table storage cung cấp kho lưu trữ khóa/thuộc tính NoSQL không có sơ đồ cho dữ liệu không quan hệ, do đó, nó có thể lưu trữ các bản ghi nhật ký bán cấu trúc có thuộc tính có thể thay đổi theo thời gian. Lưu trữ hàng đợi dành cho nhắn tin không đồng bộ, trong khi Azure Files là dịch vụ chia sẻ tệp.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-230', 'dp-900', 230, 'Question 230', '[]'::jsonb, ARRAY[]::text[], 'Apache Parquet là một định dạng tệp hướng theo cột được tổ chức thành các nhóm hàng và các khối cột. Avro, JSON và XML không phải là các định dạng lưu trữ theo cột.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-231', 'dp-900', 231, 'Which schema type is used for structured data in which each row represents a single data entity?', '[{"key":"A","text":"XML"},{"key":"B","text":"tabular"},{"key":"C","text":"blob"},{"key":"D","text":"JSON"}]'::jsonb, ARRAY['B']::text[], 'Lược đồ dạng bảng lưu trữ dữ liệu theo hàng và cột, trong đó mỗi hàng là một thực thể hoặc bản ghi riêng biệt và các cột xác định các thuộc tính của thực thể đó.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-232', 'dp-900', 232, 'Which statement is an example of Data Manipulation Language (DML)?', '[{"key":"A","text":"REVOKE"},{"key":"B","text":"DISABLE"},{"key":"C","text":"INSERT"},{"key":"D","text":"GRANT"}]'::jsonb, ARRAY['C']::text[], 'INSERT là một câu lệnh Ngôn ngữ thao tác dữ liệu vì nó thêm các hàng dữ liệu mới vào bảng cơ sở dữ liệu.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-233', 'dp-900', 233, 'Match the Azure Data Lake Storage Gen2 terms with the appropriate levels in the hierarchy.  
  
Each term may be used once, more than once, or not at all.', '{"statements":[{"id":"slot1","text":"Slot 1:","correctAnswer":"A"},{"id":"slot2","text":"Slot 2:","correctAnswer":"C"}],"choices":[{"key":"A","text":"Azure Storage account"},{"key":"B","text":"File share"},{"key":"C","text":"Container"}]}'::jsonb, ARRAY['slot1=A', 'slot2=C']::text[], 'Azure Data Lake Storage Gen2 được triển khai thông qua tài khoản Azure Storage với không gian tên phân cấp. Tài khoản lưu trữ chứa các thùng chứa và một thùng chứa có thể chứa các thư mục (thư mục) và tệp. Chia sẻ tệp Azure Files không phải là cấp độ phân cấp ADLS Gen2 tương đương.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-234', 'dp-900', 234, 'Question 234', '[]'::jsonb, ARRAY[]::text[], 'Azure Synapse Analytics hợp nhất kho dữ liệu SQL doanh nghiệp, phân tích hồ dữ liệu và xử lý dữ liệu lớn Apache Spark.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-235', 'dp-900', 235, 'Question 235', '[]'::jsonb, ARRAY[]::text[], 'Danh sách kiểm soát truy cập Azure Data Lake Storage cung cấp các quyền giống POSIX cho từng tệp và thư mục riêng lẻ. Ủy quyền ACL được bật khi tài khoản lưu trữ đã bật không gian tên phân cấp.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-236', 'dp-900', 236, 'Question 236', '[]'::jsonb, ARRAY[]::text[], 'Việc kích hoạt không gian tên phân cấp sẽ kích hoạt các khả năng của Azure Data Lake Storage Gen2, bao gồm cấu trúc thư mục phân cấp, danh sách kiểm soát truy cập POSIX cấp thư mục và các hoạt động thư mục nguyên tử.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-237', 'dp-900', 237, 'Question 237', '[]'::jsonb, ARRAY[]::text[], 'Trong lược đồ hình sao, các thứ nguyên cung cấp các thuộc tính được sử dụng để lọc, nhóm, tổng hợp và cắt lát các thước đo thực tế.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-238', 'dp-900', 238, 'Question 238', '[]'::jsonb, ARRAY[]::text[], 'Các hoạt động luồng điều khiển Azure Data Factory điều phối việc thực hiện quy trình thông qua các phần phụ thuộc của hoạt động và có thể chuyển đầu ra của hoạt động sang các hoạt động tiếp theo. Tập dữ liệu xác định dữ liệu, dịch vụ được liên kết xác định kết nối và integration runtime cung cấp khả năng tính toán hoặc kết nối thực thi.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-239', 'dp-900', 239, 'For each statement, select **Yes** when it is true; otherwise, select **No**.', '{"statements":[{"id":"1","text":"Copying data to Azure Data Lake Storage from another Azure region results in extra cost.","correctAnswer":"Yes"},{"id":"2","text":"You can use blob, table, and file storage in the same Azure Storage account.","correctAnswer":"Yes"},{"id":"3","text":"You implement Azure Data Lake Storage by creating an Azure Storage account.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:Yes', '3:Yes']::text[], 'Sao chép dữ liệu lưu trữ trên các vùng Azure sẽ phát sinh phí đầu ra mạng. Tài khoản lưu trữ v2 đa năng hỗ trợ các dịch vụ Blob, Table và Azure Files. Azure Data Lake Storage Gen2 được xây dựng trên Azure Storage và được kích hoạt bằng cách tạo tài khoản lưu trữ có hỗ trợ không gian tên phân cấp.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-240', 'dp-900', 240, 'Match each cloud service model to its appropriate Azure relational database service.  
  
Each model may be used once, more than once, or not at all.', '{"statements":[{"id":"azure_sql_database","text":"Azure SQL Database","correctAnswer":"B"},{"id":"azure_sql_managed_instance","text":"Azure SQL Managed Instance","correctAnswer":"B"},{"id":"sql_server_on_azure_virtual_machines","text":"SQL Server on Azure Virtual Machines","correctAnswer":"A"}],"choices":[{"key":"A","text":"Infrastructure as a service"},{"key":"B","text":"Platform as a service"},{"key":"C","text":"Software as a service"}]}'::jsonb, ARRAY['azure_sql_database=B', 'azure_sql_managed_instance=B', 'sql_server_on_azure_virtual_machines=A']::text[], 'Azure SQL Database và Azure SQL Managed Instance là Nền tảng do Microsoft quản lý dưới dạng dịch vụ cơ sở dữ liệu Dịch vụ, bao gồm bản vá được quản lý, bản sao lưu và cơ sở hạ tầng cơ bản. SQL Server trên Azure Virtual Machines là Cơ sở hạ tầng dưới dạng Dịch vụ vì khách hàng quản lý phiên bản SQL Server và hệ điều hành trên VM.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-241', 'dp-900', 241, 'Your company must ensure that an Azure virtual machine can connect to Azure SQL databases without exposing those databases to the internet.  
  
What should you use?', '[{"key":"A","text":"Azure Application Gateway"},{"key":"B","text":"Azure Traffic Manager"},{"key":"C","text":"Azure DNS"},{"key":"D","text":"Azure Private Link"}]'::jsonb, ARRAY['D']::text[], 'Azure Private Link sử dụng private endpoint với địa chỉ IP riêng trong mạng ảo, cho phép Azure virtual machines truy cập Azure SQL Database một cách riêng tư qua đường trục của Microsoft thay vì qua internet công cộng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-242', 'dp-900', 242, 'For each statement below, select **Yes** when it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"Azure Table storage supports multiple read replicas.","correctAnswer":"No"},{"id":"2","text":"Azure Table storage supports multiple write regions.","correctAnswer":"No"},{"id":"3","text":"The Azure Cosmos DB Table API supports multiple read replicas.","correctAnswer":"Yes"},{"id":"4","text":"The Azure Cosmos DB Table API supports multiple write regions.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:No', '3:Yes', '4:Yes']::text[], 'Azure Table storage hoạt động chủ động-thụ động giữa các khu vực: RA-GRS/RA-GZRS cung cấp quyền truy cập đọc vào một điểm cuối phụ duy nhất, trong khi hoạt động ghi vẫn ở khu vực chính. Azure Cosmos DB dành cho Bảng hỗ trợ các vùng đọc được phân phối trên toàn cầu và hỗ trợ ghi nhiều vùng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-243', 'dp-900', 243, 'You need to use Transact-SQL to query files in Azure Data Lake Storage Gen 2 from an Azure Synapse Analytics data warehouse.  
  
What should you use to query the files?', '[{"key":"A","text":"Azure Functions"},{"key":"B","text":"Microsoft SQL Server Integration Services (SSIS)"},{"key":"C","text":"PolyBase"},{"key":"D","text":"Azure Data Factory"}]'::jsonb, ARRAY['C']::text[], 'PolyBase cho phép Azure Synapse Analytics truy cập dữ liệu ngoài được lưu trữ trong Azure Data Lake Storage thông qua Transact-SQL, sử dụng các đối tượng nguồn dữ liệu ngoài và bảng ngoài.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-244', 'dp-900', 244, 'Question 244', '[]'::jsonb, ARRAY[]::text[], 'Các mô hình OLAP tối ưu hóa các truy vấn phân tích bằng cách lưu trữ hoặc sử dụng dữ liệu tóm tắt được tổng hợp trước, giúp tăng tốc độ phân tích và báo cáo đa chiều.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-245', 'dp-900', 245, 'For each statement below, select **Yes** when it is true; otherwise, select **No**.', '{"statements":[{"id":"1","text":"Azure SQL Database includes a managed backup service.","correctAnswer":"Yes"},{"id":"2","text":"Azure SQL Database has built-in high availability.","correctAnswer":"Yes"},{"id":"3","text":"Azure SQL Database can use Azure Defender.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:Yes', '3:Yes']::text[], 'Azure SQL Database bao gồm các bản sao lưu được quản lý, tự động. Kiến trúc PaaS của nó cung cấp tính khả dụng tích hợp thông qua sao chép, phục hồi tự động và hành vi chuyển đổi dự phòng được quản lý bởi nền tảng. Bộ bảo vệ Microsoft dành cho Cơ sở dữ liệu Azure SQL bảo vệ các cơ sở dữ liệu đơn lẻ và vùng linh hoạt Azure SQL được hỗ trợ.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-246', 'dp-900', 246, 'Your company intends to load data from a customer relationship management (CRM) system into a data warehouse by using an extract, load, and transform (ELT) process.  
  
Where does data processing take place during each ELT stage? Each location may be used once, more than once, or not at all.', '{"statements":[{"id":"extract","text":"Extract:","correctAnswer":"B"},{"id":"load","text":"Load:","correctAnswer":"C"},{"id":"transform","text":"Transform:","correctAnswer":"C"}],"choices":[{"key":"A","text":"A standalone data analysis tool"},{"key":"B","text":"The CRM system"},{"key":"C","text":"The data warehouse"}]}'::jsonb, ARRAY['extract=B', 'load=C', 'transform=C']::text[], 'ELT trích xuất dữ liệu từ hệ thống CRM nguồn, tải dữ liệu đó vào dữ liệu đích warehouse, sau đó chuyển đổi dữ liệu đó bằng khả năng xử lý của kho dữ liệu đích. Không cần có công cụ phân tích dữ liệu riêng cho các giai đoạn ELT này.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-247', 'dp-900', 247, 'You manage an application that stores data in a shared folder on a Windows Server.  
  
You need to migrate the shared folder to Azure Storage.  
  
Which type of Azure Storage should you use?', '[{"key":"A","text":"queue"},{"key":"B","text":"blob"},{"key":"C","text":"file"},{"key":"D","text":"table"}]'::jsonb, ARRAY['C']::text[], 'Azure Files cung cấp tính năng chia sẻ tệp được quản lý hoàn toàn mà Windows Server có thể truy cập thông qua giao thức SMB, biến nó thành loại Bộ lưu trữ Azure thích hợp để di chuyển thư mục dùng chung.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-248', 'dp-900', 248, 'Which setting can be configured only when creating an Azure Cosmos DB account?', '[{"key":"A","text":"geo-redundancy"},{"key":"B","text":"multi-region writes"},{"key":"C","text":"production or non-production account type"},{"key":"D","text":"API"}]'::jsonb, ARRAY['D']::text[], 'API tài khoản Azure Cosmos DB xác định loại tài khoản và mô hình dữ liệu (chẳng hạn như NoSQL, MongoDB, Cassandra, Gremlin hoặc Table). Loại tài khoản này chỉ có thể được đặt khi tài khoản cơ sở dữ liệu được tạo; nó không thể được thay đổi sau đó.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-249', 'dp-900', 249, 'For each statement below, select Yes when it is true. Otherwise, select No.', '{"statements":[{"id":"1","text":"You create Azure File Storage in a storage account.","correctAnswer":"Yes"},{"id":"2","text":"The Premium tier of Azure File Storage uses HDD-based hardware in a datacenter.","correctAnswer":"No"},{"id":"3","text":"The Standard tier of Azure File Storage uses SSDs.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:No']::text[], 'Azure Files được cung cấp thông qua tài khoản lưu trữ Azure. Azure Files cao cấp sử dụng ổ đĩa thể rắn (SSD), trong khi chia sẻ tệp Azure tiêu chuẩn được hỗ trợ bởi ổ đĩa cứng (HDD).', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-250', 'dp-900', 250, 'Question 250', '[]'::jsonb, ARRAY[]::text[], 'Mô hình OLAP trình bày dữ liệu warehouse tổng hợp trong một khối đa chiều. Số đo là các giá trị số được phân tích trong khối, trong khi các thứ nguyên cung cấp các danh mục được sử dụng để phân tích chúng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-251', 'dp-900', 251, 'A bank must ensure that, once an account-transfer transaction has completed, the updated account balances persist even if the database system hosting that transaction is temporarily unavailable.  
  
Which ACID semantic does this illustrate?', '[{"key":"A","text":"durability"},{"key":"B","text":"isolation"},{"key":"C","text":"atomicity"},{"key":"D","text":"consistency"}]'::jsonb, ARRAY['A']::text[], 'Độ bền đảm bảo rằng sau khi giao dịch được thực hiện, các thay đổi của nó sẽ được ghi lại vĩnh viễn và vẫn có sẵn ngay cả khi hệ thống cơ sở dữ liệu sau đó gặp lỗi hoặc ngừng hoạt động tạm thời.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-252', 'dp-900', 252, 'Question 252', '[]'::jsonb, ARRAY[]::text[], 'Các cửa hàng khóa/giá trị liên kết mỗi giá trị với một khóa duy nhất và chủ yếu hỗ trợ các thao tác truy vấn, chèn và xóa đơn giản. Điểm mạnh của họ là tra cứu theo key nhanh, độ trễ thấp; các phép nối quan hệ và thực thi ràng buộc là các khả năng của cơ sở dữ liệu quan hệ.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-253', 'dp-900', 253, 'For each following statement, select **Yes** if it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"Normalization involves eliminating relationships between database tables.","correctAnswer":"No"},{"id":"2","text":"Normalizing a database reduces data redundancy.","correctAnswer":"Yes"},{"id":"3","text":"Normalization improves data integrity.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:Yes', '3:Yes']::text[], 'Bình thường hóa không loại bỏ các mối quan hệ; nó cấu trúc chúng bằng cách sử dụng các khóa và các bảng liên quan. Nó làm giảm dữ liệu dư thừa và giúp duy trì dữ liệu nhất quán, chính xác, cải thiện tính toàn vẹn.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-254', 'dp-900', 254, 'Question 254', '[]'::jsonb, ARRAY[]::text[], 'Các khả năng của Azure Data Lake Storage được mở khóa bằng cách bật cài đặt không gian tên phân cấp trên tài khoản Azure Storage. Nó cung cấp thư mục phân cấp và ngữ nghĩa hệ thống tệp mà Data Lake Storage yêu cầu.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-255', 'dp-900', 255, 'Your company is planning a data store that will hold student data. The data has the following format.  
  
![Question Image](https://cdn.examcademy.com/images/questions/1783766052989-k7w1rn97.png)  
  
Which data-store type should you use?', '[{"key":"A","text":"graph"},{"key":"B","text":"key/value"},{"key":"C","text":"object"},{"key":"D","text":"columnar"}]'::jsonb, ARRAY['B']::text[], 'Kho lưu trữ dữ liệu khóa/giá trị sử dụng mã số sinh viên làm khóa duy nhất và lưu trữ thông tin sinh viên liên quan làm giá trị. Nó hỗ trợ các bản ghi với các nhóm thuộc tính khác nhau, chẳng hạn như tên ưa thích, địa chỉ email, ID MCP hoặc số điện thoại.', 'General', ARRAY['DP-900', 'General']::text[], 'https://cdn.examcademy.com/images/questions/1783766052989-k7w1rn97.png', 'published'),
  ('dp900-256', 'dp-900', 256, 'Which feature characterizes a non-relational database?', '[{"key":"A","text":"full support for Transact-SQL"},{"key":"B","text":"a fixed schema"},{"key":"C","text":"self-describing entities"}]'::jsonb, ARRAY['C']::text[], 'Cơ sở dữ liệu phi quan hệ thường sử dụng các thực thể linh hoạt, tự mô tả, có thể bao gồm các thuộc tính riêng của chúng và không yêu cầu lược đồ cố định, cứng nhắc.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-257', 'dp-900', 257, 'Which Azure service offers the greatest compatibility for databases migrated from Microsoft SQL Server 2019 Enterprise edition?', '[{"key":"A","text":"Azure SQL Database"},{"key":"B","text":"Azure Database for MySQL"},{"key":"C","text":"Azure SQL Managed Instance"},{"key":"D","text":"an Azure SQL Database elastic pool"}]'::jsonb, ARRAY['C']::text[], 'Azure SQL Managed Instance cung cấp tính năng tương đương gần nhất và khả năng tương thích cấp phiên bản với SQL Server, cho phép các phiên bản và cơ sở dữ liệu SQL Server hiện có di chuyển với các vấn đề tương thích ở mức tối thiểu sang no. Azure SQL Database và vùng đàn hồi là các dịch vụ trong phạm vi cơ sở dữ liệu với bề mặt tính năng SQL Server hẹp hơn; Cơ sở dữ liệu Azure cho MySQL không phải là mục tiêu SQL Server.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-258', 'dp-900', 258, 'You have a transactional application that stores data in an Azure SQL Managed Instance.  
  
When should you deploy a read-only database replica?', '[{"key":"A","text":"You need to generate reports without affecting the transactional workload."},{"key":"B","text":"You need to audit the transactional application."},{"key":"C","text":"You need to implement high availability in the event of a regional outage."},{"key":"D","text":"You need to improve the recovery point objective (RPO)."}]'::jsonb, ARRAY['A']::text[], 'Bản sao chỉ đọc có thể giảm tải báo cáo và các truy vấn chỉ đọc khác khỏi khối lượng công việc đọc-ghi chính, duy trì hiệu suất giao dịch. Mở rộng quy mô đọc Azure SQL Managed Instance được thiết kế để tách biệt khối lượng công việc chỉ đọc như báo cáo và phân tích khỏi khối lượng công việc ghi.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-259', 'dp-900', 259, 'Match each data storage option with the appropriate type of data.  
  
Each data storage option may be used once, more than once, or not at all.', '{"statements":[{"id":"audio_files","text":"Audio files","correctAnswer":"A"},{"id":"json_documents","text":"JSON documents","correctAnswer":"B"},{"id":"tabular_datasets","text":"Tabular datasets","correctAnswer":"D"}],"choices":[{"key":"A","text":"Azure Blob Storage"},{"key":"B","text":"Azure Cosmos DB for NoSQL"},{"key":"C","text":"Azure Data Factory"},{"key":"D","text":"Azure SQL Database"}]}'::jsonb, ARRAY['audio_files=A', 'json_documents=B', 'tabular_datasets=D']::text[], 'Azure Blob Storage lưu trữ dữ liệu đối tượng phi cấu trúc, bao gồm các tệp âm thanh. Azure Cosmos DB dành cho NoSQL lưu trữ các mục JSON linh hoạt theo lược đồ. Azure SQL Database là một dịch vụ quan hệ được thiết kế cho dữ liệu dạng bảng có cấu trúc. Azure Data Factory điều phối và chuyển đổi dữ liệu nhưng không phải là dịch vụ lưu trữ phù hợp.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-260', 'dp-900', 260, 'Question 260', '[]'::jsonb, ARRAY[]::text[], 'Tính năng chuyển giọng nói thành văn bản tạo chú thích văn bản bằng cách nhận dạng và xử lý ngôn ngữ nói, đây là khả năng nhận thức của AI. Phân tích mô tả tóm tắt dữ liệu trong quá khứ, phân tích dự đoán dự đoán kết quả và phân tích mô tả đề xuất hành động.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-261', 'dp-900', 261, 'Question 261', '[]'::jsonb, ARRAY[]::text[], 'Chỉ mục được nhóm xác định thứ tự vật lý của dữ liệu bảng dựa trên các giá trị khóa của nó. Các lựa chọn khác không sắp xếp dữ liệu bảng theo khóa.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-262', 'dp-900', 262, 'What should be used to automatically delete blobs from Azure Blob Storage?', '[{"key":"A","text":"archive storage"},{"key":"B","text":"the change feed"},{"key":"C","text":"soft delete"},{"key":"D","text":"a lifecycle management policy"}]'::jsonb, ARRAY['D']::text[], 'Chính sách quản lý vòng đời Azure Blob Storage sử dụng các điều kiện dựa trên quy tắc để tự động xóa các đốm màu. Nó có thể áp dụng các hành động xóa theo độ tuổi blob, thời gian sửa đổi, cấp truy cập và các tiêu chí được hỗ trợ khác.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-263', 'dp-900', 263, 'Question 263', '[]'::jsonb, ARRAY[]::text[], 'Chế độ xem là một bảng ảo được xác định bởi một truy vấn; các hàng và cột của nó được lấy từ kết quả truy vấn cơ bản.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-264', 'dp-900', 264, 'Which storage solution provides access control lists (ACLs) at the file and folder level?', '[{"key":"A","text":"Azure Data Lake Storage"},{"key":"B","text":"Azure Queue storage"},{"key":"C","text":"Azure Blob storage"},{"key":"D","text":"Azure Cosmos DB"}]'::jsonb, ARRAY['A']::text[], 'Azure Data Lake Storage hỗ trợ các ACL giống POSIX cho các quyền chi tiết trên các tệp và thư mục riêng lẻ, bao gồm kiểm soát truy cập cấp thư mục.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-265', 'dp-900', 265, 'The data is stored in the following format.  
  
![Question Image](https://cdn.examcademy.com/images/questions/1783769412647-i9rigtb8.png)  
  
Which format is being used?', '[{"key":"A","text":"JSON"},{"key":"B","text":"YAML"},{"key":"C","text":"HTML"},{"key":"D","text":"XML"}]'::jsonb, ARRAY['D']::text[], 'XML thể hiện dữ liệu phân cấp với các phần tử lồng nhau, thẻ mở và đóng cũng như thuộc tính. `Person`, `FirstName`, `Hobby` và các phần tử được gắn thẻ khác, cùng với các thuộc tính như `Age` và `Type`, tuân theo cú pháp XML.', 'General', ARRAY['DP-900', 'General']::text[], 'https://cdn.examcademy.com/images/questions/1783769412647-i9rigtb8.png', 'published'),
  ('dp900-266', 'dp-900', 266, 'Match the Azure services with the appropriate locations in the architecture. Each service can be used once, multiple times, or not at all.', '{"statements":[{"id":"ingest","text":"Ingest","correctAnswer":"C"},{"id":"preprocess_model","text":"Preprocess & model","correctAnswer":"D"}],"choices":[{"key":"A","text":"Azure Cognitive Search"},{"key":"B","text":"Azure Data Catalog"},{"key":"C","text":"Azure Data Factory"},{"key":"D","text":"Azure Synapse Analytics"}]}'::jsonb, ARRAY['ingest=C', 'preprocess_model=D']::text[], 'Azure Data Factory nhập và điều phối chuyển động dữ liệu vào Azure Data Lake Storage. Azure Synapse Analytics hỗ trợ chuẩn bị, chuyển đổi và lập mô hình dữ liệu trên dữ liệu hồ trước khi được phân phát thông qua Dịch vụ phân tích Azure và Power BI.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-267', 'dp-900', 267, 'For each statement, select **Yes** when it is true; otherwise, select **No**.', '{"statements":[{"id":"1","text":"Azure Synapse Analytics scales storage and compute independently","correctAnswer":"Yes"},{"id":"2","text":"Azure Synapse Analytics can be paused to reduce compute costs","correctAnswer":"Yes"},{"id":"3","text":"An Azure Synapse Analytics data warehouse has a fixed storage capacity","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:Yes', '3:No']::text[], 'Nhóm SQL chuyên dụng tách biệt lưu trữ khỏi điện toán, cho phép mở rộng quy mô độc lập. Việc tạm dừng sẽ giải phóng tài nguyên điện toán và ngừng tính phí điện toán, trong khi dung lượng lưu trữ vẫn được giữ nguyên và được tính phí riêng. Do đó, dung lượng lưu trữ không phải là dung lượng warehouse cố định.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-268', 'dp-900', 268, 'In an analytical data model, which table type holds entities used to aggregate numeric values, with each entity represented by a row that has a unique key value?', '[{"key":"A","text":"bridge"},{"key":"B","text":"dimension"},{"key":"C","text":"fact"}]'::jsonb, ARRAY['B']::text[], 'Bảng thứ nguyên chứa các thực thể kinh doanh theo đó các thước đo số được phân loại, nhóm lại và tổng hợp. Mỗi thành viên thứ nguyên được lưu trữ dưới dạng một hàng với một khóa duy nhất tham chiếu đến các bảng thực tế.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-269', 'dp-900', 269, 'Which T-SQL statement should be used to tell a database management system to use an index rather than carry out a full table scan?', '[{"key":"A","text":"WHERE"},{"key":"B","text":"SELECT"},{"key":"C","text":"UNION"}]'::jsonb, ARRAY['A']::text[], 'Mệnh đề `WHERE` cung cấp một vị từ tìm kiếm. Khi vị từ đó phù hợp với cột được lập chỉ mục, SQL Server có thể sử dụng tìm kiếm chỉ mục để truy xuất các hàng đủ điều kiện thay vì quét tất cả các hàng. `SELECT` dự án kết quả và `UNION` kết hợp các tập hợp kết quả; không cung cấp vị từ lọc này. Lựa chọn chỉ mục vẫn là quyết định tối ưu hóa trừ khi sử dụng gợi ý bảng rõ ràng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-270', 'dp-900', 270, 'Which database transaction property guarantees that transaction changes are retained through unexpected operating system restarts?', '[{"key":"A","text":"consistency"},{"key":"B","text":"atomicity"},{"key":"C","text":"durability"},{"key":"D","text":"isolation"}]'::jsonb, ARRAY['C']::text[], 'Độ bền đảm bảo rằng các thay đổi giao dịch đã cam kết được lưu trữ liên tục và tồn tại trong các lỗi như khởi động lại hệ điều hành bất ngờ.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-271', 'dp-900', 271, 'GRANT, REVOKE, and DENY are examples of what type of SQL statement?', '[{"key":"A","text":"Data Definition language (DDL)"},{"key":"B","text":"Data Control Language (DCL)"},{"key":"C","text":"Data Manipulation Language (DML)"}]'::jsonb, ARRAY['B']::text[], 'Các quyền kiểm soát CẤP, THU HỒI và TỪ CHỐI cũng như các đặc quyền truy cập đối với các nguyên tắc cơ sở dữ liệu, đó là mục đích của Ngôn ngữ điều khiển dữ liệu (DCL).', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-272', 'dp-900', 272, 'A bank must ensure that a transaction that debits funds from a source account and credits the same funds to a destination account completes both actions. If either action fails to complete, the other action must also fail.  
  
Which ACID semantic does this illustrate?', '[{"key":"A","text":"consistency"},{"key":"B","text":"durability"},{"key":"C","text":"atomicity"},{"key":"D","text":"isolation"}]'::jsonb, ARRAY['C']::text[], 'Atomicity làm cho một giao dịch không thể phân chia được: tất cả các hoạt động của nó được thực hiện cùng nhau hoặc toàn bộ giao dịch được khôi phục. Do đó, việc chuyển tiền không thể chỉ để lại khoản ghi nợ hoặc chỉ khoản tín dụng được hoàn thành.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-273', 'dp-900', 273, 'SELECT, INSERT, and UPDATE are examples of what type of SQL statement?', '[{"key":"A","text":"Data Definition Language (DDL)"},{"key":"B","text":"Data Control Language (DCL)"},{"key":"C","text":"Data Manipulation Language (DML)"}]'::jsonb, ARRAY['C']::text[], 'Ngôn ngữ thao tác dữ liệu (DML) bao gồm các câu lệnh được sử dụng để truy xuất hoặc thay đổi dữ liệu trong các bảng cơ sở dữ liệu, bao gồm CHỌN, CHÈN và CẬP NHẬT.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-274', 'dp-900', 274, 'Question 274', '[]'::jsonb, ARRAY[]::text[], 'Azure Synapse Analytics chứa công cụ và trải nghiệm Tích hợp dữ liệu tương tự như Azure Data Factory, cho phép tạo và thực thi các đường dẫn ETL trong không gian làm việc Synapse.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-275', 'dp-900', 275, 'Which two Azure services can be used to provision Apache Spark clusters? Each correct answer provides a complete solution.  
  
**NOTE:** Each correct selection is worth one point.', '[{"key":"A","text":"Azure Time Series Insights"},{"key":"B","text":"Azure HDInsight"},{"key":"C","text":"Azure Databricks"},{"key":"D","text":"Azure Log Analytics"}]'::jsonb, ARRAY['B', 'C']::text[], 'Azure HDInsight hỗ trợ cung cấp loại cụm Apache Spark chuyên dụng. Azure Databricks sử dụng Apache Spark để cung cấp năng lượng cho các cụm điện toán của nó. Azure Time Series Insights và Azure Log Analytics là các dịch vụ giám sát và phân tích, không phải dịch vụ cung cấp cụm Apache Spark.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-276', 'dp-900', 276, 'Question 276', '[]'::jsonb, ARRAY[]::text[], 'Quản trị viên cơ sở dữ liệu quản lý quyền truy cập cơ sở dữ liệu, quyền và các biện pháp kiểm soát bảo mật khác để bảo vệ dữ liệu được lưu trữ trong cơ sở dữ liệu.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-277', 'dp-900', 277, 'Question 277', '[]'::jsonb, ARRAY[]::text[], 'Các hồ dữ liệu có thể mở rộng quy mô để lưu trữ và phân tích khối lượng lớn dữ liệu đa dạng, bao gồm dữ liệu có cấu trúc, bán cấu trúc và không cấu trúc.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-278', 'dp-900', 278, 'Question 278', '[]'::jsonb, ARRAY[]::text[], 'Chỉ mục được nhóm sắp xếp và lưu trữ các hàng dữ liệu của bảng theo thứ tự khóa chỉ mục được nhóm. Một bảng chỉ có thể có một chỉ mục được nhóm vì các hàng dữ liệu của nó chỉ có thể được lưu trữ theo một thứ tự vật lý.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-279', 'dp-900', 279, 'What type of database service is Azure Database for PostgreSQL?', '[{"key":"A","text":"Platform as a service (PaaS)"},{"key":"B","text":"Infrastructure as a service (IaaS)"},{"key":"C","text":"Microsoft SQL Server"},{"key":"D","text":"on-premises"}]'::jsonb, ARRAY['A']::text[], 'Cơ sở dữ liệu Azure cho PostgreSQL là dịch vụ cơ sở dữ liệu PostgreSQL được quản lý hoàn toàn được cung cấp dưới dạng nền tảng dưới dạng dịch vụ (PaaS). Microsoft quản lý nền tảng cơ bản và các tác vụ vận hành, trong khi PostgreSQL được triển khai trên Azure virtual machines là giải pháp thay thế IaaS.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-280', 'dp-900', 280, 'For each of the following statements, select Yes if the statement is true. Otherwise, select No.', '{"statements":[{"id":"1","text":"Online transaction processing (OLTP) relies on a database system where data storage is optimized for both read and write operations.","correctAnswer":"Yes"},{"id":"2","text":"Online analytical processing (OLAP) relies on a database system where data storage is optimized for both read and write operations.","correctAnswer":"No"},{"id":"3","text":"Data warehouses are optimized for read operations.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:Yes']::text[], 'Cơ sở dữ liệu OLTP được thiết kế để đọc và ghi giao dịch khối lượng lớn. Khối lượng công việc OLAP và kho dữ liệu được thiết kế chủ yếu để truy vấn và báo cáo phân tích, trong đó nhấn mạnh đến hiệu suất đọc hơn là hiệu suất ghi giao dịch.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-281', 'dp-900', 281, 'For each statement below, select **Yes** when it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"Azure Databricks is an Apache Spark-based analytics platform.","correctAnswer":"Yes"},{"id":"2","text":"Azure Analysis Services is used for transactional workloads.","correctAnswer":"No"},{"id":"3","text":"Azure Data Factory orchestrates data integration workflows.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:Yes']::text[], 'Azure Databricks là nền tảng phân tích dựa trên Apache Spark. Dịch vụ phân tích Azure hỗ trợ các mô hình dữ liệu ngữ nghĩa và phân tích thông tin doanh nghiệp thay vì khối lượng công việc giao dịch. Azure Data Factory là dịch vụ tích hợp dữ liệu đám mây giúp điều phối các quy trình chuyển đổi và di chuyển dữ liệu.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-282', 'dp-900', 282, 'You need to ensure that users use multi-factor authentication (MFA) when they connect to an Azure SQL database.  
  
Which authentication type should you use?', '[{"key":"A","text":"service principal authentication"},{"key":"B","text":"Azure Active Directory (Azure AD) authentication"},{"key":"C","text":"SQL authentication"},{"key":"D","text":"certificate authentication"}]'::jsonb, ARRAY['B']::text[], 'Xác thực Azure Active Directory (Azure AD) tích hợp đăng nhập Azure SQL Database bằng Microsoft Entra ID, trong đó các chính sách Truy cập có điều kiện có thể yêu cầu xác thực đa yếu tố cho người dùng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-283', 'dp-900', 283, 'Question 283', '[]'::jsonb, ARRAY[]::text[], 'Nhóm SQL chuyên dụng Azure Synapse Analytics sử dụng kiến ​​trúc xử lý song song quy mô lớn để phân phối công việc truy vấn trên các nút điện toán.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-284', 'dp-900', 284, 'For each of the following statements, select Yes if the statement is true. Otherwise, select No.', '{"statements":[{"id":"1","text":"In non-relational databases, data is always stored in tables.","correctAnswer":"No"},{"id":"2","text":"In non-relational databases, data is always stored by using a fixed schema.","correctAnswer":"No"},{"id":"3","text":"In non-relational databases, two entities in the same collection can have different sets of fields.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:No', '3:Yes']::text[], 'Cơ sở dữ liệu phi quan hệ sử dụng nhiều mô hình dữ liệu khác nhau và không giới hạn ở các bảng quan hệ. Chúng thường cho phép các lược đồ linh hoạt, do đó các bản ghi trong cùng một bộ sưu tập có thể chứa các trường khác nhau.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-285', 'dp-900', 285, 'For each statement, select **Yes** when it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"Data engineers identify data governance rules.","correctAnswer":"Yes"},{"id":"2","text":"Data engineers create data ingestion pipelines.","correctAnswer":"Yes"},{"id":"3","text":"Data engineers implement backup and recovery processes for database systems.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:Yes', '3:No']::text[], 'Các kỹ sư dữ liệu xác định các quy tắc quản trị và xây dựng quy trình nhập/tích hợp để di chuyển và chuyển đổi dữ liệu. Sao lưu và phục hồi cơ sở dữ liệu là trách nhiệm quản trị cơ sở dữ liệu cốt lõi chứ không phải là vai trò kỹ thuật dữ liệu.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-286', 'dp-900', 286, 'In what situation can you use an Azure Resource Manager template?', '[{"key":"A","text":"to automate the creation of an interdependent group of Azure resources in a repeatable way"},{"key":"B","text":"to apply Azure policies for multi-tenant deployments"},{"key":"C","text":"to provision Azure subscriptions"},{"key":"D","text":"to control which services and feature administrators and developers can deploy from the Azure portal"}]'::jsonb, ARRAY['A']::text[], 'Các mẫu Trình quản lý tài nguyên Azure cung cấp các triển khai khai báo, lặp lại của tài nguyên Azure và có thể thể hiện sự phụ thuộc giữa các tài nguyên đó để Trình quản lý tài nguyên triển khai chúng theo thứ tự bắt buộc.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-287', 'dp-900', 287, 'Question 287', '[]'::jsonb, ARRAY[]::text[], 'Nhóm đàn hồi Azure SQL Database cung cấp một nhóm tài nguyên lưu trữ và tính toán chung mà nhiều cơ sở dữ liệu có thể sử dụng. Nó dành cho các cơ sở dữ liệu có mô hình sử dụng khác nhau hoặc không thể đoán trước.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-288', 'dp-900', 288, 'Question 288', '[]'::jsonb, ARRAY[]::text[], 'Nhà phân tích dữ liệu xác định các yêu cầu kinh doanh và quy tắc kinh doanh phải chi phối dữ liệu để báo cáo và phân tích phù hợp với nhu cầu của tổ chức.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-289', 'dp-900', 289, 'Match the terms with the correct descriptions.  
  
Each term may be used once, more than once, or not at all.', '{"statements":[{"id":"slot1","text":"A database object that holds data","correctAnswer":"C"},{"id":"slot2","text":"A database object whose content is defined by a query","correctAnswer":"B"},{"id":"slot3","text":"A database object that helps improve the speed of data retrieval","correctAnswer":"A"}],"choices":[{"key":"A","text":"Index"},{"key":"B","text":"View"},{"key":"C","text":"Table"}]}'::jsonb, ARRAY['slot1=C', 'slot2=B', 'slot3=A']::text[], 'Bảng lưu trữ dữ liệu, dạng xem trình bày tập kết quả được xác định bởi truy vấn và chỉ mục cung cấp cấu trúc dữ liệu giúp cơ sở dữ liệu truy xuất dữ liệu hiệu quả hơn.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-290', 'dp-900', 290, 'For each statement below, select **Yes** if it is true; otherwise, select **No**.', '{"statements":[{"id":"1","text":"Stream processing has access to the most recent data received or data within a rolling time window.","correctAnswer":"Yes"},{"id":"2","text":"Batch processing must occur immediately and have latency in the order of seconds or milliseconds.","correctAnswer":"No"},{"id":"3","text":"Stream processing is used for simple response functions, aggregates, or calculations such as rolling averages.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:Yes']::text[], 'Xử lý luồng liên tục xử lý dữ liệu mới đến và hỗ trợ các hoạt động theo khung thời gian như trung bình luân phiên. Quá trình xử lý hàng loạt hoạt động trên dữ liệu được thu thập theo khoảng thời gian hoặc khi có sẵn một lô, do đó, nó không có độ trễ ngay lập tức hoặc độ trễ tính bằng mili giây/giây.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-291', 'dp-900', 291, 'Your company must design a database that shows the relationships between the utilization levels of individual network devices throughout a local area network.  
  
Which type of data store should be used?', '[{"key":"A","text":"graph"},{"key":"B","text":"key/value"},{"key":"C","text":"document"},{"key":"D","text":"columnar"}]'::jsonb, ARRAY['A']::text[], 'Kho lưu trữ dữ liệu biểu đồ mô hình hóa các thiết bị riêng lẻ dưới dạng nút và kết nối mạng của chúng dưới dạng cạnh, đồng thời lưu trữ mức độ sử dụng dưới dạng thuộc tính. Nó được thiết kế để biểu diễn và duyệt qua dữ liệu có mối quan hệ nặng nề, được kết nối một cách hiệu quả. [Microsoft Learn: Graph Database Overview](https://learn.microsoft.com/en-us/fabric/graph/graph-database)', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-292', 'dp-900', 292, 'For each statement below, select **Yes** when it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"Data stored in the Hot access tier of Azure Blob storage is stored on high-performance media.","correctAnswer":"Yes"},{"id":"2","text":"The Cool access tier in Azure Blob storage incurs higher storage costs compared to the Hot access tier.","correctAnswer":"No"},{"id":"3","text":"The Archive access tier in Azure Blob storage has the highest latency of the three available tiers.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:Yes']::text[], 'Hot tier dành cho dữ liệu được truy cập thường xuyên và sử dụng phương tiện hiệu suất cao. Cool tier có chi phí lưu trữ thấp hơn Hot, mặc dù chi phí truy cập cao hơn. Lưu trữ là một cấp độ ngoại tuyến; Việc truy xuất yêu cầu bù nước và có thể mất hàng giờ, mang lại độ trễ cao nhất.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-293', 'dp-900', 293, 'What language is used to write queries in Azure Synapse Data Explorer?', '[{"key":"A","text":"Bash"},{"key":"B","text":"PowerShell"},{"key":"C","text":"KQL"},{"key":"D","text":"SQL"}]'::jsonb, ARRAY['C']::text[], 'Azure Synapse Data Explorer sử dụng Ngôn ngữ truy vấn Kusto (KQL) để truy vấn và phân tích dữ liệu. Tài liệu Azure Synapse Data Explorer của Microsoft đặc biệt bao gồm việc sử dụng truy vấn KQL.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-294', 'dp-900', 294, 'You need to collect real-time telemetry data from a mobile application.  
  
Which workload type describes this scenario?', '[{"key":"A","text":"Online Transaction Processing (OLTP)"},{"key":"B","text":"batch"},{"key":"C","text":"massively parallel processing (MPP)"},{"key":"D","text":"streaming"}]'::jsonb, ARRAY['D']::text[], 'Truyền tải khối lượng công việc trực tiếp và xử lý các sự kiện đến liên tục với độ trễ thấp. Đo từ xa ứng dụng thời gian thực là trường hợp sử dụng truyền phát sự kiện; Microsoft mô tả Trung tâm sự kiện là một nền tảng truyền dữ liệu theo thời gian thực để đo từ xa và ghi nhật ký ứng dụng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-295', 'dp-900', 295, 'What must be enabled to provision Azure Data Lake Storage in an Azure Storage account?', '[{"key":"A","text":"Versioning must be disabled."},{"key":"B","text":"Hierarchical namespace must be disabled."},{"key":"C","text":"Versioning must be enabled."},{"key":"D","text":"Hierarchical namespace must be enabled."}]'::jsonb, ARRAY['D']::text[], 'Các khả năng của Azure Data Lake Storage yêu cầu tài khoản Azure Storage có bật không gian tên phân cấp. Không gian tên này cung cấp hệ thống phân cấp thư mục và ngữ nghĩa hệ thống tệp được Data Lake Storage sử dụng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-296', 'dp-900', 296, 'You are creating a set of SQL queries that administrators will use to troubleshoot an Azure SQL database.  
  
You need to embed documents and query results in a SQL notebook.  
  
What should you use?', '[{"key":"A","text":"Microsoft SQL Server Management Studio (SSMS)"},{"key":"B","text":"Azure Data Studio"},{"key":"C","text":"Azure CLI"},{"key":"D","text":"Azure PowerShell"}]'::jsonb, ARRAY['B']::text[], 'Azure Data Studio hỗ trợ sổ ghi chép SQL kết hợp các ô văn bản Markdown để tạo tài liệu với các ô mã SQL chạy truy vấn và hiển thị nội tuyến kết quả của chúng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-297', 'dp-900', 297, 'Question 297', '[]'::jsonb, ARRAY[]::text[], 'Azure SQL Database sử dụng quy tắc tường lửa cấp máy chủ để kiểm soát địa chỉ IP nào có thể kết nối. Theo mặc định, các kết nối bị chặn cho đến khi quy tắc tường lửa được phép được định cấu hình; NSG, Azure Firewall và Azure Front Door không phải là cơ chế bảo vệ mặc định.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-298', 'dp-900', 298, 'What is one characteristic of non-relational data?', '[{"key":"A","text":"no indexes"},{"key":"B","text":"self-describing entities"},{"key":"C","text":"a well-defined schema"},{"key":"D","text":"no unique key values"}]'::jsonb, ARRAY['B']::text[], 'Dữ liệu phi quan hệ thường sử dụng các thực thể tự mô tả, trong đó mỗi bản ghi hoặc tài liệu có thể mang các thuộc tính riêng của nó và không cần phải tuân theo một lược đồ cứng nhắc, được xác định trước.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-299', 'dp-900', 299, 'You have structured data organized in a tabular format.  
  
What denotes a single instance of a data entity?', '[{"key":"A","text":"a column"},{"key":"B","text":"a table"},{"key":"C","text":"a cell"},{"key":"D","text":"a row"}]'::jsonb, ARRAY['D']::text[], 'Một hàng là một bản ghi đại diện cho một phiên bản riêng lẻ của một thực thể, với các giá trị thuộc tính của nó được lưu trữ trên các cột.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-300', 'dp-900', 300, 'For each of the following statements, select Yes if the statement is true. Otherwise, select No.', '{"statements":[{"id":"1","text":"Platform as a service (PaaS) database offerings in Azure require less setup and configuration effort than infrastructure as a service (IaaS) database offerings.","correctAnswer":"Yes"},{"id":"2","text":"Platform as a service (PaaS) database offerings in Azure provide end users with the ability to control and update the operating system version.","correctAnswer":"No"},{"id":"3","text":"All relation and non-relational platform as a service (PaaS) database offerings in Azure can be paused to reduce costs.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:No']::text[], 'Dịch vụ cơ sở dữ liệu Azure PaaS ủy quyền cơ sở hạ tầng, hệ điều hành, vá lỗi, sao lưu và các công việc quản lý khác cho Microsoft, giảm thiểu việc thiết lập và quản trị so với IaaS. Khách hàng không kiểm soát hoặc cập nhật hệ điều hành cơ bản trong PaaS; Máy ảo IaaS cung cấp khả năng kiểm soát đó. Việc tạm dừng dành riêng cho dịch vụ và cấp độ chứ không phải phổ biến: tính năng tự động tạm dừng Azure SQL Database chỉ khả dụng cho các cấu hình không có máy chủ được hỗ trợ.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-301', 'dp-900', 301, 'For each statement below, select **Yes** if it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"A Microsoft Power BI dashboard is associated with a single workspace.","correctAnswer":"Yes"},{"id":"2","text":"A Microsoft Power BI dashboard can only display visualizations from a single dataset.","correctAnswer":"No"},{"id":"3","text":"A Microsoft Power BI dashboard can display visualizations from a Microsoft Excel workbook.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:Yes']::text[], 'Không gian làm việc Power BI là nơi chứa các bảng thông tin và một bảng thông tin nằm trong một không gian làm việc. Trang tổng quan có thể kết hợp các ô từ nhiều báo cáo và mô hình ngữ nghĩa thay vì bị giới hạn ở một tập dữ liệu. Các lựa chọn sổ làm việc Excel có thể được ghim vào bảng điều khiển Power BI.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-302', 'dp-900', 302, 'You need to recommend a data-store service that meets these requirements:  
  
- Native SQL API access  
- Configurable indexes  
  
What should you recommend?', '[{"key":"A","text":"Azure Files"},{"key":"B","text":"Azure Blob storage"},{"key":"C","text":"Azure Table storage"},{"key":"D","text":"Azure Cosmos DB"}]'::jsonb, ARRAY['D']::text[], 'Azure Cosmos DB hỗ trợ API SQL để truy vấn dữ liệu tài liệu và cho phép mỗi vùng chứa sử dụng chính sách lập chỉ mục có thể tùy chỉnh, bao gồm các đường dẫn thuộc tính được lập chỉ mục và loại trừ. Điều này đáp ứng cả yêu cầu về quyền truy cập API SQL gốc và chỉ mục có thể định cấu hình.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-303', 'dp-900', 303, 'Match the Azure Cosmos DB APIs with the applicable data structures.  
  
An API may be used once, multiple times, or not at all.', '{"statements":[{"id":"graph_data","text":"Graph data","correctAnswer":"B"},{"id":"json_documents","text":"JSON documents","correctAnswer":"C"},{"id":"key_value_data","text":"Key/value data","correctAnswer":"D"}],"choices":[{"key":"A","text":"Cassandra API"},{"key":"B","text":"Gremlin API"},{"key":"C","text":"MongoDB API"},{"key":"D","text":"Table API"}]}'::jsonb, ARRAY['graph_data=B', 'json_documents=C', 'key_value_data=D']::text[], 'API của Azure Cosmos DB dành cho Gremlin lưu trữ các thực thể đồ thị dưới dạng các đỉnh và cạnh. API cho MongoDB của nó sử dụng các thực thể tài liệu và API bảng của nó sử dụng các mục trong bảng có quyền truy cập kiểu khóa/giá trị. API Cassandra là API cột rộng và không khớp với bất kỳ cấu trúc được liệt kê nào.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-304', 'dp-900', 304, 'Question 304', '[]'::jsonb, ARRAY[]::text[], 'Cơ sở dữ liệu quan hệ lưu trữ dữ liệu có cấu trúc trong các bảng (quan hệ), thường sử dụng các hàng, cột và một lược đồ được xác định.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-305', 'dp-900', 305, 'A retail point-of-sale (POS) system is an example of which type of solution?', '[{"key":"A","text":"a data warehouse"},{"key":"B","text":"online analytical processing (OLAP)"},{"key":"C","text":"extract, transform, and load (ETL)"},{"key":"D","text":"online transaction processing (OLTP)"}]'::jsonb, ARRAY['D']::text[], 'Hệ thống xử lý giao dịch trực tuyến (OLTP) xử lý các giao dịch kinh doanh thông thường, theo thời gian thực như bán lẻ và xử lý thanh toán.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-306', 'dp-900', 306, 'Which Azure SQL offering delivers near-100 percent compatibility with on-premises Microsoft SQL Server instances while providing automated updates, backups, and maintenance tasks?', '[{"key":"A","text":"Azure SQL Managed Instance"},{"key":"B","text":"SQL Server on Azure Virtual Machines"},{"key":"C","text":"Azure SQL Database"},{"key":"D","text":"Azure SQL Edge"}]'::jsonb, ARRAY['A']::text[], 'Azure SQL Managed Instance là công cụ cơ sở dữ liệu PaaS được quản lý hoàn toàn với khả năng tương thích tính năng gần như 100% với SQL Server. Nó thực hiện các chức năng quản lý như nâng cấp, vá lỗi, sao lưu và giám sát mà không cần sự tham gia của người dùng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-307', 'dp-900', 307, 'Which statement is an example of Data Manipulation Language (DML)?', '[{"key":"A","text":"INSERT"},{"key":"B","text":"ALTER"},{"key":"C","text":"DROP"},{"key":"D","text":"CREATE"}]'::jsonb, ARRAY['A']::text[], '`INSERT` là câu lệnh Ngôn ngữ thao tác dữ liệu vì nó thêm các hàng dữ liệu vào bảng. `ALTER`, `DROP` và `CREATE` là các câu lệnh Ngôn ngữ Định nghĩa Dữ liệu.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-308', 'dp-900', 308, 'Question 308', '[]'::jsonb, ARRAY[]::text[], 'Biểu đồ tán xạ vẽ các quan sát số theo cặp trên hai trục, làm cho mối quan hệ và mối tương quan giữa các thước đo có thể nhìn thấy được.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-309', 'dp-900', 309, 'Question 309', '[]'::jsonb, ARRAY[]::text[], 'Hệ thống cơ sở dữ liệu quan hệ hỗ trợ các giao dịch ACID và tính nhất quán giao dịch mạnh mẽ, khiến chúng phù hợp với khối lượng công việc ghi giao dịch có khối lượng lớn.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-310', 'dp-900', 310, 'Question 310', '[]'::jsonb, ARRAY[]::text[], 'Chỉ có thể tạo bảng thông tin Power BI trong dịch vụ Power BI. Power BI Desktop tạo báo cáo, trong khi ứng dụng di động Power BI hỗ trợ xem và chia sẻ trang tổng quan thay vì tạo chúng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-311', 'dp-900', 311, 'Which storage solution supports role-based access control (RBAC) at the file and folder levels?', '[{"key":"A","text":"Azure Disk Storage"},{"key":"B","text":"Azure Data Lake Storage"},{"key":"C","text":"Azure Blob storage"},{"key":"D","text":"Azure Queue storage"}]'::jsonb, ARRAY['B']::text[], 'Azure Data Lake Storage hỗ trợ mô hình ủy quyền kết hợp Azure RBAC với danh sách kiểm soát truy cập (ACL) giống POSIX. RBAC có thể cấp quyền truy cập vào tài khoản lưu trữ hoặc vùng chứa và ACL cung cấp các quyền chi tiết cho từng thư mục và tệp riêng lẻ.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-312', 'dp-900', 312, 'You have an Azure Cosmos DB account that uses the Core (SQL) API.  
  
Which two settings can be configured at the container level? Each correct answer provides a complete solution.  
  
NOTE: Each correct selection is worth one point.', '[{"key":"A","text":"the throughput"},{"key":"B","text":"the read region"},{"key":"C","text":"the partition key"},{"key":"D","text":"the API"}]'::jsonb, ARRAY['A', 'C']::text[], 'Vùng chứa Azure Cosmos DB yêu cầu khóa phân vùng để phân phối các mục của nó trên các phân vùng và thông lượng có thể được cung cấp trực tiếp trên một vùng chứa riêng lẻ. Vùng đọc và API đã chọn là cài đặt cấp tài khoản.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-313', 'dp-900', 313, 'You have a table named Sales containing the following data.  
  
![Question Image](https://cdn.examcademy.com/images/questions/1783766659846-9x1hiqdr.png)  
  
You need to query the table to return the average sales amount for each day. The output must return the following results.  
  
![Question Image](https://cdn.examcademy.com/images/questions/1783766662796-hzfad5dd.png)  
  
Complete the query. Each value may be used once, more than once, or not at all.', '{"statements":[{"id":"clause1","text":"Slot 1:","correctAnswer":"D"},{"id":"clause2","text":"Slot 2:","correctAnswer":"B"}],"choices":[{"key":"A","text":"CREATE"},{"key":"B","text":"GROUP BY"},{"key":"C","text":"ORDER BY"},{"key":"D","text":"SELECT"}]}'::jsonb, ARRAY['clause1=D', 'clause2=B']::text[], 'SELECT trả về ngày và AVG(SalesAmount). NHÓM THEO Ngày bán hàng tạo thành một nhóm tổng hợp cho mỗi ngày, tạo ra số liệu trung bình hàng ngày được yêu cầu; ĐẶT HÀNG THEO SalesDate sắp xếp các nhóm đó theo thứ tự thời gian.', 'General', ARRAY['DP-900', 'General']::text[], 'https://cdn.examcademy.com/images/questions/1783766659846-9x1hiqdr.png', 'published'),
  ('dp900-314', 'dp-900', 314, 'For each statement below, select **Yes** when it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"Azure SQL Database has all the same features as SQL Server on Azure Virtual Machines.","correctAnswer":"No"},{"id":"2","text":"In a platform as a service (PaaS) model, before you deploy a relational database, you must create a virtual machine and a virtual network.","correctAnswer":"No"},{"id":"3","text":"In an infrastructure as a service (IaaS) model, before you deploy a relational database, you must create a virtual machine and a virtual network.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:No', '3:Yes']::text[], 'Azure SQL Database là dịch vụ cơ sở dữ liệu PaaS được quản lý, không phải là phiên bản SQL Server đầy đủ trên máy ảo do khách hàng quản lý, do đó bộ tính năng của nó không giống với SQL Server trên máy ảo Azure. PaaS loại bỏ nhu cầu cung cấp máy ảo và mạng ảo cơ bản trước khi tạo cơ sở dữ liệu. IaaS đặt SQL Server trên máy ảo Azure và máy ảo yêu cầu cấu hình mạng ảo.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-315', 'dp-900', 315, 'HOTSPOT — Select the appropriate option in the answer area to complete the sentence.', '[]'::jsonb, ARRAY[]::text[], 'Azure Cosmos DB dành cho NoSQL (Core [SQL]) hỗ trợ ngôn ngữ truy vấn Cosmos DB SQL. Mệnh đề SELECT của nó truy xuất và chiếu các trường hoặc giá trị từ tài liệu JSON.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-316', 'dp-900', 316, 'Question 316', '[]'::jsonb, ARRAY[]::text[], 'Một bảng thực thể có một tập hợp các cột nhất quán cho tất cả các bản ghi. Việc thêm một thuộc tính sẽ thay đổi lược đồ bảng bằng cách thêm một cột; các bản ghi thiếu giá trị cho thuộc tính đó có thể sử dụng giá trị rỗng hoặc trống.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-317', 'dp-900', 317, 'Your company is designing a data store for internet-connected temperature sensors. The gathered data will be used to analyze temperature trends. Which type of data store should be used?', '[{"key":"A","text":"relational"},{"key":"B","text":"time series"},{"key":"C","text":"graph"},{"key":"D","text":"columnar"}]'::jsonb, ARRAY['B']::text[], 'Kho lưu trữ dữ liệu chuỗi thời gian được thiết kế để phục vụ các phép đo theo dấu thời gian như đọc nhiệt độ và hỗ trợ phân tích xu hướng hiệu quả theo thời gian.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-318', 'dp-900', 318, 'Match the data-store types with the appropriate scenarios. Each data-store type can be used once, more than once, or not at all.', '{"statements":[{"id":"slot1","text":"A list of application user names and, for each, the default language","correctAnswer":"C"},{"id":"slot2","text":"A collection of medical images and their associated metadata.","correctAnswer":"B"},{"id":"slot3","text":"Employee data that shows the relationships between employees","correctAnswer":"A"}],"choices":[{"key":"A","text":"Graph"},{"key":"B","text":"Object"},{"key":"C","text":"Key/value"}]}'::jsonb, ARRAY['slot1=C', 'slot2=B', 'slot3=A']::text[], 'Kho lưu trữ khóa/giá trị truy xuất hiệu quả ngôn ngữ mặc định của người dùng bằng khóa tên người dùng. Lưu trữ đối tượng và tệp được thiết kế cho các tệp nhị phân lớn có siêu dữ liệu, bao gồm cả hình ảnh y tế. Cửa hàng đồ thị biểu diễn nhân viên dưới dạng các nút và mối quan hệ của họ dưới dạng các cạnh.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-319', 'dp-900', 319, 'Which three objects can be added to a Microsoft Power BI dashboard? Each correct answer provides a complete solution.  
  
**NOTE:** Each correct selection is worth one point.', '[{"key":"A","text":"a report page"},{"key":"B","text":"a Microsoft PowerPoint slide"},{"key":"C","text":"a visualization from a report"},{"key":"D","text":"a dataflow"},{"key":"E","text":"a text box"}]'::jsonb, ARRAY['A', 'C', 'E']::text[], 'Trang tổng quan Power BI có thể bao gồm trang báo cáo trực tiếp, các hình ảnh trực quan riêng lẻ được ghim từ báo cáo và các hộp văn bản được thêm dưới dạng ô trang tổng quan. Các trang chiếu và luồng dữ liệu PowerPoint không phải là các đối tượng ô bảng thông tin được hỗ trợ.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-320', 'dp-900', 320, 'For each statement below, select **Yes** when it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"You can use Azure Data Studio to query a Microsoft SQL Server big data cluster.","correctAnswer":"Yes"},{"id":"2","text":"You can use Microsoft SQL Server Management Studio (SSMS) to query an Azure Synapse Analytics data warehouse.","correctAnswer":"Yes"},{"id":"3","text":"You can use MySQL Workbench to query Azure Database for MariaDB databases.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:Yes', '3:Yes']::text[], 'Azure Data Studio hỗ trợ truy vấn cụm dữ liệu lớn SQL Server. SSMS có thể kết nối và truy vấn các nhóm SQL chuyên dụng của Azure Synapse (kho dữ liệu). MySQL Workbench là ứng dụng khách MySQL tương thích với Cơ sở dữ liệu Azure dành cho MariaDB.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-321', 'dp-900', 321, 'Question 321', '[]'::jsonb, ARRAY[]::text[], 'Phân tích nhận thức áp dụng các khả năng của AI như nhận dạng giọng nói cho âm thanh phi cấu trúc, cho phép nó được chuyển thành văn bản.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-322', 'dp-900', 322, 'You need to query a table named **Products** in an Azure SQL database.  
  
Which three requirements must be satisfied to query the table from the internet? Each correct answer is part of the solution.  
  
**NOTE:** Each correct selection is worth one point.', '[{"key":"A","text":"You must be assigned the Reader role for the resource group that contains the database."},{"key":"B","text":"You must have SELECT access to the Products table."},{"key":"C","text":"You must have a user in the database."},{"key":"D","text":"You must be assigned the Contributor role for the resource group that contains the database."},{"key":"E","text":"Your IP address must be allowed to connect to the database."}]'::jsonb, ARRAY['B', 'C', 'E']::text[], 'Máy khách kết nối từ internet phải có địa chỉ IP được tường lửa Azure SQL Database cho phép. Hiệu trưởng được xác thực cần một người dùng cơ sở dữ liệu để kết nối và được ủy quyền trong cơ sở dữ liệu và nó phải có quyền `SELECT` trên bảng `Products` (trực tiếp hoặc thông qua một vai trò). Vai trò Người đọc và Người đóng góp trong nhóm tài nguyên Azure kiểm soát quyền truy cập vào mặt phẳng quản lý và không cấp quyền truy vấn dữ liệu bảng.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published'),
  ('dp900-323', 'dp-900', 323, 'Question 323', '[]'::jsonb, ARRAY[]::text[], 'Cơ sở dữ liệu quan hệ lưu trữ dữ liệu trong các bảng được xác định trước với các hàng, cột, mối quan hệ và lược đồ được xác định, làm cho chúng phù hợp với dữ liệu có cấu trúc.', 'General', ARRAY['DP-900', 'General']::text[], NULL, 'published')
